/* Nederlandse parafrases naar The Daily Stoic, Ryan Holiday & Stephen Hanselman. */
window.MementoStoicDays = {
  "01-01": {"dateKey": "01-01", "day": 1, "month": 1, "sourceTitle": "CONTROL AND CHOICE", "thinker": "Epictetus", "thoughtNl": "Besteed je aandacht aan keuzes die je vandaag kunt maken, ook wanneer je de omstandigheden niet kunt veranderen.", "explanationNl": "Een storm houdt een vliegtuig aan de grond, hoe boos een reiziger zich ook maakt. Volgens de auteurs kost verzet tegen zo’n vaststaand gegeven aandacht die je kunt gebruiken voor beslissingen die nog openliggen. Ze herkennen dat onderscheid in het gebed om kalmte uit de herstelwereld. Iemand kan vroeger aangedaan leed en eigen misstappen onmogelijk terugdraaien. De keuze die nu voorligt kan wel richting geven aan wat er volgt.", "reflectionNl": "Welke situatie kost je vandaag energie terwijl jouw eerstvolgende beslissing nog openstaat?", "exerciseNl": "Schrijf bij één frustratie op wat vaststaat en welke stap je zelf kunt zetten.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "01-02": {"dateKey": "01-02", "day": 2, "month": 1, "sourceTitle": "EDUCATION IS FREEDOM", "thinker": "Epictetus", "thoughtNl": "Kennis helpt je vrijer te leven wanneer je wat je leest gebruikt om jezelf beter te leren kennen.", "explanationNl": "De auteurs zien filosofie lezen als oefenen in leven. Misschien pak je een boek omdat je met minder angst wilt leven of meer rust zoekt. Dan telt wat het denken van anderen je leert over je eigen keuzes. Dat doel is gemakkelijk uit het oog te verliezen op een dag waarop afleiding aantrekkelijker lijkt dan studie. Onthoud op zulke momenten wat je ermee hoopt te bereiken. Vooral zelfkennis vergroot je vrijheid.", "reflectionNl": "Wat wilde je leren toen je begon aan een boek dat nu ongelezen blijft liggen?", "exerciseNl": "Lees één alinea en noteer welk gedrag die je beter laat begrijpen.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "01-03": {"dateKey": "01-03", "day": 3, "month": 1, "sourceTitle": "BE RUTHLESS TO THE THINGS THAT DON’T MATTER", "thinker": "Seneca", "thoughtNl": "Elke afwijzing van iets wat weinig voor je betekent maakt ruimte voor een keuze die je wél wilt maken.", "explanationNl": "De auteurs merken op dat een uitnodiging weigeren lastig kan zijn, vooral als anderen die vanzelfsprekend vinden. Ook boosheid, afleiding en obsessie kunnen je tijd opeisen. Los lijken die impulsen klein, maar samen kunnen ze evenveel beslag op je leggen als een agenda vol afspraken. Grenzen stellen kan moeite kosten en anderen teleurstellen. Wie daarmee oefent, houdt meer tijd over om bewust te kiezen hoe die wil leven en waarvan die wil genieten.", "reflectionNl": "Welk verzoek zou je vandaag afslaan als je eerst keek naar wat ervoor moet wijken?", "exerciseNl": "Schrijf één vriendelijke, korte afwijzing voor een verplichting die je kunt laten vallen.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "01-04": {"dateKey": "01-04", "day": 4, "month": 1, "sourceTitle": "THE BIG THREE", "thinker": "Marcus Aurelius", "thoughtNl": "Onderzoek hoe je iets ziet, kies hoe je handelt en aanvaard wat je buiten jouw invloed aantreft.", "explanationNl": "De drie disciplines die de auteurs hier uitlichten vormen ook de indeling van het boek. Ze overlappen in de praktijk. Je kunt bij dezelfde beslissing onderzoeken of je waarneming klopt, je handeling zorgvuldig kiezen en bereid zijn de omstandigheden te aanvaarden die je niet kunt bepalen. De opvattingen van afzonderlijke filosofen kunnen interessant zijn. Voor de helderheid in een gewone werkdag bieden deze drie vragen een kortere weg van filosofie naar handelen.", "reflectionNl": "Bij welke beslissing van vandaag kun je oordeel, handelen en aanvaarden elk een eigen plaats geven?", "exerciseNl": "Neem één aankomende beslissing en schrijf bij elk van de drie disciplines één zin.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "01-05": {"dateKey": "01-05", "day": 5, "month": 1, "sourceTitle": "CLARIFY YOUR INTENTIONS", "thinker": "Seneca", "thoughtNl": "Een helder doel helpt je kiezen welke inspanning vandaag zin heeft en wanneer je onderweg moet bijsturen.", "explanationNl": "Robert Greene en Stephen Covey worden aangehaald omdat zij allebei het belang van een eindpunt benadrukken. De uitkomst blijft volgens de auteurs onzeker. Een doel geeft je intussen een maatstaf voor dagelijkse keuzes. Zonder maatstaf is het moeilijk te bepalen welke verzoeken je kunt weigeren, wanneer je afwijkt en wanneer je genoeg hebt gedaan. De auteurs verbinden die richtingloosheid met de verwarring die volgens de stoïcijnen uit verkeerde opvattingen voortkomt.", "reflectionNl": "Hoe weet je aan het einde van vandaag dat een taak goed genoeg is afgerond?", "exerciseNl": "Omschrijf het gewenste resultaat van één taak voordat je eraan begint.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "01-06": {"dateKey": "01-06", "day": 6, "month": 1, "sourceTitle": "WHERE, WHO, WHAT, AND WHY", "thinker": "Marcus Aurelius", "thoughtNl": "Neem de tijd om te bepalen wie je bent en waar je voor staat wanneer je gebruikelijke antwoorden wegvallen.", "explanationNl": "Een radiopresentator vroeg komiek Mitch Hedberg wie hij eigenlijk was. Die vroeg zich af of het een diepe vraag was of dat hij bij het verkeerde station zat. De auteurs gebruiken het verhaal om te laten zien hoe gemakkelijk we zulke vragen oppervlakkig beantwoorden. Een functie of woonplaats vertellen gaat snel. Bedenken welke overtuigingen je sturen en welke voorbeelden je volgt vraagt meer aandacht. Daar zit ook de kans te ontdekken of je huidige richting voldoening geeft.", "reflectionNl": "Wat zou iemand uit jouw keuzes kunnen afleiden over waar jij voor staat?", "exerciseNl": "Beantwoord voor jezelf in drie zinnen de vraag wie je bent, zonder je beroep te noemen.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "01-07": {"dateKey": "01-07", "day": 7, "month": 1, "sourceTitle": "SEVEN CLEAR FUNCTIONS OF THE MIND", "thinker": "Epictetus", "thoughtNl": "Geef je aandacht aan weloverwogen keuzes, voorbereiding en het herkennen van wat wel en niet in je macht ligt.", "explanationNl": "De auteurs werken zeven taken uit die Epictetus aan de geest toeschrijft. Kies hoe je denkt en handelt, weiger verleiding, verlang naar verbetering en wijs slechte invloeden en onwaarheden af. Bereid je voor op wat zich kan aandienen en houd een leidend beginsel voor ogen. Onderzoek ten slotte of je beeld klopt van wat je zelf in de hand hebt en aanvaard de grens daarvan. Samen geven die taken richting aan je aandacht.", "reflectionNl": "Welke van de zeven taken van de geest zou je helpen bij het eerstvolgende lastige besluit?", "exerciseNl": "Kies één taak en noteer in welke situatie je die vandaag wilt toepassen.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "01-08": {"dateKey": "01-08", "day": 8, "month": 1, "sourceTitle": "SEEING OUR ADDICTIONS", "thinker": "Seneca", "thoughtNl": "Een gewoonte verdient aandacht zodra je merkt dat je moeite hebt om haar één keer over te slaan.", "explanationNl": "Koffie drinken en werkmail lezen beginnen als heel gewone handelingen. De auteurs beschrijven hoe zulke gewoontes zich kunnen opdringen totdat iemand automatisch grijpt naar wat eerder een keuze was. De drang maakt het moeilijker om helder te zien hoeveel ruimte je nog hebt om anders te handelen. Voor de een gaat het om voortdurend kijken op een telefoon, voor de ander om roddelen of klagen. De vrijheid om soms af te zien van een gewoonte verdient oefening.", "reflectionNl": "Welke gewoonte merk je meestal pas op nadat je ermee begonnen bent?", "exerciseNl": "Kies een onschuldige gewoonte en wacht één keer een paar minuten voordat je eraan toegeeft.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "01-09": {"dateKey": "01-09", "day": 9, "month": 1, "sourceTitle": "WHAT WE CONTROL AND WHAT WE DON’T", "thinker": "Epictetus", "thoughtNl": "Wat er vandaag gebeurt ligt vaak buiten je macht, maar je kunt onderzoeken welk oordeel je eraan verbindt.", "explanationNl": "De auteurs houden het onderscheid van Epictetus dicht bij de dagelijkse ervaring. Het kan onrustig maken om te beseffen hoeveel toeval en hoeveel beslissingen van anderen jouw dag beïnvloeden. Bij elke gebeurtenis blijft er wel een eigen oordeel om te onderzoeken. Je kunt nagaan waarom je iets bijvoorbeeld oneerlijk of ongunstig noemt. Dat geeft je genoeg om mee te werken wanneer je neiging juist is om je invloed op de wereld buiten jezelf uit te breiden.", "reflectionNl": "Welk oordeel over iets dat vandaag gebeurde nam je meteen voor waar aan?", "exerciseNl": "Schrijf één gebeurtenis en je eerste oordeel erover op aparte regels.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "01-10": {"dateKey": "01-10", "day": 10, "month": 1, "sourceTitle": "IF YOU WANT TO BE STEADY", "thinker": "Epictetus", "thoughtNl": "Oefen je oordeel zorgvuldig, zodat verwarrende gebeurtenissen je minder snel uit evenwicht brengen.", "explanationNl": "Rust is volgens de auteurs een vaardigheid. Wanneer gebeurtenissen rommelig of overweldigend lijken, helpt je verstand om te ordenen wat je ziet. Een onzorgvuldig oordeel werkt door in alles wat erna komt, inclusief de besluiten die je onder druk neemt. De stabiliteit waarnaar de stoïcijnen zoeken ontstaat daarom vooral in hoe ze gebeurtenissen beoordelen. Een stille omgeving of een gunstige dag kan prettig zijn, maar biedt die geoefende helderheid op zichzelf nauwelijks.", "reflectionNl": "Bij welke lastige situatie van vandaag zou een preciezer oordeel je eerste reactie veranderen?", "exerciseNl": "Benoem bij één verwarrende gebeurtenis eerst wat je zeker weet.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "01-11": {"dateKey": "01-11", "day": 11, "month": 1, "sourceTitle": "IF YOU WANT TO BE UNSTEADY", "thinker": "Epictetus", "thoughtNl": "Je kunt ook midden in een drukke dag rust vinden door te oefenen met de oordelen die je onrustig maken.", "explanationNl": "De auteurs stellen zich stoïcijnse rust voor tussen mensen op de markt, tijdens het werk of bij iemand die ongerust op een naaste wacht. Dat zijn plekken waar de dagelijkse verstoringen aanwezig blijven. Wie ze allemaal probeert te ontlopen, neemt volgens Epictetus de eigen oordelen mee naar de volgende plek. Je kunt leren zulke oordelen te herkennen en bij te stellen. Zo wordt kalmte iets wat je ook in een onrustige omgeving kunt oefenen.", "reflectionNl": "Welk oordeel over je omgeving zou je op een andere plek waarschijnlijk meenemen?", "exerciseNl": "Merk in een drukke ruimte één gedachte op die je extra onrust bezorgt.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "01-12": {"dateKey": "01-12", "day": 12, "month": 1, "sourceTitle": "THE ONE PATH TO SERENITY", "thinker": "Epictetus", "thoughtNl": "Keer op verschillende momenten van de dag terug naar wat je zelf kunt kiezen en wat je moet laten gebeuren.", "explanationNl": "De auteurs stellen voor om het onderscheid tussen keuze en omstandigheden de hele dag opnieuw te maken. Begin bij wat je deze ochtend kunt beïnvloeden en herinner je later aan je vermogen om je verstand en oordeel te gebruiken. In de middag kun je nagaan welk deel van het verloop je moet laten gebeuren. Voor het slapen gaan krijgt die oefening een vertrouwde vorm. Bij het inslapen vertrouw je je al toe aan iets waarover je de controle loslaat.", "reflectionNl": "Op welk terugkerend moment van je dag raak je het onderscheid tussen keuze en uitkomst kwijt?", "exerciseNl": "Koppel aan twee gewone momenten vandaag een korte pauze om je eerstvolgende keuze te bepalen.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "01-13": {"dateKey": "01-13", "day": 13, "month": 1, "sourceTitle": "CIRCLE OF CONTROL", "thinker": "Epictetus", "thoughtNl": "Je lichaam en je omstandigheden kunnen veranderen buiten je wil om. Richt je op de keuzes die je zelf maakt.", "explanationNl": "De auteurs omschrijven de cirkel van controle klein. Zelfs je lichaam kan worden getroffen door ziekte of letsel zonder dat je dat hebt gekozen. Een reiziger kan in omstandigheden belanden die een ander bepaalt. In het midden van die onzekerheid staan je eigen geest, wil en keuzes. Volgens de auteurs kan het opluchten die grens scherp te trekken. Je hoeft minder zaken als persoonlijke verantwoordelijkheid te behandelen en kunt zorgvuldiger omgaan met wat je beslist.", "reflectionNl": "Voor welke uitkomst houd je jezelf verantwoordelijk terwijl je alleen jouw aandeel kunt bepalen?", "exerciseNl": "Verklein bij één zorg je takenlijst tot de keuze die vandaag van jou is.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "01-14": {"dateKey": "01-14", "day": 14, "month": 1, "sourceTitle": "CUT THE STRINGS THAT PULL YOUR MIND", "thinker": "Marcus Aurelius", "thoughtNl": "Merk op wat aan je aandacht trekt en kies bewust wat voor jou belangrijk genoeg is om te volgen.", "explanationNl": "Apps, voedselproducten en nieuws zijn volgens de auteurs vaak ontworpen om je aandacht of geld vast te houden. In de tijd van Marcus Aurelius waren er andere prikkels, zoals roddels, werk, angst en achterdocht. De oefening begint met opmerken waaraan je gehoor geeft. Ze halen Viktor Frankl aan om te laten zien hoe waarden richting kunnen geven wanneer impulsen aan je trekken. Voor dat onderscheid zijn oplettendheid en enige inspanning nodig.", "reflectionNl": "Wat trok vandaag het vaakst aan je aandacht en hoe belangrijk vind je dat zelf?", "exerciseNl": "Kies één melding die je telkens afleidt en zet haar voor vandaag stil.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "01-15": {"dateKey": "01-15", "day": 15, "month": 1, "sourceTitle": "PEACE IS IN STAYING THE COURSE", "thinker": "Seneca", "thoughtNl": "Een gekozen richting geeft rust, ook als je onderweg iets moet aanpassen of anderen een ander pad volgen.", "explanationNl": "De auteurs leggen Seneca’s begrip van innerlijke rust uit als vertrouwen dat je in grote lijnen de juiste weg volgt. Volledige zekerheid hoort daar nauwelijks bij. Nieuwe informatie kan aanleiding geven om bij te sturen. Het verschil zit in de reden waarom je van richting verandert. Wanneer je je steeds vergelijkt met iedereen die een andere kant opgaat, verlies je gemakkelijk het doel uit het oog dat je eerder bewust hebt gekozen.", "reflectionNl": "Welke verandering overweeg je vooral doordat iemand anders zijn leven anders heeft ingericht?", "exerciseNl": "Schrijf bij één doel op waarom het voor jou nog steeds de moeite waard is.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "01-16": {"dateKey": "01-16", "day": 16, "month": 1, "sourceTitle": "NEVER DO ANYTHING OUT OF HABIT", "thinker": "Musonius Rufus", "thoughtNl": "Vraag bij een vaste routine welke reden je vandaag nog hebt om het precies zo te doen.", "explanationNl": "Een werknemer die een werkwijze alleen verdedigt omdat die altijd is gevolgd, laat volgens de auteurs zien hoe routine zelfstandig denken kan vervangen. In een bedrijf maakt dat het moeilijk om betere werkwijzen op te merken. Dezelfde vraag mag je daarom op je eigen gewoontes toepassen. Filosofie helpt om zichtbaar te maken wat je op automatische piloot doet. Kijk of de aanpak nog het beste werkt en of je haar bewust kunt verantwoorden.", "reflectionNl": "Welke werkwijze zou je lastig kunnen uitleggen aan iemand die haar voor het eerst ziet?", "exerciseNl": "Doorloop één vaste routine en bedenk bij één stap waarom je die zo uitvoert.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "01-17": {"dateKey": "01-17", "day": 17, "month": 1, "sourceTitle": "REBOOT THE REAL WORK", "thinker": "Epictetus", "thoughtNl": "Een halve poging biedt een excuus voor mislukking. Geef wat ertoe doet de kans van een echte start.", "explanationNl": "De auteurs herinneren aan de neiging om op school ergens weinig moeite voor te doen als je vreest dat het mislukt. Dan kun je jezelf wijsmaken dat de uitkomst weinig zegt over je vermogen. Later raken vergelijkbare uitvluchten aan de kwaliteit van je leven en aan hoe je met de wereld omgaat. Dat kan intimiderend voelen. De auteurs wijzen op wat je van filosofen kunt leren en vragen voor vandaag één ding van je: begin aan het werk.", "reflectionNl": "Bij welke taak beschermt een halve poging je tegen ontdekken hoe een serieuze poging uitpakt?", "exerciseNl": "Doe vandaag tien minuten geconcentreerd werk aan één taak waar je steeds omheen draait.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "01-18": {"dateKey": "01-18", "day": 18, "month": 1, "sourceTitle": "SEE THE WORLD LIKE A POET AND AN ARTIST", "thinker": "Marcus Aurelius", "thoughtNl": "Kijk aandachtig naar gewone dingen. Een kunstenaarsblik kan je samenhang laten zien waar je eerst alleen gebreken opmerkte.", "explanationNl": "Marcus schreef voor zichzelf en gebruikte verrassend beeldende taal. De auteurs verbinden dat met zijn opleiding bij de redenaar Marcus Cornelius Fronto. De beelden laten zien hoe een andere manier van kijken het alledaagse kan verrijken. Een rijpe vrucht die van haar boom valt kan iets zichtbaar maken over het levenseinde. De barsten in een brood kunnen de eetlust juist aanwakkeren. Zulke details helpen je schoonheid en samenhang te vinden die je anders voorbij zou lopen.", "reflectionNl": "Welk gewoon detail zag je vandaag ineens anders toen je er langer naar keek?", "exerciseNl": "Kies iets wat je dagelijks ziet en beschrijf één detail alsof je het voor het eerst opmerkt.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "01-19": {"dateKey": "01-19", "day": 19, "month": 1, "sourceTitle": "WHEREVER YOU GO, THERE YOUR CHOICE IS", "thinker": "Epictetus", "thoughtNl": "Je omstandigheden kunnen sterk verbeteren of verslechteren. In allebei blijft er een keuze die je zelf kunt maken.", "explanationNl": "De auteurs wijzen op de uiteenlopende posities die stoïcijnen in hun samenleving innamen, van voorrecht tot omstandigheden die moeilijk te bevatten zijn. Ook binnen één leven kan voorspoed afwisselen met zware perioden. Zelfs succes kan op een zeker moment een last worden. In al die situaties blijft volgens Epictetus de vraag wat er aan jou is om te beslissen. Helderheid begint wanneer je die keuze herkent, afweegt en zo goed mogelijk gebruikt.", "reflectionNl": "Welke keuze heb je zowel op een goede als op een slechte dag in handen?", "exerciseNl": "Kies één moeilijk moment en schrijf op welke beslissing van jou blijft als de uitkomst tegenvalt.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "01-20": {"dateKey": "01-20", "day": 20, "month": 1, "sourceTitle": "REIGNITE YOUR THOUGHTS", "thinker": "Marcus Aurelius", "thoughtNl": "Ook na weken waarin je van je principes afdreef, kun je er in je volgende keuze naar terugkeren.", "explanationNl": "Een periode waarin je handelt op een manier waar je later van baalt, hoeft volgens de auteurs weinig te zeggen over wat er nu mogelijk is. Ze vermoeden dat Marcus Aurelius de herinnering ook voor zichzelf nodig had en noemen lastige senatoren of spanningen rond zijn zoon als mogelijke aanleidingen. De omstandigheden van het moment kennen we niet. Hun punt is dat principes beschikbaar blijven, zelfs wanneer je er vijf minuten geleden vanaf week.", "reflectionNl": "Aan welk principe zou je vandaag opnieuw vorm geven als je één eerdere misstap even liet rusten?", "exerciseNl": "Kies één overtuiging die je belangrijk vindt en breng haar bij de eerstvolgende kleine beslissing in praktijk.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "01-21": {"dateKey": "01-21", "day": 21, "month": 1, "sourceTitle": "A MORNING RITUAL", "thinker": "Epictetus", "thoughtNl": "Maak elke ochtend even tijd om te onderzoeken hoe je denkt en handelt. De vorm mag bij je passen.", "explanationNl": "De auteurs noemen meditatie, lichaamsbeweging en dagboekschrijven als mogelijke ochtendrituelen. Hun waarde zit hier in de tijd die je reserveert om naar jezelf te kijken. Van Marcus Aurelius weten we volgens de auteurs vooral dat hij zulke momenten voor zichzelf vrijmaakte. Het precieze tijdstip is onbekend. Zijn voorbeeld en de vragen van Epictetus helpen je een eigen ritueel te beginnen. Door terug te komen op lastige vragen kun je je antwoorden geleidelijk verbeteren.", "reflectionNl": "Welke vraag wil je morgenochtend eerlijk beantwoorden voordat je opgaat in de dag?", "exerciseNl": "Plan vlak na het opstaan twee minuten voor één terugkerende vraag aan jezelf.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "01-22": {"dateKey": "01-22", "day": 22, "month": 1, "sourceTitle": "THE DAY IN REVIEW", "thinker": "Seneca", "thoughtNl": "Schrijf aan het einde van de dag eerlijk op wat je deed en wat je morgen anders kunt aanpakken.", "explanationNl": "Seneca nam van een andere filosoof de gewoonte over zijn dag te onderzoeken. De auteurs noemen vragen naar rechtvaardigheid, verbetering en gewoontes die hij wist te beteugelen. Bij de aantekeningen van Marcus Aurelius herkennen ze hetzelfde streven naar persoonlijke helderheid. Schrijven maakt de terugblik zelf tot een oefening. Wie gebeurtenissen bewust terughaalt en opschrijft wat hielp, wat tegenwerkte en wat beter kan, onthoudt zijn inzichten makkelijker en kan na verloop van tijd veranderingen opmerken.", "reflectionNl": "Bij welk moment van vandaag zou je morgen op een andere manier willen reageren?", "exerciseNl": "Schrijf vanavond één keuze op die goed uitpakte en één verandering voor morgen.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "01-23": {"dateKey": "01-23", "day": 23, "month": 1, "sourceTitle": "THE TRUTH ABOUT MONEY", "thinker": "Seneca", "thoughtNl": "Geld verandert je mogelijkheden. Onderzoek welke innerlijke kwestie je hoopt op te lossen zodra je denkt dat meer geld genoeg zal zijn.", "explanationNl": "De auteurs zetten Fitzgeralds fascinatie voor rijke mensen naast Hemingways droge opmerking dat ze vooral meer geld hebben. Seneca kende rijkdom van dichtbij. Vanuit dat perspectief zien de auteurs hoe gemakkelijk mensen geld een vermogen toeschrijven dat het nauwelijks heeft. Materiële middelen kunnen omstandigheden veranderen, maar de onrust waarvoor je een uitweg zoekt kan intussen bij je blijven. De veronderstelling dat een welvarend leven innerlijk fundamenteel anders is, kan tot een pijnlijke desillusie leiden.", "reflectionNl": "Welk gevoel verwacht je van een aankoop terwijl je waarschijnlijk ook op een andere manier aan dat gevoel kunt werken?", "exerciseNl": "Schrijf bij één gewenste aankoop op welk praktisch probleem ze oplost en welk gevoel je ervan verwacht.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "01-24": {"dateKey": "01-24", "day": 24, "month": 1, "sourceTitle": "PUSH FOR DEEP UNDERSTANDING", "thinker": "Marcus Aurelius", "thoughtNl": "Lees langzaam genoeg om een idee te onderzoeken en aandachtig genoeg om wat standhoudt mee te nemen in je leven.", "explanationNl": "Marcus Aurelius bedankt zijn leraar Rusticus voor zijn invloed op de manier waarop hij leerde. Rusticus leende hem zijn exemplaar van de gesprekken van Epictetus. Volgens de auteurs nam Marcus de lessen pas echt over nadat hij ze grondig had gewogen. Ze boden hem later houvast, ook toen hij over veel macht en luxe beschikte. De auteurs verbinden zijn voorbeeld aan hun eigen opzet van één pagina per dag. Die geeft ruimte om iets goed te lezen.", "reflectionNl": "Welk idee heb je onlangs aangenomen omdat je iemand vertrouwde, terwijl je het zelf nog zou kunnen onderzoeken?", "exerciseNl": "Herlees één passage en leg in je eigen woorden uit waarom je de gedachte overtuigend vindt.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "01-25": {"dateKey": "01-25", "day": 25, "month": 1, "sourceTitle": "THE ONLY PRIZE", "thinker": "Marcus Aurelius", "thoughtNl": "Als wat je graag doet binnen je bereik ligt, heb je minder nodig om van je leven te genieten.", "explanationNl": "De auteurs geven voorbeelden van zeer vermogende mensen die blijven wonen, rijden of leven op een manier die weinig van hun vermogen vraagt. Ze zien daarin bewuste prioriteiten. Als je plezier vooral komt uit bezigheden die binnen bereik liggen, hangt het minder af van inkomsten die kunnen wegvallen. Steeds meer verlangens vragen steeds meer inzet om ze te vervullen. Daardoor kun je juist minder tijd en vrijheid overhouden voor wat je het liefst doet.", "reflectionNl": "Welke bezigheid geeft je veel plezier terwijl ze weinig geld, spullen of status vraagt?", "exerciseNl": "Maak vandaag tijd voor één eenvoudige bezigheid waar je al van weet dat je haar graag doet.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "01-26": {"dateKey": "01-26", "day": 26, "month": 1, "sourceTitle": "THE POWER OF A MANTRA", "thinker": "Marcus Aurelius", "thoughtNl": "Gebruik een korte zin om terug te keren naar een helder oordeel wanneer indrukken en afleiding zich aan je opdringen.", "explanationNl": "Een mantra kan bestaan uit een woord, gedachte of klank die je helpt je aandacht te verzamelen. De auteurs leggen dat gebruik eerst uit vanuit de meditatieve praktijk en herkennen iets vergelijkbaars bij Marcus Aurelius. Wanneer een eerste indruk of de druk van de dag je dreigt mee te slepen, kan een zin je eraan herinneren dat je kunt kiezen wat je aanneemt. De woorden mogen volgens de auteurs verschillen, zolang ze je helpen helder te zien.", "reflectionNl": "Welke korte zin zou je helpen wanneer je merkt dat je eerste indruk je oordeel begint over te nemen?", "exerciseNl": "Schrijf een eigen herinneringszin en probeer haar bij één moment van afleiding.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "01-27": {"dateKey": "01-27", "day": 27, "month": 1, "sourceTitle": "THE THREE AREAS OF TRAINING", "thinker": "Epictetus", "thoughtNl": "Onderzoek wat je verlangt, waarom je wilt handelen en hoe je oordeelt. Die drie beïnvloeden elkaar bij iedere keuze.", "explanationNl": "De auteurs onderscheiden drie gebieden waarin je volgens Epictetus kunt oefenen. Kijk welke verlangens je wilt volgen en waarvan je wilt wegblijven, want aantrekking wijst je soms de verkeerde kant op. Onderzoek vervolgens of je drang om te handelen voortkomt uit goede motieven of uit automatisme. Gebruik ten slotte je verstand om de situatie zorgvuldig te beoordelen. In de praktijk sturen deze gebieden elkaar voortdurend. Daarom verdient elk gebied zijn eigen aandacht en inspanning.", "reflectionNl": "Bij welk voornemen bepaalt je verlangen al wat je over de situatie gelooft?", "exerciseNl": "Neem één voorgenomen actie en schrijf op wat je verlangt, waarom je wilt handelen en wat je zeker weet.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "01-28": {"dateKey": "01-28", "day": 28, "month": 1, "sourceTitle": "WATCHING THE WISE", "thinker": "Marcus Aurelius", "thoughtNl": "Kies iemand wiens oordeel je vertrouwt en bestudeer welke handelingen die persoon kiest en welke juist achterwege blijven.", "explanationNl": "De auteurs halen Seneca aan voor het idee dat een maatstaf helpt om te zien waar iets afwijkt. Iemand die je wijs vindt kan die rol vervullen wanneer je een aanname wilt toetsen of een voorbeeld zoekt voor je eigen handelen. Wie dat is, bepaal je zelf. Een ouder, schrijver of filosoof kan die rol spelen. Let concreet op hoe diegene handelt en op wat diegene bewust nalaat. Probeer het bruikbare daarvan zelf toe te passen.", "reflectionNl": "Wie zou jij bij een lastige keuze als maatstaf nemen, en welke gewoonte van die persoon waardeer je?", "exerciseNl": "Neem één besluit en bedenk welke concrete handeling jouw voorbeeldpersoon zou kiezen.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "01-29": {"dateKey": "01-29", "day": 29, "month": 1, "sourceTitle": "KEEP IT SIMPLE", "thinker": "Marcus Aurelius", "thoughtNl": "Geef de taak die voor je ligt de aandacht waarmee je ook je laatste opdracht zou willen uitvoeren.", "explanationNl": "Vragen over je toekomst, je uiterlijk en de indruk die je maakt kunnen je gedachten zo vullen dat je huidige taak erbij inschiet. De auteurs vergelijken Marcus’ advies met de opdracht van coach Bill Belichick aan zijn spelers om hun eigen werk te doen. Marcus vraagt die aandacht zelfs aan iets alledaags te geven alsof het je laatste taak zou kunnen zijn. Ook wanneer er later veel andere kansen komen, is de taak die nu voor je ligt een goede plaats om zorgvuldig te beginnen.", "reflectionNl": "Welke taak van vandaag verdient je volledige aandacht terwijl je vooral bezig bent met iets wat daarna komt?", "exerciseNl": "Werk tien minuten aan één taak en leg afleidende vragen in die tijd even apart.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "01-30": {"dateKey": "01-30", "day": 30, "month": 1, "sourceTitle": "YOU DON’T HAVE TO STAY ON TOP OF EVERYTHING", "thinker": "Epictetus", "thoughtNl": "Je mag iets buiten je aandacht laten wanneer de details weinig betekenen voor de mensen en keuzes waarvoor je verantwoordelijk bent.", "explanationNl": "In een wereld met doorlopend nieuws voelen mensen volgens de auteurs druk om op de hoogte te zijn van ieder schandaal, iedere serie en elke mogelijke crisis. Ze vragen hoeveel van die druk voortkomt uit de angst om onwetend over te komen. Gebeurtenissen die je omgeving rechtstreeks raken verdienen wel aandacht. Door selectiever te volgen wat er gebeurt, houd je tijd en energie over en hoef je je minder vaak op te winden over onzekere ontwikkelingen.", "reflectionNl": "Welke berichten blijf je volgen vooral uit angst dat je er later niet over mee kunt praten?", "exerciseNl": "Kies één nieuwsonderwerp buiten je directe verantwoordelijkheid en laat updates erover vandaag voorbijgaan.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "01-31": {"dateKey": "01-31", "day": 31, "month": 1, "sourceTitle": "PHILOSOPHY AS MEDICINE OF THE SOUL", "thinker": "Marcus Aurelius", "thoughtNl": "Keer terug naar de gewoontes die je helder helpen denken wanneer drukte je van die oefeningen heeft weggetrokken.", "explanationNl": "De auteurs beschrijven hoe werk, inkomsten en creatieve bezigheden je zoveel vaart kunnen geven dat je filosofische oefening langzaam uit beeld verdwijnt. Dat voelt aanvankelijk alsof alles goed loopt. De gevolgen worden merkbaar wanneer spanning zich ophoopt, je denken vertroebelt en je minder scherp ziet wat belangrijk is. Dan kun je bewust vaart minderen en terugkeren naar oefeningen die je oordeel en uitgangspunten verzorgen. Daarin herkennen de auteurs de herstellende werking die Marcus aan filosofie toekent.", "reflectionNl": "Welke oefening die je vroeger rust of helderheid gaf is ongemerkt uit je dag verdwenen?", "exerciseNl": "Reserveer vandaag vijf minuten voor één beproefde oefening, bijvoorbeeld een korte terugblik.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "02-01": {"dateKey": "02-01", "day": 1, "month": 2, "sourceTitle": "FOR THE HOT-HEADED MAN", "thinker": "Marcus Aurelius", "thoughtNl": "Wie je kwaad probeert te maken, kan daarmee je aandacht sturen. Houd ruimte om zelf je reactie te kiezen.", "explanationNl": "De auteurs gebruiken sporters die hun tegenstander beledigen zodra de scheidsrechter wegkijkt. Hun doel is dat de ander boos wordt en minder goed speelt. Daartegenover zetten ze bokser Joe Louis. Zijn beheerste houding maakte volgens hen meer indruk dan een woede-uitbarsting zou hebben gedaan. Ze zien kracht in het bewaren van je zelfbeheersing wanneer iets je raakt. Daarmee geef je een tegenstander minder gelegenheid om te bepalen hoe jij je gedraagt.", "reflectionNl": "Welke opmerking brengt je het snelst uit je doen, ook wanneer reageren je niets oplevert?", "exerciseNl": "Neem bij de eerstvolgende provocatie één rustige ademteug voordat je beslist of je antwoordt.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "02-02": {"dateKey": "02-02", "day": 2, "month": 2, "sourceTitle": "A PROPER FRAME OF MIND", "thinker": "Marcus Aurelius", "thoughtNl": "Neem je zelfstandigheid serieus genoeg om ook je eigen impulsen te vragen of je eraan wilt gehoorzamen.", "explanationNl": "Veel mensen verzetten zich zodra iemand hun vertelt hoe ze moeten leven. De auteurs merken op hoeveel gehoor diezelfde mensen intussen geven aan plotselinge aandrang. Een afwijkende mening lijkt meteen om discussie te vragen, iets lekkers om opgegeten te worden en een tegenslag om boosheid of zorgen. Even later kan goed nieuws de stemming weer helemaal omgooien. De vraag is hoeveel ruimte je overhoudt om zelf te beslissen als iedere impuls meteen je gedrag bepaalt.", "reflectionNl": "Welke aandrang behandel je gewoonlijk als een bevel waar je direct aan moet voldoen?", "exerciseNl": "Wacht bij één kleine aandrang tien tellen en beslis daarna bewust wat je doet.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "02-03": {"dateKey": "02-03", "day": 3, "month": 2, "sourceTitle": "THE SOURCE OF YOUR ANXIETY", "thinker": "Epictetus", "thoughtNl": "Onderzoek bij onrust welke uitkomst je probeert af te dwingen en of piekeren daar ook maar iets aan bijdraagt.", "explanationNl": "Een ouder verlangt naar veiligheid voor zijn kinderen, een reiziger naar gunstig weer en weinig verkeer, een belegger naar herstel van de markt. De auteurs zien bij Epictetus wat die situaties delen. Het verlangen betreft iets waarover je geen beslissende macht hebt. De klok of koers blijven volgen kan voelen alsof je actief iets doet. De omstandigheden trekken zich weinig aan van hoeveel onrust je ervoor inlevert. Kijk wat die onrust op dit moment werkelijk oplevert.", "reflectionNl": "Welke uitkomst houd je vandaag voortdurend in de gaten terwijl je er op dit moment weinig aan kunt veranderen?", "exerciseNl": "Leg één terugkerende controle kort weg en kies één handeling die wel binnen je bereik ligt.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "02-04": {"dateKey": "02-04", "day": 4, "month": 2, "sourceTitle": "ON BEING INVINCIBLE", "thinker": "Epictetus", "thoughtNl": "Ook onder druk kun je geoefend raken in een kalm antwoord dat je met aandacht hebt gekozen.", "explanationNl": "De auteurs beschrijven een ervaren spreker die scherpe persvragen opvangt met geduld, humor en een rustige houding. Ook wanneer een vraag echt raakt, kan die spreker de eigen reactie kiezen. Ervaring helpt daarbij, evenals het besef dat boos uitvallen de situatie erger kan maken. De auteurs gebruiken dit als beeld voor prohairesis, het vermogen tot een weloverwogen keuze. Het beeld is ook bruikbaar bij een gewone dag waarop frustratie, kritiek of een overvolle agenda je onder druk zet.", "reflectionNl": "Op welke scherpe vraag zou je het liefst rustig en kort kunnen antwoorden?", "exerciseNl": "Bedenk voor één verwachte lastige vraag een feitelijk antwoord van één zin.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "02-05": {"dateKey": "02-05", "day": 5, "month": 2, "sourceTitle": "STEADY YOUR IMPULSES", "thinker": "Marcus Aurelius", "thoughtNl": "Toets een sterke impuls aan je verstand en je gevoel voor rechtvaardigheid voordat je besluit ernaar te handelen.", "explanationNl": "De auteurs beschrijven mensen bij wie iedere dag als een enorm succes of een ramp lijkt te voelen. Ze vragen wat er zou veranderen als zulke snelle impulsen eerst langs een maatstaf kwamen. Filosofie geeft daarvoor aanknopingspunten, zoals redelijkheid en rechtvaardigheid. De impuls zelf kan zich zomaar aandienen. Oefening zit in de beslissing wat je ermee doet. Vraag jezelf daarom af wie de leiding heeft en welk uitgangspunt je voor de handeling kunt aanvoeren.", "reflectionNl": "Welk beginsel helpt je beslissen wanneer je vandaag geneigd bent uit een eerste opwelling te handelen?", "exerciseNl": "Kies bij één snelle impuls een concrete maatstaf en pas die toe voordat je reageert.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "02-06": {"dateKey": "02-06", "day": 6, "month": 2, "sourceTitle": "DON’T SEEK OUT STRIFE", "thinker": "Seneca", "thoughtNl": "Onderzoek waarom je de strijd opzoekt. Soms vraagt de juiste keuze juist dat je een rustige situatie rustig laat.", "explanationNl": "Theodore Roosevelt prees mensen die zich daadwerkelijk inzetten boven toeschouwers die alleen kritiek leveren. De auteurs erkennen zijn moed en noemen tegelijk zijn opeenvolgende gevaren en ondernemingen. Ze vragen zich af hoeveel van die drang voortkwam uit moeite om stil te zitten. Werk en strijd kunnen afleiding bieden van de onrust die bij rust bovenkomt. Inzet verdient bewondering wanneer de reden ervoor deugt. Een vredige uitkomst kan onder sommige omstandigheden de eervolste keuze zijn.", "reflectionNl": "Welke confrontatie zou je laten rusten als je even onderzocht wat je er werkelijk mee wilt bereiken?", "exerciseNl": "Schrijf bij één strijd die je overweegt op waarvoor je haar aangaat en wat rust je zou kosten.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "02-07": {"dateKey": "02-07", "day": 7, "month": 2, "sourceTitle": "FEAR IS A SELF-FULFILLING PROPHECY", "thinker": "Seneca", "thoughtNl": "Let erop of jouw reactie op een gevreesde uitkomst juist helpt om die uitkomst dichterbij te brengen.", "explanationNl": "De auteurs zien in de geschiedenis van Nero hoe gevaarlijk macht kan worden wanneer angst en achterdocht de overhand krijgen. Ze geven ook herkenbare voorbeelden. Wie verraad verwacht kan uit voorzorg zelf iemands vertrouwen beschamen. Wie elk detail controleert uit angst voor slecht bestuur kan daardoor zelf het werk ontregelen. Zulke reacties brengen de gevreesde uitkomst dichterbij. Op het moment dat een scenario rampzalig voelt, verdient je eigen aandrang tot ingrijpen dus een extra zorgvuldige toets.", "reflectionNl": "Welke reactie uit angst zou juist schade kunnen doen aan wat je probeert te beschermen?", "exerciseNl": "Beschrijf bij één zorg hoe je voorgenomen reactie de situatie kan beïnvloeden voordat je haar uitvoert.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "02-08": {"dateKey": "02-08", "day": 8, "month": 2, "sourceTitle": "DID THAT MAKE YOU FEEL BETTER?", "thinker": "Seneca", "thoughtNl": "Vraag jezelf tijdens een uitbarsting of wat je nu doet werkelijk verlichting geeft voor wat je dwarszit.", "explanationNl": "De auteurs beschrijven hoe schreeuwen, scherpe opmerkingen of aanhoudend klagen in een hevige emotie gerechtvaardigd kunnen voelen. Met wat afstand kan die zekerheid omslaan in gêne. Hun voorgestelde vraag gaat over het effect van het gedrag: geeft het verlichting of brengt het iets in beweging? Ze raden aan die maatstaf vooral bij jezelf te gebruiken, ook als je bijvoorbeeld hardop blijft zuchten bij lichamelijk ongemak of blijft malen over spijt. Het antwoord kan je helpen anders te reageren.", "reflectionNl": "Welk gedrag houd je soms aan omdat je al van streek bent, terwijl het je nauwelijks helpt?", "exerciseNl": "Pauzeer bij één moment van klagen en merk op of het probleem of je stemming erdoor verandert.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "02-09": {"dateKey": "02-09", "day": 9, "month": 2, "sourceTitle": "YOU DON’T HAVE TO HAVE AN OPINION", "thinker": "Marcus Aurelius", "thoughtNl": "Je kunt weten dat iets gebeurd is en jezelf toch de ruimte geven om er geen oordeel over te vormen.", "explanationNl": "De auteurs laten je bedenken hoeveel vervelende dingen je vermoedelijk nooit te weten komt. Denk aan een opmerking achter je rug of een voorwerp dat je kwijtraakte zonder het te merken. Zulke voorvallen roepen bij jou geen reactie op zolang je er niets van weet. Dat verschil laat volgens hen zien dat je een oordeel ook bewust kunt laten rusten wanneer het vooral ergernis zou opleveren. Een gebeurtenis waar je geen aandacht aan hoeft te besteden, krijgt daardoor minder macht over je dag.", "reflectionNl": "Over welk klein voorval kun je vandaag je oordeel laten rusten zonder een probleem te negeren dat je moet oplossen?", "exerciseNl": "Zeg bij één onbelangrijk bericht dat je er voorlopig niets van hoeft te vinden en ga verder met je taak.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "02-10": {"dateKey": "02-10", "day": 10, "month": 2, "sourceTitle": "ANGER IS BAD FUEL", "thinker": "Seneca", "thoughtNl": "Boosheid kan je in beweging zetten. Vraag hoeveel het kost om diezelfde boosheid steeds opnieuw als drijfveer te gebruiken.", "explanationNl": "De auteurs erkennen dat woede over afwijzing of vernedering mensen soms tot prestaties drijft. Hun bezwaar gaat over wat er met die motivatie meekomt. Boosheid kan anderen meeslepen, problemen laten escaleren en je uitputten. Wanneer de oorspronkelijke aanleiding verdwijnt, moet je nieuwe boosheid vinden om op dezelfde manier door te gaan. Ze halen Martin Luther King Jr. aan om te laten zien welk gewicht haat kan krijgen, ook bij mensen die alle reden hebben om zich kwaad te voelen.", "reflectionNl": "Welk doel zou nog steeds voor je tellen als je niemand meer iets hoefde te bewijzen?", "exerciseNl": "Schrijf één reden op om aan dat doel te werken die ook zonder boosheid overeind blijft.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "02-11": {"dateKey": "02-11", "day": 11, "month": 2, "sourceTitle": "HERO OR NERO?", "thinker": "Seneca", "thoughtNl": "Invloed geeft je meer gelegenheid om je karakter te tonen. Kijk welke verlangens je begrenst zodra anderen weinig tegenspreken.", "explanationNl": "De auteurs zetten de misdaden van Nero en de verbanning van filosofen onder Domitianus naast Marcus Aurelius als voorbeeld van een wijze vorst. Tussen die gevallen zien ze aanleiding om preciezer naar macht te kijken. Persoonlijke waarden, zelfkennis en het vermogen om verlangens te begrenzen beïnvloeden wat iemand ermee doet. Rechtvaardigheid vraagt extra aandacht wanneer anderen uit beleefdheid of afhankelijkheid weinig weerstand bieden. Ook in werk en privéleven laat je gedrag bij kleine vormen van gezag zien wat je belangrijk vindt.", "reflectionNl": "Wie zou zich vrij voelen om jou tegen te spreken bij een besluit dat jij mag nemen?", "exerciseNl": "Vraag bij één beslissing waar jij over gaat om de eerlijke inbreng van iemand die er gevolgen van merkt.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "02-12": {"dateKey": "02-12", "day": 12, "month": 2, "sourceTitle": "PROTECT YOUR PEACE OF MIND", "thinker": "Epictetus", "thoughtNl": "Bescherm je rust door je reacties te oefenen én te onderzoeken aan welke terugkerende spanningen je jezelf kunt onttrekken.", "explanationNl": "Stoïcijnse oefening kan helpen om bij een conflictueuze relatie, een stressvolle baan of veel publieke aandacht je reactie zorgvuldig te kiezen. De auteurs voegen daar een vraag aan toe. Hoeveel van die terugkerende belasting wil je blijven verdragen en welke reden heb je daarvoor? Een situatie kunnen dragen is één deel van het verhaal. Je kunt ook onderzoeken of deze omstandigheden passen bij het leven dat je wilt en serieus overwegen iets aan je omgeving te veranderen.", "reflectionNl": "Welke terugkerende situatie kost je meer rust dan je bereid bent ervoor te blijven betalen?", "exerciseNl": "Noteer bij één spanningsbron een kleine verandering in de omstandigheden die je zelf kunt verkennen.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "02-13": {"dateKey": "02-13", "day": 13, "month": 2, "sourceTitle": "PLEASURE CAN BECOME PUNISHMENT", "thinker": "Epictetus", "thoughtNl": "Neem bij een verleiding ook het gevoel erna mee in je afweging. Dat geeft een vollediger beeld van het plezier.", "explanationNl": "De auteurs gebruiken het voorbeeld van een dieet waarbij iemand de hele week naar een dag vol lekkers uitkijkt. In hun beschrijving kan zo’n dag uitlopen op een ervaring die veel minder prettig voelt dan de voorpret deed vermoeden. De oefening zit in het verbinden van de aantrekkelijke eerste indruk met wat er werkelijk op volgt. Wie het latere ongemak meeweegt, kan merken dat voorbij laten gaan uiteindelijk prettiger is dan toegeven en daarna spijt hebben.", "reflectionNl": "Welke verleiding lijkt aantrekkelijker wanneer je alleen aan de eerste minuut denkt dan wanneer je het hele verloop overziet?", "exerciseNl": "Denk bij één alledaagse verleiding na over hoe je je doorgaans tien minuten erna voelt.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "02-14": {"dateKey": "02-14", "day": 14, "month": 2, "sourceTitle": "THINK BEFORE YOU ACT", "thinker": "Heraclitus", "thoughtNl": "Geef je verstand tijd om mee te doen zodra een sterk gevoel je aanspoort om meteen iets te doen.", "explanationNl": "Achteraf vragen we ons soms af hoe we iets konden doen terwijl de gevolgen zo duidelijk lijken. De auteurs zoeken het probleem in het moment waarop je handelt. Je kunt voldoende verstand hebben om de situatie goed te beoordelen, terwijl je die mogelijkheid laat liggen doordat een emotie of directe lichamelijke gewaarwording de leiding neemt. Richt je aandacht daarom op je denkvermogen voordat je beslist. Juist in de korte ruimte vóór de handeling krijgt een overwogen antwoord een kans.", "reflectionNl": "Welke lichamelijke gewaarwording is voor jou vaak het eerste teken dat je op het punt staat overhaast te handelen?", "exerciseNl": "Sta bij een impuls kort stil en benoem hardop of in gedachten één mogelijk gevolg.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "02-15": {"dateKey": "02-15", "day": 15, "month": 2, "sourceTitle": "ONLY BAD DREAMS", "thinker": "Marcus Aurelius", "thoughtNl": "Een levendige voorstelling van een ramp kan een echte reactie oproepen. Kijk eerst welke aanwijzingen je werkelijk hebt.", "explanationNl": "De auteurs halen schrijvers en denkers aan die herkennen hoeveel pijn mensen hebben om dingen die nooit zijn gebeurd. Ze vergelijken zulke overtuigende voorstellingen met dromen. Zolang je erin zit, ga je vaak mee in het verhaal zonder te vragen of het klopt. Dat kan ook overdag gebeuren wanneer angst of boosheid je een scenario laat aannemen. Je reactie kan dan echte gevolgen krijgen. Met een moment van onderzoek kun je onderscheiden wat er daadwerkelijk gebeurt en wat je geest erbij invult.", "reflectionNl": "Welk deel van je grootste zorg vandaag bestaat uit iets wat je je voorstelt dat nog kan gebeuren?", "exerciseNl": "Verdeel één zorg in twee regels met wat je hebt waargenomen en wat je verwacht.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "02-16": {"dateKey": "02-16", "day": 16, "month": 2, "sourceTitle": "DON’T MAKE THINGS HARDER THAN THEY NEED TO BE", "thinker": "Marcus Aurelius", "thoughtNl": "Beoordeel een verzoek op wat er gevraagd wordt voordat je ergernis aan de afzender het antwoord laat bepalen.", "explanationNl": "Een lastige collega vraagt iets en je voelt meteen weerstand. De auteurs beschrijven hoe een weigering kan uitlopen op wederzijdse tegenwerking, terwijl een deel van het verzoek eenvoudig of redelijk is. Als je dat deel oppakt, wordt de rest misschien beter hanteerbaar. Ze verbinden dat aan het stoïcijnse idee van passende handelingen. Door ruimte te maken tussen je ergernis en je besluit, voorkom je dat een bijzaak het juiste werk moeilijker maakt.", "reflectionNl": "Welk deel van een verzoek waar je tegen opziet zou redelijk klinken als iemand anders het deed?", "exerciseNl": "Splits één lastig verzoek op en begin desgewenst met het eenvoudige deel dat je kunt verantwoorden.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "02-17": {"dateKey": "02-17", "day": 17, "month": 2, "sourceTitle": "THE ENEMY OF HAPPINESS", "thinker": "Epictetus", "thoughtNl": "Laat een toekomstige mijlpaal geen voorwaarde worden om vandaag ergens tevreden over te mogen zijn.", "explanationNl": "Mensen stellen geluk volgens de auteurs vaak uit tot ze een diploma, promotie of bepaald inkomen hebben. Ze vergelijken zulke voorwaarden met een horizon die opschuift naarmate je verder loopt. Voorpret kan aangenaam zijn. Bij Epictetus ligt de moeilijkheid in een verlangen dat alle aandacht naar later trekt en daardoor de tevredenheid van dit moment verdringt. Kijk welk deel van je geluk je hebt gekoppeld aan iets dat eerst nog moet gebeuren.", "reflectionNl": "Welke mijlpaal behandel je als voorwaarde om te genieten van iets dat nu al mogelijk is?", "exerciseNl": "Kies één prettig ding dat je tot na een mijlpaal uitstelt en maak er vandaag even tijd voor.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "02-18": {"dateKey": "02-18", "day": 18, "month": 2, "sourceTitle": "PREPARE FOR THE STORM", "thinker": "Epictetus", "thoughtNl": "Bereid in een rustig moment voor hoe je reageert wanneer een sterke indruk je straks dreigt mee te slepen.", "explanationNl": "Epictetus vergelijkt overweldigende indrukken met een storm. De auteurs trekken dat beeld door naar weersvoorspellingen en huizen die je tijdig kunt voorbereiden. Wie vooraf leert wat nodig is, heeft bij een waarschuwing iets om op terug te vallen. De wind houdt zijn kracht, maar je staat er anders tegenover wanneer je een plan hebt. Zo kun je ook bij bekende innerlijke of uiterlijke druk vooraf bedenken wat je helpt je evenwicht te bewaren.", "reflectionNl": "Waaraan herken je meestal vroeg dat een situatie je uit je evenwicht gaat brengen?", "exerciseNl": "Schrijf voor één herkenbaar waarschuwingssignaal een eenvoudige handeling op die je wilt proberen.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "02-19": {"dateKey": "02-19", "day": 19, "month": 2, "sourceTitle": "THE BANQUET OF LIFE", "thinker": "Epictetus", "thoughtNl": "Neem wat binnen je bereik komt met aandacht aan, zoals je aan tafel wacht tot een schaal bij je is.", "explanationNl": "De auteurs werken de vergelijking van Epictetus tussen het leven en een maaltijd uit. Wie iets verlangt, hoeft niet naar voren te grijpen terwijl een ander aan de beurt is. Het beeld biedt ook ruimte voor dankbaarheid om de uitnodiging en aandacht voor wat je al kunt proeven. Genieten gaat samen met maat houden. Aan het einde kun je de gastheer helpen en later zelf de zorg voor gasten op je nemen.", "reflectionNl": "Welk aanbod kun je vandaag waarderen zonder meteen te bedenken hoe je er meer van krijgt?", "exerciseNl": "Neem bij een maaltijd bewust de tijd voor wat er al op tafel staat.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "02-20": {"dateKey": "02-20", "day": 20, "month": 2, "sourceTitle": "THE GRAND PARADE OF DESIRE", "thinker": "Marcus Aurelius", "thoughtNl": "Kijk waar het volgen van iedere bevlieging op uitdraait voordat je een aantrekkelijk vooruitzicht als onschuldig beschouwt.", "explanationNl": "De auteurs stellen voor de gevolgen van een leven vol toegeeflijkheid te bekijken. Ze gebruiken sprekende voorbeelden van mensen met zoveel macht of aandacht dat bijna iedere bevlieging bereikbaar is. Zo kan het feestleven van een jonge ster omslaan in afhankelijkheid en vastgelopen werk. De voorbeelden zijn bedoeld om de aantrekkingskracht van zo’n leven te toetsen. Je kunt dezelfde vraag aan jezelf stellen wanneer je denkt dat toegeven aan een bepaalde gewoonte nauwelijks iets kost.", "reflectionNl": "Welke gewoonte lijkt je prettig zolang je buiten beeld laat waar vaker toegeven toe kan leiden?", "exerciseNl": "Bedenk bij één bevlieging wat het je zou opleveren en kosten als je haar een maand lang telkens volgt.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "02-21": {"dateKey": "02-21", "day": 21, "month": 2, "sourceTitle": "WISH NOT, WANT NOT", "thinker": "Epictetus", "thoughtNl": "Zelfs iets waardevols kan je beheersen wanneer je je rust afhankelijk maakt van de vraag of je het krijgt.", "explanationNl": "Volgens de auteurs verdienen rust, leren en reizen best een plaats in je leven. Epictetus richt zich op hoe dwingend verlangen naar zulke dingen kan worden. Je hoopt op iets waarover omstandigheden mede beslissen en kunt je zelfbeheersing verliezen als het anders loopt. De auteurs halen Diogenes aan om te laten zien welke vrijheid er in weinig nodig hebben ligt. Het risico geldt ook voor liefde en nobele doelen, zodra het bereiken ervan je volledig in beslag neemt.", "reflectionNl": "Aan welk waardevol doel denk je zo dwingend dat tegenslag je hele dag kan bepalen?", "exerciseNl": "Schrijf bij één verlangen op wat je kunt blijven doen wanneer je de gehoopte uitkomst voorlopig niet krijgt.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "02-22": {"dateKey": "02-22", "day": 22, "month": 2, "sourceTitle": "WHAT’S BETTER LEFT UNSAID", "thinker": "Plutarchus", "thoughtNl": "Neem tijd om je gedachten te ordenen, ook als anderen verwachten dat je meteen iets overtuigends zegt.", "explanationNl": "Van Cato werd volgens de auteurs bij zijn intrede in de politiek verwacht dat hij snel indruk zou maken met toespraken en scherpe oordelen. Hij voelde die druk en nam toch de tijd om zich voor te bereiden. De auteurs zien daarin een oefening die ook buiten de politiek bruikbaar is. Onderzoek of je alleen wilt reageren uit emotie, eigenbelang, onwetendheid of haast. Spreek zodra je een doordachte bijdrage te leveren hebt.", "reflectionNl": "In welk gesprek zou je vooral iets zeggen omdat stilte ongemakkelijk voelt?", "exerciseNl": "Schrijf eerst je reactie op een lastig bericht op en lees die na voordat je beslist of je die verstuurt.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "02-23": {"dateKey": "02-23", "day": 23, "month": 2, "sourceTitle": "CIRCUMSTANCES HAVE NO CARE FOR OUR FEELINGS", "thinker": "Marcus Aurelius", "thoughtNl": "Een tegenslag kan jouw boosheid niet horen. Gebruik je aandacht voor wat jouw handelen nog kan veranderen.", "explanationNl": "Marcus Aurelius gebruikte in zijn persoonlijke aantekeningen geregeld woorden van andere schrijvers om zichzelf aan lessen te herinneren. De auteurs herkennen hier een fragment uit een grotendeels verloren toneelstuk van Euripides over Bellerophon. Daarin klinkt de vraag waarom iemand boos zou worden op krachten die hem te boven gaan. Omstandigheden zijn ongevoelig voor geschreeuw of onrust. De les die Marcus eruit haalt is om ze minder persoonlijk op te vatten en minder effect toe te schrijven aan opwinding.", "reflectionNl": "Tegen welke omstandigheid richt je vandaag boosheid alsof die jou persoonlijk zou kunnen horen?", "exerciseNl": "Kies bij één tegenslag een handeling die de situatie kan beïnvloeden en probeer die als dat zinvol is.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "02-24": {"dateKey": "02-24", "day": 24, "month": 2, "sourceTitle": "THE REAL SOURCE OF HARM", "thinker": "Epictetus", "thoughtNl": "Een ervaring krijgt mede betekenis door de omstandigheden en jouw oordeel. Geef jezelf ruimte voordat je haar een belediging noemt.", "explanationNl": "De auteurs vergelijken dezelfde geldsom voor iemand met veel vermogen en iemand voor wie het verlies zwaar weegt. Ook woorden van een vijand komen anders binnen dan woorden van een partner. Zulke verschillen laten zien hoeveel context en beoordeling bijdragen aan de ervaren schade. Als jij een opmerking direct als aanval opvat en je stem verheft, kan jouw reactie een confrontatie helpen ontstaan. Een eerste indruk onderzoeken geeft je ruimte om te kiezen hoe je verdergaat.", "reflectionNl": "Welke woorden vat je persoonlijk op terwijl je nog niet weet hoe ze bedoeld zijn?", "exerciseNl": "Schrijf bij één scherpe opmerking eerst de woorden zelf op en noteer je interpretatie eronder.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "02-25": {"dateKey": "02-25", "day": 25, "month": 2, "sourceTitle": "THE SMOKE AND DUST OF MYTH", "thinker": "Marcus Aurelius", "thoughtNl": "Roem en invloed vervagen. Bedenk hoeveel van je korte tijd je wilt geven aan woede, obsessie of perfectionisme.", "explanationNl": "Marcus Aurelius herinnerde zichzelf eraan hoe weinig mensen nog wisten van keizers die kort tevoren regeerden. De auteurs zien daarin zijn besef dat ook zijn eigen macht uiteindelijk weinig sporen zou nalaten. Ze noemen zijn vergelijking tussen Alexander de Grote en de man die zijn muilezels dreef. Uiteindelijk ligt voor beiden de dood in het verschiet. Dat perspectief helpt je te wegen hoeveel tijd je op aarde wilt besteden aan emoties die vooral ontevredenheid opleveren.", "reflectionNl": "Welk gevecht om erkenning zou je minder tijd geven als je het op de schaal van een heel leven bekeek?", "exerciseNl": "Maak vandaag een kwartier vrij voor iets prettigs waarvoor je geen erkenning nodig hebt.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "02-26": {"dateKey": "02-26", "day": 26, "month": 2, "sourceTitle": "TO EACH HIS OWN", "thinker": "Marcus Aurelius", "thoughtNl": "Schrijf op wat je kwaad maakt als dat helpt. Je mag daarna rustig beslissen wat je werkelijk wilt zeggen.", "explanationNl": "De auteurs vertellen hoe Abraham Lincoln bij boosheid een brief kon schrijven waarin hij precies uiteenzette wat hem dwarszat. Vervolgens borg hij die soms op zonder haar te versturen. In die werkwijze herkennen de auteurs Marcus’ besef dat fel terugslaan gemakkelijk is en vaak tot spijt leidt. Hun uitnodiging is om je laatste uitbarsting te onderzoeken op wat ze je opleverde. Een brief opstellen kan ruimte geven om je verhaal te vormen voordat je anderen erbij betrekt.", "reflectionNl": "Wat wilde je bereiken met de laatste scherpe reactie waar je achteraf spijt van had?", "exerciseNl": "Zet bij boosheid je eerste reactie in een kladje en beslis later of iets daarvan gezegd moet worden.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "02-27": {"dateKey": "02-27", "day": 27, "month": 2, "sourceTitle": "CULTIVATING INDIFFERENCE WHERE OTHERS GROW PASSION", "thinker": "Epictetus", "thoughtNl": "Je kunt genieten van wat je hebt en tegelijk oefenen om je rust niet afhankelijk te maken van het behoud ervan.", "explanationNl": "De auteurs stellen zich voor hoeveel rust in relaties mogelijk wordt als bezit, uiterlijk en levensduur je minder bezighouden. Seneca geldt als hun voorbeeld. Hij kon zijn rijkdom waarderen terwijl hij rekening hield met de mogelijkheid die ooit te verliezen. De auteurs bedoelen met stoïcijnse onverschilligheid dat je een uitkomst het gewicht geeft dat ze verdient. Dat laat ruimte voor gebruik en plezier, terwijl verlangen naar meer en angst voor verlies je oordeel minder gemakkelijk overnemen.", "reflectionNl": "Van welk bezit zou je vandaag gemakkelijker genieten als je minder bezig was met de kans dat je het ooit kwijtraakt?", "exerciseNl": "Gebruik één bezit waar je graag zuinig op bent en besteed aandacht aan wat het je nu biedt.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "02-28": {"dateKey": "02-28", "day": 28, "month": 2, "sourceTitle": "WHEN YOU LOSE CONTROL", "thinker": "Epictetus", "thoughtNl": "Zelfs na een flinke misstap kun je pauzeren en bij je volgende keuze opnieuw je verstand gebruiken.", "explanationNl": "De auteurs maken ruimte voor zowel kleine als grote misstappen. In de verwarring van een moment kun je je vermogen om een weloverwogen keuze te maken laten liggen. Volgens hen zijn de middelen en doelen waarmee je oefent daarna nog steeds beschikbaar. Je kunt stoppen met wat je doet, je beheersing hervinden en je verstand opnieuw gebruiken. Hoe je zojuist handelde bepaalt dus minder dan je denkt over de keuze die nu volgt.", "reflectionNl": "Wat is de eerste keuze die je nu opnieuw zorgvuldig kunt maken na iets waar je ontevreden over bent?", "exerciseNl": "Zet even afstand tussen jezelf en de situatie, en benoem dan één beheerste vervolgstap.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "02-29": {"dateKey": "02-29", "day": 29, "month": 2, "sourceTitle": "YOU CAN’T ALWAYS (BE) GET(TING) WHAT YOU WANT", "thinker": "Epictetus", "thoughtNl": "Oefen in kiezen welke verlangens aandacht verdienen. Je houdt meer ruimte over wanneer je minder tegelijk probeert binnen te halen.", "explanationNl": "De auteurs verbinden de moderne wens om tegelijk werk, gezin, zingeving, succes en vrije tijd te hebben met een gebrek aan tijd om prioriteiten te onderzoeken. In de Griekse lesruimte die ze beschrijven, gebruikten leerlingen vrije tijd om na te denken over het goede leven. Epictetus biedt hier vragen over noodzaak en gemis. Stel je voor wat er gebeurt als een verlangen onvervuld blijft. Met die toets kun je verplichtingen en wensen loslaten die vooral drukte toevoegen.", "reflectionNl": "Welke extra wens maakt het moeilijker om tijd te geven aan iets dat je nu al belangrijker vindt?", "exerciseNl": "Kies één ding dat je graag wilt toevoegen en schrijf op wat er gebeurt als je het deze maand laat rusten.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "03-01": {"dateKey": "03-01", "day": 1, "month": 3, "sourceTitle": "WHERE PHILOSOPHY BEGINS", "thinker": "Epictetus", "thoughtNl": "Filosofie begint zodra je je eigen gedachten onderzoekt en durft te vragen waar je overtuigingen vandaan komen.", "explanationNl": "De auteurs openen met de vraag hoe iemand eigenlijk aan filosofie begint. Een studieprogramma, een lezing of afstand doen van bezit kan allemaal heel plechtig klinken. Voor Epictetus begint het wanneer je je verstand gebruikt om vanzelfsprekende emoties, overtuigingen en woorden te onderzoeken. De vergelijking met een dier dat zichzelf in de spiegel herkent maakt dat concreet: je merkt dat je je eigen denken kunt waarnemen. Daar begint het onderzochte leven waar ook Socrates op wijst.", "reflectionNl": "Welke overtuiging over jezelf behandel je als feit, terwijl je nooit hebt onderzocht waar die vandaan komt?", "exerciseNl": "Schrijf één stellige gedachte op en voeg er de vraag aan toe welk bewijs je ervoor hebt.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "03-02": {"dateKey": "03-02", "day": 2, "month": 3, "sourceTitle": "ACCURATE SELF-ASSESSMENT", "thinker": "Seneca", "thoughtNl": "Schat jezelf eerlijk in, want jezelf onderschatten kan je evenzeer beperken als jezelf overschatten.", "explanationNl": "Wie eerlijk naar zichzelf kijkt, kan ontdekken dat bepaalde sterke kanten minder ontwikkeld zijn dan gedacht. Dat vooruitzicht maakt zelfonderzoek ongemakkelijk. De auteurs halen Goethe aan om ook het omgekeerde te laten zien: mensen kunnen onverwacht goed voor anderen zorgen tijdens eigen verdriet of overeind blijven bij grote druk. De opdracht is daarom je beperkingen én je kunnen onder ogen te zien. Zo kun je bepalen wat er nodig is om mogelijkheden te benutten die je nog weinig aanspreekt.", "reflectionNl": "Bij welke recente gebeurtenis bleek je meer aan te kunnen dan je vooraf verwachtte?", "exerciseNl": "Noteer één zwakte en één vermogen, elk met een voorbeeld uit je eigen ervaring.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "03-03": {"dateKey": "03-03", "day": 3, "month": 3, "sourceTitle": "(DIS)INTEGRATION", "thinker": "Epictetus", "thoughtNl": "Als je je eigen drijfveren leert kennen, hoef je je telkens minder te voegen naar wat de omgeving vraagt.", "explanationNl": "Verlangens en angsten kunnen binnen één persoon tegelijk in tegengestelde richtingen trekken. De omgeving voegt daar haar eigen tegenstrijdige verwachtingen aan toe. Holiday en Hanselman gebruiken het beeld van Jekyll en Hyde om te laten zien hoe moeilijk het is zo verdeeld te blijven leven. Ze zetten de filosoof, die zich toelegt op innerlijke samenhang, naast iemand die zich steeds vormt naar de stemming van een groep. Zelfkennis helpt om onder die druk koers te houden.", "reflectionNl": "Waar doe je in verschillende gezelschappen iets anders terwijl je eigenlijk hetzelfde belangrijk vindt?", "exerciseNl": "Benoem bij één aanstaande keuze welk eigen uitgangspunt je wilt volgen.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "03-04": {"dateKey": "03-04", "day": 4, "month": 3, "sourceTitle": "AWARENESS IS FREEDOM", "thinker": "Epictetus", "thoughtNl": "Onderzoek welke verplichtingen je werkelijk hebt en welke je zelf aanvaardt uit gewoonte, ijdelheid of behoefte aan controle.", "explanationNl": "De auteurs erkennen gewone verantwoordelijkheden voor werk en familie. Hun vraag gaat over alles wat daar bovenop komt doordat we indruk willen maken, een impuls volgen of moeite hebben om iets af te wijzen. Ook wie macht heeft, kan volgens Seneca vastzitten aan geld of aanzien. De voorbeelden lopen van voortdurend ingrijpen bij medewerkers tot telkens toezeggen dat je bij een bijeenkomst zult zijn. Wie zijn verplichtingen inventariseert kan zien waar hij zichzelf meer vastlegt dan nodig is.", "reflectionNl": "Welke afspraak zou je vandaag opnieuw afwegen als niemand teleurgesteld kon zijn?", "exerciseNl": "Kies één terugkerende verplichting en schrijf op wie of wat die werkelijk van je vraagt.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "03-05": {"dateKey": "03-05", "day": 5, "month": 3, "sourceTitle": "CUTTING BACK ON THE COSTLY", "thinker": "Seneca", "thoughtNl": "Vraag bij elk bezit ook wat het kost om het te bewaren, te onderhouden en eraan te blijven denken.", "explanationNl": "Seneca wijst op een prijs die gemakkelijk uit beeld verdwijnt wanneer we spullen verzamelen. Holiday en Hanselman plaatsen dat in een wereld waarin grotere huizen en meer bezit al snel als vooruitgang gelden. Zelfs een voorwerp dat je gratis krijgt kan ruimte innemen in je garage en aandacht blijven opeisen. Kijk daarom eens naar wat je al in huis hebt en vraag wat het je werkelijk oplevert. Het antwoord kan veranderen zodra je ook het bewaren meetelt.", "reflectionNl": "Welk voorwerp gebruik je zelden maar kost je regelmatig ruimte of aandacht?", "exerciseNl": "Kies één voorwerp en maak een korte afweging tussen gebruikswaarde en bewaarkosten.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "03-06": {"dateKey": "03-06", "day": 6, "month": 3, "sourceTitle": "DON’T TELL YOURSELF STORIES", "thinker": "Epictetus", "thoughtNl": "Luister naar de mensen die bij je zijn en wees alert op de verhalen waarmee je jezelf in het middelpunt zet.", "explanationNl": "De auteurs noemen twee bezwaren tegen steeds over je verleden vertellen. Met Nassim Taleb wijzen ze erop dat we gebeurtenissen achteraf tot een verhaal smeden en daarin meer samenhang en zekerheid ervaren dan de feiten dragen. Epictetus vestigt bovendien de aandacht op het gezelschap: een sterke anekdote voor de verteller kan voor de anderen gewoon vermoeiend zijn. In het huidige gesprek is er meer kans op werkelijk contact als je ruimte maakt om te luisteren.", "reflectionNl": "Wanneer begon je voor het laatst jouw versie van een verhaal te vertellen terwijl iemand nog iets over zichzelf wilde delen?", "exerciseNl": "Stel in je volgende gesprek een vervolgvraag voordat je een eigen anekdote deelt.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "03-07": {"dateKey": "03-07", "day": 7, "month": 3, "sourceTitle": "DON’T TRUST THE SENSES", "thinker": "Heraclitus, via Diogenes Laërtius", "thoughtNl": "Gun jezelf een korte pauze tussen wat je waarneemt en de conclusie die je daaruit wilt trekken.", "explanationNl": "Zelfkennis houdt hier in dat je je reflexen, gewoonten en aannames kritisch kunt bekijken. Holiday en Hanselman verbinden dat met zelfbedrog en onaangevochten zekerheden. Ook zintuigen kunnen misleiden, terwijl emoties alarm slaan en verwachtingen soms veel te gunstig uitvallen. Dat klinkt ontmoedigend, maar kan volgens de auteurs juist ruimte geven. Zodra je beseft dat een eerste indruk voorlopig is, kun je even wachten, beter kijken naar wat er speelt en met meer informatie besluiten wat je doet.", "reflectionNl": "Welke recente eerste indruk zou je herzien als je alleen de controleerbare feiten opschrijft?", "exerciseNl": "Wacht bij één snelle conclusie en bedenk welk detail haar zou kunnen veranderen.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "03-08": {"dateKey": "03-08", "day": 8, "month": 3, "sourceTitle": "DON’T UNINTENTIONALLY HAND OVER YOUR FREEDOM", "thinker": "Epictetus", "thoughtNl": "Let op waar je aandacht naartoe gaat, vooral op momenten waarop je die ongemerkt uit handen geeft.", "explanationNl": "We bewaken volgens de auteurs vanzelf onze lichamelijke grenzen, terwijl we veel losser omgaan met onze aandacht. Ze wijzen op even surfen tijdens het werk, tijdens familietijd op een telefoon kijken en op een bankje in het park voortdurend anderen beoordelen. Dat zijn momenten waarop afleiding zich vaak ongemerkt voltrekt. De stoïcijnen maken onderscheid tussen uiterlijke omstandigheden, die ons lichaam kunnen beperken, en het vermogen onze aandacht en oordelen bewust te sturen. Dat vermogen verdient actieve bescherming.", "reflectionNl": "Op welk moment van de dag laat je het vaakst een scherm bepalen waar je aandacht terechtkomt?", "exerciseNl": "Leg bij één gesprek of klus je telefoon tien minuten uit het zicht.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "03-09": {"dateKey": "03-09", "day": 9, "month": 3, "sourceTitle": "FIND THE RIGHT SCENE", "thinker": "Epictetus en Musonius Rufus, die Theognis citeert", "thoughtNl": "Kies bewust bij wie je tijd doorbrengt, want hun gewoonten en verwachtingen kleuren geleidelijk ook de jouwe.", "explanationNl": "Met voorbeelden van Jim Rohn, James Altucher en Goethe beschrijven de auteurs hoe mensen elkaar vormen. Een goede kring kan je aanmoedigen, aanspreken en verder helpen. Andere contacten maken het moeilijker om te handelen zoals je zelf belangrijk vindt. De bedoeling is om aandacht te geven aan wat een omgang in de praktijk met je doet. Op basis daarvan kun je besluiten met wie je graag meer tijd doorbrengt en waar enige afstand goed zou zijn.", "reflectionNl": "Na welk contact merk je dat je vaker handelt zoals je eigenlijk wilt handelen?", "exerciseNl": "Plan een kort moment met iemand die jou op een goede manier scherp houdt.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "03-10": {"dateKey": "03-10", "day": 10, "month": 3, "sourceTitle": "FIND YOURSELF A CATO", "thinker": "Seneca", "thoughtNl": "Neem een betrouwbaar voorbeeld in gedachten en vraag hoe die persoon jouw eerstvolgende beslissing zou beoordelen.", "explanationNl": "Cato de Jongere kreeg een vaste plaats in de stoïcijnse literatuur door hoe hij handelde. Holiday en Hanselman benadrukken dat daar geen boeken of lessen van hem voor nodig waren. Seneca raadt aan zelf zo’n voorbeeld te kiezen en het als stille getuige bij beslissingen toe te laten. De auteurs verbinden dat met Adam Smiths idee van een onpartijdige toeschouwer. Zo’n denkbeeldige blik kan je corrigeren bij gemakzucht, oneerlijkheid of eigenbelang. Je kunt op termijn zelf dat voorbeeld voor iemand worden.", "reflectionNl": "Wie zou jou het eerlijkst kunnen laten zien wat er wringt aan een keuze die je overweegt?", "exerciseNl": "Neem één besluit in gedachten en beschrijf wat jouw gekozen voorbeeld erin zou opmerken.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "03-11": {"dateKey": "03-11", "day": 11, "month": 3, "sourceTitle": "LIVING WITHOUT RESTRICTION", "thinker": "Epictetus", "thoughtNl": "Weeg bij het nastreven van succes mee hoeveel vrijheid je ervoor moet inleveren en wat dat van je vraagt.", "explanationNl": "Holiday en Hanselman vragen om bij rijke, beroemde of machtige mensen ook te kijken naar de prijs van hun positie. Misschien moeten ze op bepaalde feesten verschijnen, mensen naar de mond praten of hun werkelijke opvattingen inslikken. Een loopbaan kan zelfs gedrag eisen dat tegen hun karakter ingaat. Het loon of het aanzien vertelt dus maar een deel van het verhaal. Wie dit succes nastreeft, doet er goed aan de hele ruil te overzien voordat de eigen keuzes steeds smaller worden.", "reflectionNl": "Welke vrijheid zou je missen als je de functie of status bereikte die je nu nastreeft?", "exerciseNl": "Schrijf bij één ambitie op welke prijs je bereid bent te betalen en waar je grens ligt.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "03-12": {"dateKey": "03-12", "day": 12, "month": 3, "sourceTitle": "SEEING THINGS AS THE PERSON AT FAULT DOES", "thinker": "Marcus Aurelius", "thoughtNl": "Probeer bij een kwetsende daad te begrijpen wat de ander dacht te doen, ook als diens oordeel verkeerd was.", "explanationNl": "De auteurs lezen Marcus in het licht van Socrates’ idee dat mensen gewoonlijk handelen vanuit wat hun juist toeschijnt. Ze nemen de Amerikaanse Burgeroorlog als scherp voorbeeld. Geconfedereerde soldaten konden oprecht denken hun plicht te vervullen, terwijl de zaak waarvoor ze vochten verkeerd was. Lincoln sprak eveneens over handelen naar het eigen begrip van plicht. Die oprechtheid maakt de twee keuzes moreel niet gelijk. Het onderscheid tussen bedoeling en juistheid kan wel helpen om andermans gedrag preciezer te beoordelen.", "reflectionNl": "Welke redenering kan iemand hebben gevolgd bij een keuze die jij als een persoonlijke aanval ervoer?", "exerciseNl": "Schrijf in één zin op wat de ander misschien probeerde te bereiken en in één zin waarom jij zijn keuze afwijst.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "03-13": {"dateKey": "03-13", "day": 13, "month": 3, "sourceTitle": "ONE DAY IT WILL ALL MAKE SENSE", "thinker": "Epictetus", "thoughtNl": "Een tegenslag kan later anders blijken uit te pakken dan je vandaag vanuit je eigen plannen kunt zien.", "explanationNl": "We verzetten ons volgens Holiday en Hanselman vaak tegen een gebeurtenis omdat die onze plannen doorkruist. Daarmee beoordelen we haar vanuit een beperkt standpunt. Wat nu rampzalig lijkt, kan met tijd een gunstige wending blijken of iemand anders ruimte bieden. De auteurs plaatsen dit bij de stoïcijnse gedachte dat gebeurtenissen deel zijn van een groter, redelijk geheel waarvan wij de verbanden maar gedeeltelijk zien. Het ongemak van vandaag geeft op zichzelf nog geen zicht op wat er uiteindelijk uit voortkomt.", "reflectionNl": "Welke gebeurtenis kreeg achteraf een andere betekenis dan jij haar op de dag zelf gaf?", "exerciseNl": "Beschrijf één actuele tegenvaller eerst feitelijk en noteer daarna welke gevolgen je nog onmogelijk kunt overzien.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "03-14": {"dateKey": "03-14", "day": 14, "month": 3, "sourceTitle": "SELF-DECEPTION IS OUR ENEMY", "thinker": "Zeno, via Diogenes Laërtius", "thoughtNl": "Laat ruimte voor wat je nog kunt leren, vooral wanneer je ervan overtuigd bent dat je iets al beheerst.", "explanationNl": "Zelfoverschatting is voor de auteurs vooral schadelijk omdat ze leren blokkeert. Ze verwijzen naar Epictetus’ gedachte dat je moeilijk iets kunt leren waarvan je denkt dat je het al weet. Als je jezelf al volmaakt of algemeen bewonderd waant, ontneem je jezelf de aanleiding om te verbeteren of respect werkelijk te verdienen. Zelfbedrog geeft zo in je verbeelding alvast wat je in werkelijkheid nog wilt ontwikkelen. De schrijvers stellen voor dat patroon steeds opnieuw te weerstaan, desnoods per dag.", "reflectionNl": "Op welk onderwerp verdedig je je kennis het snelst wanneer iemand een aanvulling geeft?", "exerciseNl": "Vraag één persoon om een specifiek verbeterpunt en schrijf eerst alleen op wat je hoort.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "03-15": {"dateKey": "03-15", "day": 15, "month": 3, "sourceTitle": "THE PRESENT IS ALL WE POSSESS", "thinker": "Marcus Aurelius", "thoughtNl": "Het huidige moment is de tijd die je werkelijk hebt. Geef het aandacht zolang het nog beschikbaar is.", "explanationNl": "Holiday en Hanselman vragen je op te merken hoe vaak je méér van de tijd verlangt. Je wilt dat het verleden anders was of terugkwam, of je verwacht dat de toekomst precies volgens jouw wensen verloopt. Zo gaat aandacht verloren voor wat er intussen werkelijk gebeurt. De auteurs herinneren aan een aan Bil Keane toegeschreven woordspeling over het heden als geschenk. Dat geschenk is tijdelijk beschikbaar. Door de momenten die je hebt volledig te beleven, kun je volgens hen genoeg hebben aan een leven.", "reflectionNl": "Welk moment vandaag dreig je te missen doordat je in gedachten een gebeurtenis probeert over te doen?", "exerciseNl": "Kies een gewone bezigheid en geef die twee minuten je volle aandacht.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "03-16": {"dateKey": "03-16", "day": 16, "month": 3, "sourceTitle": "THAT SACRED PART OF YOU", "thinker": "Marcus Aurelius", "thoughtNl": "Waardeer dat je je verstand kunt gebruiken en zet dat vermogen zorgvuldig in voor jezelf en voor anderen.", "explanationNl": "Het vermogen om te lezen, na te denken en situaties te doorgronden is volgens de auteurs gemakkelijk als vanzelfsprekend te behandelen. Ze wijzen erop hoeveel het in de praktijk mogelijk maakt. Je kunt ermee uit moeilijkheden komen, je omstandigheden verbeteren en ook invloed hebben op de omstandigheden van anderen. Dat is een reden om dit vermogen bewust te waarderen. De auteurs koppelen de macht van redeneren nadrukkelijk aan verantwoordelijkheid voor wat je ermee doet.", "reflectionNl": "Voor wie maakt het verschil als jij vandaag eerst goed nadenkt en pas daarna beslist?", "exerciseNl": "Kies één beslissing en schrijf op welke gevolgen twee mogelijke opties voor iemand anders hebben.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "03-17": {"dateKey": "03-17", "day": 17, "month": 3, "sourceTitle": "THE BEAUTY OF CHOICE", "thinker": "Epictetus", "thoughtNl": "Kijk achter uiterlijk, bezit en status naar de inspanning en keuzes die iets over iemands karakter vertellen.", "explanationNl": "Holiday en Hanselman herkennen Epictetus’ punt in Fight Club, waar identiteit wordt losgemaakt van beroep, geld en bezit. Reclame en andere media moedigen volgens hen juist aan om presentatie met persoonlijkheid te verwarren. Als voorbeeld bespreken ze een getraind lichaam. De inspanning erachter kan bewonderenswaardig zijn, terwijl pronken een heel andere drijfveer laat zien. Ook bij een mooi uiterlijk kun je daarom verder kijken dan het zichtbare resultaat. De keuzes, het werk en de motieven erachter bepalen hoe je het beoordeelt.", "reflectionNl": "Welke eigenschap wil je dat mensen herkennen aan wat je doet, los van hoe je overkomt?", "exerciseNl": "Beoordeel één resultaat waar je trots op bent door de keuze erachter te benoemen.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "03-18": {"dateKey": "03-18", "day": 18, "month": 3, "sourceTitle": "IMPOSSIBLE WITHOUT YOUR CONSENT", "thinker": "Marcus Aurelius", "thoughtNl": "Let bij frustratie op het oordeel dat je aan een gebeurtenis toevoegt en welke reactie daardoor wordt versterkt.", "explanationNl": "Op moeilijke dagen wijzen we al snel het werk of een leidinggevende aan als oorzaak van onze frustratie. De auteurs benadrukken vanuit de stoïcijnse visie dat de gevoelens werkelijk zijn en binnen ons ontstaan. Ze noemen hypolêpsis, het opnemen of overnemen van indrukken, gedachten en oordelen door de geest. Iemand kan het voorwerp van je frustratie worden. Welke aanname je bij diens gedrag maakt en welk oordeel je vasthoudt, is volgens deze benadering het deel dat je zelf kunt onderzoeken.", "reflectionNl": "Welk oordeel over je leidinggevende of werk komt telkens terug zodra de druk toeneemt?", "exerciseNl": "Schrijf één ergernis op in twee delen: de waarneembare gebeurtenis en jouw uitleg ervan.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "03-19": {"dateKey": "03-19", "day": 19, "month": 3, "sourceTitle": "TIMELESS WISDOM", "thinker": "Epictetus", "thoughtNl": "Kijk welke verwachting je irritatie voedt en onderzoek of je de situatie ook zonder die eis kunt beoordelen.", "explanationNl": "De auteurs horen bij de Indiase jezuïet en psychotherapeut Anthony de Mello een gedachte terug die sterk lijkt op Epictetus: onderzoek bij ergernis wat er in je eigen reactie gebeurt. Hun overeenkomst laat zien hoe eenzelfde inzicht in verschillende tijden en tradities kan ontstaan. Holiday en Hanselman wijzen vervolgens op etiketten en verwachtingen. Het oordeel dat iets onaanvaardbaar is kan uit een eigen aanspraak voortkomen. Zodra je die aanspraak opmerkt, kun je anders naar dezelfde gebeurtenis kijken en meer ruimte maken voor aanvaarding.", "reflectionNl": "Welke stille verwachting over hoe iemand zich hoort te gedragen maakt jouw irritatie het sterkst?", "exerciseNl": "Herschrijf één ergernis als een beschrijving van wat er gebeurde en wat je gehoopt had.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "03-20": {"dateKey": "03-20", "day": 20, "month": 3, "sourceTitle": "READY AND AT HOME", "thinker": "Seneca", "thoughtNl": "Moeilijkheden hoef je niet op te zoeken. Je kunt wel voorbereiden hoe je ze tegemoet wilt treden.", "explanationNl": "De auteurs vertellen hoe de Amerikaanse president James Garfield te midden van politieke verdeeldheid een conflict liever vermeed en bereid bleef zijn bevoegdheid te verdedigen. Ze zien daarin wat Seneca bedoelt met klaarstaan voor moeilijkheden. Ernaar verlangen is dwaas, maar erop rekenen dat ze uitblijven laat je onvoorbereid. Holiday en Hanselman maken dat tastbaar met een bezoeker aan de deur: wie iemand verwacht, kan hem wakker, aangekleed en met aandacht ontvangen. Zo kun je ook tegenslag bewust tegemoet treden.", "reflectionNl": "Welke mogelijke tegenvaller zou je kalmer opvangen als je nu je eerste reactie bepaalde?", "exerciseNl": "Formuleer voor één waarschijnlijke moeilijkheid een eerste haalbare stap.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "03-21": {"dateKey": "03-21", "day": 21, "month": 3, "sourceTitle": "THE BEST RETREAT IS IN HERE, NOT OUT THERE", "thinker": "Marcus Aurelius", "thoughtNl": "Je kunt jezelf nu al wat rust geven door je aandacht naar binnen te richten en prikkels te verminderen.", "explanationNl": "Een vakantie, een weekend of het einde van een drukke periode lijken geschikte momenten om eindelijk rust te vinden. Holiday en Hanselman vragen hoe vaak dat uitstel werkelijk heeft geholpen. Met een gedachte van Jon Kabat-Zinn herinneren ze eraan dat je jezelf overal meeneemt. Daardoor kun je ook ter plekke iets doen. Aandacht voor je ademhaling, even luisteren naar muziek of de technologie uitzetten zijn volgens hen manieren om op een gewone dag een moment van terugtrekking te vinden.", "reflectionNl": "Welke rust stel je steeds uit tot na je volgende vrije dag?", "exerciseNl": "Zet je scherm uit en volg rustig vijf ademhalingen op de plek waar je al bent.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "03-22": {"dateKey": "03-22", "day": 22, "month": 3, "sourceTitle": "THE SIGN OF TRUE EDUCATION", "thinker": "Epictetus", "thoughtNl": "Echte vorming zie je aan hoe iemand denkt en handelt, vooral bij zaken die buiten diens macht liggen.", "explanationNl": "Een diploma kan op opleiding wijzen zoals schoenen kunnen wijzen op wandelen. Voor de auteurs begint de kwestie juist bij wat iemand daadwerkelijk met zijn kennis doet. Ze vragen hoe hoogopgeleide mensen soms overduidelijke dingen missen of onredelijk besluiten. Als verklaring noemen ze onder meer het vergeten van het onderscheid tussen wat binnen en buiten je macht ligt. Een fragment van Heraclitus illustreert hoe feitelijke kennis naast gemist inzicht kan bestaan. Oplettendheid en herhaald zelfonderzoek horen daarom bij vorming.", "reflectionNl": "Welke eenvoudige les kun je goed uitleggen maar pas je onder druk nog zelden toe?", "exerciseNl": "Merk vandaag één moment op waarop je energie steekt in iets waar je geen invloed op hebt.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "03-23": {"dateKey": "03-23", "day": 23, "month": 3, "sourceTitle": "THE STRAITJACKETED SOUL", "thinker": "Seneca", "thoughtNl": "Onderzoek waar hebzucht of een andere vaste neiging je oordeel vernauwt, ook wanneer je de feiten goed kent.", "explanationNl": "Holiday en Hanselman kijken naar de financiële crisis aan het einde van de jaren nul. Deskundige mensen kenden de markten en beheerden enorme bedragen, en toch gingen velen mee in ingewikkelde constructies rond schuld. De auteurs zien hebzucht als een factor die snelle winst aantrekkelijk maakte en het benoemen van gevaar in de weg stond. Achteraf veroordelen levert minder op dan nagaan welke eigen verlangens vandaag hetzelfde effect hebben. Je verstand kan ingrijpen zodra je merkt wat je oordeel vernauwt.", "reflectionNl": "Welke kans op winst of voordeel maakt het voor jou moeilijk om naar een duidelijk bezwaar te luisteren?", "exerciseNl": "Schrijf vóór één verleidelijke keuze op welk risico je het liefst buiten beschouwing zou laten.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "03-24": {"dateKey": "03-24", "day": 24, "month": 3, "sourceTitle": "THERE IS PHILOSOPHY IN EVERYTHING", "thinker": "Epictetus", "thoughtNl": "Breng wat je over filosofie leest in verband met je gewone keuzes. Daar krijgen de woorden hun betekenis.", "explanationNl": "Plutarchus beschreef hoe zijn levenservaring hem hielp om Romeinse literatuur te begrijpen toen hij die later in zijn leven ging bestuderen. De auteurs gebruiken dat voorbeeld om Epictetus’ kijk op filosofie te verduidelijken. Studie krijgt betekenis door situaties waarin je de ideeën herkent en uitprobeert. Je gedrag over langere tijd laat vervolgens zien welke lessen je werkelijk hebt opgenomen. Dat kan blijken op het werk, bij een politieke keuze, in een gesprek met je ouders of in de omgang met je buur.", "reflectionNl": "Welke filosofische les zou je vandaag kunnen toetsen in een gesprek dat toch al op je wacht?", "exerciseNl": "Kies één alledaags gebaar waarmee je een overtuiging die je belangrijk vindt zichtbaar maakt.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "03-25": {"dateKey": "03-25", "day": 25, "month": 3, "sourceTitle": "WEALTH AND FREEDOM ARE FREE", "thinker": "Epictetus", "thoughtNl": "Zie welke vormen van rijkdom en vrijheid je al hebt, ook als je omstandigheden vandaag hetzelfde blijven.", "explanationNl": "Holiday en Hanselman leggen twee wegen naast elkaar. Je kunt proberen alles te verkrijgen wat je verlangt, of leren waarderen wat je al hebt. Voor vrijheid maken ze een vergelijkbaar onderscheid. Wie vooral strijdt voor steeds meer bewegingsruimte kan het gevoel van beperking blijven voeden. Aandacht voor de keuzes die al beschikbaar zijn kan nu al ruimte geven. De vraag van de auteurs is welke van beide wegen op deze plek en dit moment het meest uitvoerbaar is.", "reflectionNl": "Welke keuze kun je vandaag al maken terwijl je denkt dat er eerst iets moet veranderen?", "exerciseNl": "Noteer twee vrijheden die je op dit moment hebt en gebruik er vandaag bewust één.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "03-26": {"dateKey": "03-26", "day": 26, "month": 3, "sourceTitle": "WHAT RULES YOUR RULING REASON?", "thinker": "Marcus Aurelius", "thoughtNl": "Onderzoek ook wat je verstand beïnvloedt, want zelfs een geoefend oordeel staat onder invloed van lichaam en omgeving.", "explanationNl": "Holiday en Hanselman verbinden Marcus’ vraag over zijn leidende verstand met Juvenalis’ vraag wie de bewakers bewaakt. Ook een redelijk en gedisciplineerd mens heeft invloeden die buiten zijn aandacht kunnen blijven. De auteurs wijzen op psychologie, neurologie, evolutionaire biologie en onbewuste processen. Een lege maag dient als voorbeeld van een lichamelijke toestand die je beslissingen kan kleuren, ook wanneer je doorgaans geduldig bent. Onderzoek hoe lichaam en geest werken om beter te begrijpen waar je oordeel vandaag op steunt.", "reflectionNl": "Onder welke omstandigheden blijkt jouw geduld minder betrouwbaar dan je op basis van je karakter zou denken?", "exerciseNl": "Noteer voor een belangrijk besluit hoe moe, hongerig of gehaast je bent en neem zo nodig pauze.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "03-27": {"dateKey": "03-27", "day": 27, "month": 3, "sourceTitle": "PAY WHAT THINGS ARE WORTH", "thinker": "Diogenes van Sinope, via Diogenes Laërtius", "thoughtNl": "Een prijs vertelt hoeveel iemand vraagt. Bepaal zelf of het voorwerp enige werkelijke waarde voor je leven heeft.", "explanationNl": "De auteurs zetten de prijs van een met diamanten bezette bank naast het lage bedrag waarvoor iemand bereid kan zijn een ander te doden. Die schokkende vergelijking ondergraaft het idee dat marktprijzen de werkelijke waarde bepalen. Ze verwijzen naar Diogenes van Sinope en zijn aandacht voor waarde, een thema dat ook bij Epictetus en Marcus terugkomt. Het koopgedrag van anderen kan een nutteloos voorwerp aantrekkelijk maken. Onderzoek daarom wat iets je werkelijk biedt, zelfs als de prijs op zichzelf meevalt.", "reflectionNl": "Welke voorgenomen aankoop lijkt waardevol vooral omdat anderen er veel voor overhebben?", "exerciseNl": "Stel één aankoopbesluit uit en schrijf op welk concreet gebruik de prijs voor jou zou rechtvaardigen.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "03-28": {"dateKey": "03-28", "day": 28, "month": 3, "sourceTitle": "COWARDICE AS A DESIGN PROBLEM", "thinker": "Seneca", "thoughtNl": "Bereid het begin van een lastige situatie voor, zodat een onverwachte wending je minder snel uit het veld slaat.", "explanationNl": "De auteurs noemen sportwedstrijden, zakelijke afspraken en gesprekken die snel uit de hand kunnen lopen als je onvoorbereid begint. Een plan hoeft de toekomst niet precies te voorspellen. Het geeft je iets om op terug te vallen wanneer je overrompeld raakt. Coach Bill Walsh werkte daarom voor zijn ploeg vooraf een reeks openingszetten uit. Zo kon het team aan de wedstrijd beginnen zonder elk onverwacht punt als een reden tot paniek te behandelen. De les is om je eerste stappen van tevoren te bepalen.", "reflectionNl": "Waar loop je het risico dat een onverwachte opening je de rest van het gesprek uit balans brengt?", "exerciseNl": "Schrijf voor één lastige afspraak je openingszin en twee eerste stappen op.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "03-29": {"dateKey": "03-29", "day": 29, "month": 3, "sourceTitle": "WHY DO YOU NEED TO IMPRESS THESE PEOPLE AGAIN?", "thinker": "Epictetus", "thoughtNl": "Merk hoeveel je voor goedkeuring doet en vraag je af wat je zelf zou kiezen zonder publiek.", "explanationNl": "Holiday en Hanselman kijken naar wat mensen doen om een teken van waardering te krijgen: anders praten, eten of kleden, en vervolgens gespannen wachten op een reactie. Hetzelfde gedrag kan een eigen voorkeur zijn of uitsluitend bedoeld om indruk te maken. Ze herinneren met Marcus eraan dat de mensen wier goedkeuring we zoeken zelf ook afgeleid of gemakkelijk te imponeren zijn. Als je keuzes steeds van hun oordeel afhangen, ruil je een deel van de rust in die filosofie kan bieden.", "reflectionNl": "Welke keuze van deze week had je anders gemaakt als niemand er iets van zou merken?", "exerciseNl": "Doe één kleine keuze vandaag volgens je eigen voorkeur en laat het bij die keuze.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "03-30": {"dateKey": "03-30", "day": 30, "month": 3, "sourceTitle": "REASON IN ALL THINGS", "thinker": "Marcus Aurelius", "thoughtNl": "Kijk vóór je handelt wat je stuurt: een overwogen reden, een impuls, imitatie of een oude gewoonte.", "explanationNl": "De auteurs vragen wat ons gedrag bestuurt wanneer het verstand die taak niet op zich neemt. Impulsen, grillen, nagebootst gedrag en routines kunnen ongemerkt de leiding krijgen. Wie terugkijkt op eerdere keuzes, ontdekt volgens hen vaak dat er nauwelijks een bewuste afweging aan voorafging. Juist die gevallen behoren tot de beslissingen waarover we later het vaakst spijt hebben. Het praktische onderzoek begint dan bij het herkennen van de kracht die je op dit moment tot handelen aanzet.", "reflectionNl": "Bij welke keuze waar je spijt van hebt kun je achteraf aanwijzen welke impuls het van je afweging won?", "exerciseNl": "Sta vóór één gewoontehandeling even stil en benoem de reden waarom je haar wilt uitvoeren.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "03-31": {"dateKey": "03-31", "day": 31, "month": 3, "sourceTitle": "YOU’RE A PRODUCT OF YOUR TRAINING", "thinker": "Marcus Aurelius", "thoughtNl": "Oefen vandaag de gewoonten die je morgen nodig hebt, zodat je minder afhankelijk wordt van impulsen en omstandigheden.", "explanationNl": "De auteurs vergelijken een ongetrainde geest met een hond die achter auto’s aan mag blijven gaan en met een belegger die zonder discipline gokt. In elk voorbeeld krijgt herhaald, onbegrensd gedrag steeds meer invloed. Ook de geest kan meegesleurd worden door gebeurtenissen en impulsen wanneer zij haar vermogen tot zelfsturing niet ontwikkelt. Verandering vraagt daarom om gewoonten die je nu al begint te trainen. Zo ontstaat meer kans om morgen anders te handelen en minder tijd te steken in onhaalbare of onnodige doelen.", "reflectionNl": "Welke kleine gewoonte zou je morgen helpen op het moment waarop je meestal automatisch reageert?", "exerciseNl": "Koppel één gewenst gedrag vandaag aan een herkenbaar moment, zoals een pauze voor je een antwoord verstuurt.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "04-01": {"dateKey": "04-01", "day": 1, "month": 4, "sourceTitle": "THE COLOR OF YOUR THOUGHTS", "thinker": "Marcus Aurelius", "thoughtNl": "De gedachten die je telkens herhaalt, gaan bepalen wat je opmerkt en welke betekenis je eraan geeft.", "explanationNl": "Holiday en Hanselman vergelijken het denken met een lichaam dat zich naar een vaak herhaalde houding vormt. Ze gebruiken het beeld van een rug die dag na dag in dezelfde houding zit en voeten die steeds in te smalle schoenen worden geduwd. Zo kan ook een vaste instelling geleidelijk je waarneming vormen. Als je vaak uitgaat van het negatieve, ga je gemakkelijker overal iets negatiefs zien. Een gesloten houding kan op dezelfde manier steeds meer ervaringen buitensluiten.", "reflectionNl": "Welk soort detail valt je als eerste op wanneer je de dag met een negatieve verwachting begint?", "exerciseNl": "Zoek vandaag bij één eerste indruk ook een concreet detail dat niet bij je gebruikelijke verwachting past.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "04-02": {"dateKey": "04-02", "day": 2, "month": 4, "sourceTitle": "BE WARY OF WHAT YOU LET IN", "thinker": "Marcus Aurelius", "thoughtNl": "Je kiest niet altijd welke invloeden je tegenkomt. Je kunt wel bepalen hoeveel ruimte ze in je hoofd krijgen.", "explanationNl": "De auteurs vragen hoe moeilijk het wordt om zelf redelijk en meelevend te blijven als de omgeving vooral lage normen, negativiteit of ruzies laat zien. Zulke invloeden zijn nooit helemaal te vermijden. Marcus’ oefening gaat over wat er vervolgens gebeurt: je kunt besluiten hoeveel van dat gedrag of die druk je mee naar binnen neemt. Holiday en Hanselman vergelijken dat met onverwacht bezoek. Iemand kan voor de deur staan zonder dat je diegene hoeft uit te nodigen voor het avondeten.", "reflectionNl": "Welk terugkerend gesprek of programma neemt na afloop meer ruimte in je hoofd in dan je wilt?", "exerciseNl": "Kies vandaag een moment om een bron van andermans ruzie bewust uit te zetten of te verlaten.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "04-03": {"dateKey": "04-03", "day": 3, "month": 4, "sourceTitle": "DECEIVED AND DIVIDED", "thinker": "Seneca", "thoughtNl": "Kijk of je dagelijkse keuzes elkaar helpen of in de weg zitten. Bepaal vervolgens welk verlangen voorrang krijgt.", "explanationNl": "Holiday en Hanselman geven voorbeelden van mensen die iets zeggen te willen en tegelijk gedrag kiezen dat hun doel bemoeilijkt. Iemand wil een goede baan zonder te gaan zoeken. Een bedrijf volgt twee strategieën die elkaar ondermijnen en behaalt met geen van beide succes. Martin Luther King jr. vergeleek verdeeldheid in een mens met een burgeroorlog. In de stoïcijnse lezing kunnen botsende verlangens en scheve oordelen die verdeeldheid aanjagen. De vraag wat je werkelijk nastreeft maakt die tegenstrijdigheden zichtbaar.", "reflectionNl": "Welk doel noem je belangrijk terwijl je gedrag van de afgelopen week ook een ander doel verraadt?", "exerciseNl": "Zet twee botsende keuzes naast elkaar en kies welke vandaag voorrang krijgt.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "04-04": {"dateKey": "04-04", "day": 4, "month": 4, "sourceTitle": "DON’T LET THIS GO TO YOUR HEAD", "thinker": "Marcus Aurelius", "thoughtNl": "Laat bij succes je verstand en karakter richting geven, juist wanneer mensen je vooral vertellen wat je wilt horen.", "explanationNl": "De auteurs proberen zich voor te stellen wat de keizerlijke macht met Marcus Aurelius kon doen. Een positie waar hij volgens hen niet doelbewust naar streefde, bracht immense rijkdom, militair gezag en verering mee. Mensen die iets van hem nodig hadden, hadden redenen om hem naar de mond te praten. Zijn notities dienden om het zicht op wat hij belangrijk vond te bewaren. Holiday en Hanselman trekken die les door naar ieder eigen succes: blijf handelen vanuit dezelfde karaktervastheid en laat het verstand de richting bepalen.", "reflectionNl": "Welke gewoonte wil je behouden als je meer aanzien, geld of verantwoordelijkheid krijgt?", "exerciseNl": "Kies één persoon bij wie je ook na een succes eerlijk tegengas wilt blijven vragen.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "04-05": {"dateKey": "04-05", "day": 5, "month": 4, "sourceTitle": "TRUST, BUT VERIFY", "thinker": "Epictetus", "thoughtNl": "Gebruik je eerste indruk als beginpunt en toets haar voordat je op een mogelijk vooroordeel handelt.", "explanationNl": "Holiday en Hanselman verwijzen naar Malcolm Gladwell om te beschrijven hoe snel mensen nieuwe informatie kunnen plaatsen. Ervaring kan zo in een fractie van een seconde helpen. Hetzelfde vermogen kan echter stereotypen of bestaande aannames bevestigen. Een korte pauze kost weinig en maakt het mogelijk om jezelf af te vragen wat je werkelijk weet, waarom iets je zo raakt en wat je reactie toevoegt. Door de indruk te toetsen kun je bruikbare intuïtie blijven benutten en minder vaak op een scheef oordeel handelen.", "reflectionNl": "Welke persoon beoordeel je erg snel terwijl je maar weinig concrete informatie over diegene hebt?", "exerciseNl": "Schrijf bij één eerste indruk op wat je weet en wat je er zelf bij invult.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "04-06": {"dateKey": "04-06", "day": 6, "month": 4, "sourceTitle": "PREPARE YOURSELF FOR NEGATIVITY", "thinker": "Marcus Aurelius", "thoughtNl": "Reken erop dat mensen soms onaardig of onwetend handelen, zodat je juist meer geduld kunt opbrengen wanneer het gebeurt.", "explanationNl": "De auteurs gebruiken Nicolas Chamforts grap over een pad die je ’s ochtends doorslikt om de rest van de dag beter aan te kunnen. Marcus bereidt zich op vergelijkbare wijze voor op mensen die zelfzuchtig of onwetend reageren. Daarbij hoort ook het besef dat anderen je niet hoeven mee te trekken in hun gedrag en dat je ze als medemensen kunt blijven zien. Het doel van de voorbereiding is dat je, wanneer de irritatie zich voordoet, eerder geduldig, vergevingsgezind en begripvol kunt reageren.", "reflectionNl": "Bij welk gedrag schiet je vaak in dezelfde reactie, ook al weet je dat het geregeld voorkomt?", "exerciseNl": "Bedenk vóór een verwachte irritatie één rustige zin waarmee je het gesprek kunt voortzetten.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "04-07": {"dateKey": "04-07", "day": 7, "month": 4, "sourceTitle": "EXPECT TO CHANGE YOUR OPINIONS", "thinker": "Epictetus", "thoughtNl": "Houd je oordeel voorlopig genoeg om het te herzien zodra je nieuwe informatie krijgt of iets belangrijks blijkt te missen.", "explanationNl": "We beginnen projecten en ontmoetingen geregeld met een opvallende zekerheid over hoe ze zullen verlopen. Holiday en Hanselman wijzen erop hoe vaak latere ervaring die zekerheid onderuit haalt. Ze stellen vragen die blinde vlekken zichtbaar maken, bijvoorbeeld naar wat je nog niet hebt overwogen of naar je eigen aandeel in een probleem. Leg naast wat je werkelijk weet ook vast wat je nog niet weet. Voor de auteurs groeit wijsheid uit de bereidheid om te blijven vragen en je oordeel bij te stellen.", "reflectionNl": "Welke aanname over een lopend plan zou als eerste mogen veranderen als de feiten tegenvallen?", "exerciseNl": "Schrijf bij één plan op welke nieuwe informatie voor jou reden zou zijn om het aan te passen.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "04-08": {"dateKey": "04-08", "day": 8, "month": 4, "sourceTitle": "THE COST OF ACCEPTING COUNTERFEITS", "thinker": "Epictetus", "thoughtNl": "Onderzoek invloedrijke overtuigingen met evenveel zorg als geld dat je op echtheid controleert voordat je het aanneemt.", "explanationNl": "Holiday en Hanselman beschrijven hoe handelaren munten op klank konden onderzoeken en hoe iemand vandaag een biljet tegen het licht houdt. De aandacht die naar geld gaat, steekt af tegen het gemak waarmee we soms een levensbepalende gedachte aannemen. De auteurs noemen het idee dat veel geld iemand vanzelf rijk maakt en de aanname dat brede instemming een bewijs van waarheid is. Epictetus’ maatstaf is volgens hen om indrukken zorgvuldig te onderzoeken voordat je ze jouw handelen laat bepalen.", "reflectionNl": "Welke gangbare overtuiging over succes zou je op zijn waarde toetsen als je haar vandaag voor het eerst hoorde?", "exerciseNl": "Kies één stellige aanname en formuleer welk bewijs je nodig hebt voordat je ernaar handelt.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "04-09": {"dateKey": "04-09", "day": 9, "month": 4, "sourceTitle": "TEST YOUR IMPRESSIONS", "thinker": "Epictetus", "thoughtNl": "Neem een sterk onderbuikgevoel serieus genoeg om het te onderzoeken voordat je het gebruikt als basis voor een besluit.", "explanationNl": "De auteurs zien hoe verleidelijk het is om bij alle regels en cijfers juist volledig op je gevoel te varen. Ze wijzen op aangeleerde vuistregels en evolutionair gevormde reacties die in sommige omstandigheden behulpzaam waren en vandaag tot verkeerde beslissingen kunnen leiden. Een onmiddellijk gevoel kan later aanleiding tot spijt blijken. De stoïcijnse oefening is afstand nemen, de juistheid van de eerste indruk onderzoeken en beoordelen welke indruk constructief genoeg is om werkelijk op voort te bouwen.", "reflectionNl": "Bij welk besluit voelt haast aan als zekerheid, terwijl je nog weinig concrete redenen hebt?", "exerciseNl": "Vergelijk vóór één gevoelsbesluit je eerste reactie met één controleerbaar feit.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "04-10": {"dateKey": "04-10", "day": 10, "month": 4, "sourceTitle": "JUDGMENTS CAUSE DISTURBANCE", "thinker": "Epictetus", "thoughtNl": "Houd wat er gebeurde apart van wat je vreest dat het betekent of wie je ervoor verantwoordelijk houdt.", "explanationNl": "Holiday en Hanselman gebruiken het onderscheid van de Japanse zwaardvechter Musashi tussen het oog dat waarneemt en het oog dat betekenis toekent. Het eerste ziet de feitelijke gebeurtenis. Het tweede komt met een oordeel over wat die gebeurtenis zal aanrichten of wiens schuld het is. Daardoor kan een voorval als een persoonlijke ramp voelen nog voordat de gevolgen bekend zijn. De schrijvers wijzen erop dat die onrust uit het toegevoegde oordeel voortkomt en vervolgens aan het voorval zelf wordt toegeschreven.", "reflectionNl": "Welke voorspelling behandel je na een tegenvaller al als een vaststaand gevolg?", "exerciseNl": "Beschrijf een recente tegenvaller eerst zoals een camera die had kunnen registreren.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "04-11": {"dateKey": "04-11", "day": 11, "month": 4, "sourceTitle": "IF YOU WANT TO LEARN, BE HUMBLE", "thinker": "Epictetus", "thoughtNl": "Je kunt van iemand leren zodra je bereid bent een overtuiging los te laten die je al lang hebt.", "explanationNl": "Epictetus gaf daadwerkelijk les en veel van wat we van hem weten komt uit de aantekeningen van een leerling. Holiday en Hanselman wijzen op een frustratie die hij met veel leraren deelt: leerlingen zeggen graag iets te willen leren en denken heimelijk dat ze alles al weten. Emerson biedt het tegenovergestelde uitgangspunt. Ieder mens kan op een bepaald punt iets van een ander leren. Leraren, filosofen en boeken helpen vooral wanneer je openstaat voor de mogelijkheid dat je bestaande opvatting moet veranderen.", "reflectionNl": "Wat zou iemand met minder ervaring dan jij je vandaag op een specifiek punt kunnen leren?", "exerciseNl": "Vraag iemand hoe die een taak aanpakt die jij doorgaans op je eigen manier doet.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "04-12": {"dateKey": "04-12", "day": 12, "month": 4, "sourceTitle": "REJECT TANTALIZING GIFTS", "thinker": "Seneca", "thoughtNl": "Onderzoek wat een aantrekkelijk aanbod van je vraagt voordat je instemt met de eer, het gemak of het geschenk.", "explanationNl": "In Seneca’s toneelstuk Thyestes gebruikt Atreus geschenken om zijn broer in een val te lokken. Thyestes weigert aanvankelijk, maar laat zich uiteindelijk toch overhalen. De auteurs verbinden de scène met de Amerikaanse generaal Sherman, die een mogelijke kandidatuur voor het presidentschap resoluut afwees. Mensen reageren vaak verbaasd wanneer iemand eer of succes laat lopen. De schrijvers zien in het toneelstuk een waarschuwing voor de aantrekkingskracht van nieuwe, glanzende kansen. Een aantrekkelijk aanbod verdient onderzoek naar wat ermee meekomt.", "reflectionNl": "Welk aanbod zou je anders beoordelen als je alleen kijkt naar de verplichtingen die eraan vastzitten?", "exerciseNl": "Vraag bij een aantrekkelijk voorstel eerst wat er na je instemming van je wordt verwacht.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "04-13": {"dateKey": "04-13", "day": 13, "month": 4, "sourceTitle": "LESS IS MORE", "thinker": "Marcus Aurelius", "thoughtNl": "Schrap een extra woord, uitleg of gebaar wanneer de kern van wat je wilt overbrengen al duidelijk is.", "explanationNl": "De schrijvers wijzen op auteurs die zorgvuldig kiezen wat ze weglaten. Een gedicht van Philip Levine en Gertrudes korte terechtwijzing van de breedsprakige Polonius in Hamlet illustreren hoeveel nadruk beknoptheid kan geven. Vervolgens stellen Holiday en Hanselman zich Marcus voor: iemand met een publiek dat moest luisteren en macht om allerlei dingen te ondernemen, die zichzelf toch voor overdaad waarschuwt. Die herinnering geldt ook wanneer je praat of handelt om indruk te maken. Vraag je dan af wat er werkelijk nodig is.", "reflectionNl": "Waar voeg je doorgaans een extra uitleg toe omdat je graag wilt laten zien hoeveel je weet?", "exerciseNl": "Haal vóór het versturen van één bericht de minst nodige zin weg en lees het opnieuw.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "04-14": {"dateKey": "04-14", "day": 14, "month": 4, "sourceTitle": "BECOMING AN EXPERT IN WHAT MATTERS", "thinker": "Seneca", "thoughtNl": "Besteed ook aandacht aan hoe je leeft, zelfs wanneer je al veel tijd hebt gestoken in vakkennis of hobby’s.", "explanationNl": "Je kunt volgens Holiday en Hanselman veel weten over je beroep, sport of andere interesses en toch nauwelijks weten welke gewoonten je eigen leven sturen. Ze verwijzen naar Seneca’s aansporing aan zijn schoonvader, die een functie rond de graanvoorziening van Rome verloor. De vrijgekomen aandacht kon naar zijn innerlijke leven gaan. De schrijvers vragen welke kennis later meer waarde heeft voor jou en voor anderen: beheersing van feiten over een tijdverdrijf of enig inzicht in sterfelijkheid, geluk en betekenis.", "reflectionNl": "Over welk onderdeel van je eigen leven weet je minder dan over je favoriete hobby, terwijl het meer gevolgen heeft?", "exerciseNl": "Reserveer vijf minuten om één terugkerende gewoonte te onderzoeken alsof je er voor het eerst iets over leert.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "04-15": {"dateKey": "04-15", "day": 15, "month": 4, "sourceTitle": "PAY YOUR TAXES", "thinker": "Seneca", "thoughtNl": "Bij elke keuze hoort een prijs. Neem die mee in je afweging en geef aandacht aan wat je ervoor terugkrijgt.", "explanationNl": "Holiday en Hanselman beginnen bij ergernis over inkomstenbelasting en herinneren aan de diensten die belasting mede mogelijk maakt. Daarna gebruiken ze belasting als beeld voor ongemakken die bij allerlei voordelen horen. Reizen brengt wachttijd, bekendheid brengt geruchten en ook een goede relatie kent meningsverschillen. Stress kan bij succes horen. De schrijvers vragen hoeveel energie je wilt steken in verzet tegen iedere onvermijdelijke bijkomstigheid. Soms geeft het meer rust om een bekende prijs te dragen en tegelijk oog te houden voor wat je daarmee mogelijk maakt.", "reflectionNl": "Welk terugkerend ongemak hoort bij iets waarvoor je ondanks die prijs opnieuw zou kiezen?", "exerciseNl": "Benoem vandaag bij één ergernis welk voordeel en welke kosten voor jou samengaan.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "04-16": {"dateKey": "04-16", "day": 16, "month": 4, "sourceTitle": "OBSERVE CAUSE AND EFFECT", "thinker": "Marcus Aurelius", "thoughtNl": "Volg een terugkerende gedachte tot aan het gedrag dat eruit voortkomt, zodat je ziet waar je kunt ingrijpen.", "explanationNl": "De auteurs leggen een verband tussen het werk van psycholoog Albert Ellis en de doorwerking van stoïcijnse ideeën in cognitieve gedragstherapie. Ze lezen Marcus’ aantekening als een uitnodiging om de volgorde van je eigen gedachten en daden te observeren. Kijk waar een gedachte vandaan komt, welke aannames meespelen en tot welk gedrag ze leidt. Sommige patronen zijn behulpzaam, andere eindigen telkens in een fout of spijt. Door oorzaak en gevolg herkenbaar te maken, krijg je een plek om te beginnen met veranderen.", "reflectionNl": "Welke gedachte gaat vaak vooraf aan een reactie waar je achteraf spijt van hebt?", "exerciseNl": "Houd vandaag één reeks bij met een aanleiding, je gedachte, je gedrag en het gevolg.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "04-17": {"dateKey": "04-17", "day": 17, "month": 4, "sourceTitle": "NO HARM, NO FOUL", "thinker": "Marcus Aurelius", "thoughtNl": "Laat bij een dubbelzinnige opmerking ruimte voor meerdere bedoelingen voordat je beslist hoe je erop reageert.", "explanationNl": "Holiday en Hanselman wijzen erop dat hetzelfde woord of dezelfde opmerking afhankelijk van context, toon en bedoeling iets onschuldigs of iets kwetsends kan zijn. De gekozen interpretatie kan het verschil maken tussen samen lachen, gekwetst raken of ruzie krijgen. Ze vragen welke vooringenomenheid je naar gesprekken meeneemt en wat je doorgaans als eerste over iemands intentie aanneemt. Door een redelijke uitleg te zoeken die bij de feiten past, wordt het gemakkelijker om een reactie te kiezen die bij de werkelijke situatie past.", "reflectionNl": "Welke bedoeling neem je automatisch aan wanneer een kort bericht van iemand afstandelijk overkomt?", "exerciseNl": "Vraag bij één dubbelzinnige uitspraak wat de ander precies bedoelt voordat je erop reageert.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "04-18": {"dateKey": "04-18", "day": 18, "month": 4, "sourceTitle": "OPINIONS ARE LIKE . . .", "thinker": "Epictetus", "thoughtNl": "Laat vandaag een overbodig oordeel weg en kijk welke eigenschappen van de situatie dan vanzelf overblijven.", "explanationNl": "Volgens de auteurs leggen we vrijwel voortdurend een mening over de wereld heen, van het weer tot politiek, andermans opmerkingen en ons eigen succes. Verwachtingen, aanspraken, cultuur en soms onwetendheid beïnvloeden hoe we oordelen. Die extra laag kan voortdurend aanleiding geven tot boosheid en onrust. Epictetus’ oefening krijgt bij Holiday en Hanselman de vorm van wieden. Haal eens een oordeel weg dat je niet nodig hebt om te handelen. Er blijft een gebeurtenis of toestand over die je eenvoudig kunt waarnemen.", "reflectionNl": "Welk dagelijks verschijnsel krijgt van jou steeds hetzelfde oordeel terwijl je er vandaag niets mee hoeft te doen?", "exerciseNl": "Beschrijf het weer één keer in concrete waarnemingen, zonder het prettig of vervelend te noemen.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "04-19": {"dateKey": "04-19", "day": 19, "month": 4, "sourceTitle": "OUR SPHERE OF IMPULSES", "thinker": "Marcus Aurelius, met Epictetus", "thoughtNl": "Gebruik invloed met oog voor het gemeenschappelijk belang en blijf bereid iets te leren van mensen met weinig macht.", "explanationNl": "De auteurs merken op dat keizer Marcus wijsheid van Epictetus, een voormalige slaaf, in zijn notities opnam. Ze zien iets vergelijkbaars in het contact tussen Abraham Lincoln en Frederick Douglass. De afkomst of positie van een spreker zegt weinig over hoeveel je van diens ervaring kunt leren. Tegelijk herinnert de passage mensen met gezag eraan hun impulsen te toetsen en de grenzen van hun invloed te zien. Bij macht én machteloosheid blijven het algemeen belang, de werkelijke waarde van dingen en ruimte voor onverwachte omstandigheden van belang.", "reflectionNl": "Wie kent de gevolgen van jouw besluit uit eigen ervaring en heb je nog niet gehoord?", "exerciseNl": "Vraag vandaag één betrokkene met weinig invloed op een besluit hoe het in de praktijk uitpakt.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "04-20": {"dateKey": "04-20", "day": 20, "month": 4, "sourceTitle": "REAL GOOD IS SIMPLE", "thinker": "Marcus Aurelius", "thoughtNl": "Wijsheid, zelfbeheersing, rechtvaardigheid en moed bieden een vorm van waarde die geld en bekendheid op zichzelf niet leveren.", "explanationNl": "De auteurs onderscheiden wat mensen om ons heen aanprijzen van de eigenschappen die de stoïcijnen werkelijk waardevol vinden. Seneca’s toneelwerk herinnert aan de angsten die ook rijke mensen kunnen hebben. Wie geld of status bereikt, kan ontdekken dat die verworvenheden weinig oplossen van de onvrede waarvoor ze bedoeld waren. Bij wijsheid, zelfbeheersing, rechtvaardigheid en moed verwachten de schrijvers die teleurstelling niet. Deze eigenschappen maken het mogelijk beter te handelen, en hun waarde hangt niet af van hoeveel aanzien ze opleveren.", "reflectionNl": "Welke eigenschap zou een probleem vandaag beter helpen oplossen dan het krijgen van meer erkenning?", "exerciseNl": "Kies één gelegenheid vandaag om moed, rechtvaardigheid, wijsheid of zelfbeheersing concreet te oefenen.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "04-21": {"dateKey": "04-21", "day": 21, "month": 4, "sourceTitle": "DON’T LET YOUR ATTENTION SLIDE", "thinker": "Epictetus", "thoughtNl": "Train je aandacht door terug te keren naar wat je hebt gekozen, voordat elke onderbreking een nieuwe gewoonte wordt.", "explanationNl": "Holiday en Hanselman halen via Winifred Gallagher een vergelijking met Einstein aan om de waarde van geconcentreerd nadenken zichtbaar te maken. Ze plaatsen die naast de veelheid aan apps, berichten en artikelen die om aandacht vragen. Epictetus’ waarschuwing gaat volgens hen verder dan de tijd die je aan een enkele onderbreking verliest. Aandacht is een gewoonte. Telkens afdwalen maakt verder afdwalen gemakkelijker en vergroot de kans op fouten. Bewaak daarom de aandacht die je nodig hebt om af te maken wat je kiest.", "reflectionNl": "Welke kleine onderbreking lokt je geregeld weg terwijl je nog midden in een taak zit?", "exerciseNl": "Zet voor één taak tien minuten de meldingen uit en leg een blad klaar voor invallen die kunnen wachten.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "04-22": {"dateKey": "04-22", "day": 22, "month": 4, "sourceTitle": "THE MARKS OF A RATIONAL PERSON", "thinker": "Marcus Aurelius", "thoughtNl": "Kijk naar binnen, onderzoek jezelf kritisch en gebruik dat onderzoek om zelfstandig te beslissen, ook wanneer anderen iets anders verwachten.", "explanationNl": "De auteurs brengen de oefening voor redelijk handelen terug tot drie stappen. Richt eerst je aandacht op wat er in jezelf omgaat. Kijk vervolgens met een kritische blik naar wat je daar aantreft. Beslis ten slotte zelf, met zo weinig mogelijk invloed van vooringenomenheid of wat gangbaar is. De eerste twee stappen maken de derde beter uitvoerbaar: als je ziet hoe je eigen oordeel tot stand komt, kun je gerichter bepalen waarop je besluit zal rusten.", "reflectionNl": "Welk besluit zou je opnieuw willen overwegen zonder je gebruikelijke voorkeur en de mening van de groep meteen te volgen?", "exerciseNl": "Schrijf bij één keuze achtereenvolgens je eerste indruk, een kritische vraag daarover en je eigen besluit op.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "04-23": {"dateKey": "04-23", "day": 23, "month": 4, "sourceTitle": "THE MIND IS ALL YOURS", "thinker": "Marcus Aurelius", "thoughtNl": "Zorg bewust voor je denken en oordelen. Daar heb je volgens Marcus meer zeggenschap over dan over je lichaam.", "explanationNl": "Marcus onderscheidt hier lichaam, adem en geest. Holiday en Hanselman wijzen op ziekte, een ongeluk of gevangenschap als voorbeelden van omstandigheden die lichaam en adem kunnen treffen. Die twee verdienen aandacht, maar ontsnappen in belangrijke mate aan onze invloed. De auteurs vergelijken het verschil met de zorg die je hebt voor een huurhuis tegenover de zorg voor iets dat werkelijk van jou is. Met dat beeld vragen ze je bewust om te gaan met je denken en je oordelen, het deel dat Marcus als het meest eigene beschouwt.", "reflectionNl": "Welke gedachte verdient vandaag zorg van jou, ook als je de lichamelijke omstandigheden niet meteen kunt veranderen?", "exerciseNl": "Geef vijf minuten aandacht aan één oordeel dat je kunt onderzoeken, bijvoorbeeld door er twee mogelijke verklaringen bij te schrijven.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "04-24": {"dateKey": "04-24", "day": 24, "month": 4, "sourceTitle": "A PRODUCTIVE USE FOR CONTEMPT", "thinker": "Marcus Aurelius", "thoughtNl": "Haal iets wat je sterk begeert terug tot zijn gewone bestanddelen, zodat je het met wat meer afstand kunt beoordelen.", "explanationNl": "De schrijvers bespreken een oefening waarbij Marcus iets verleidelijks beschrijft in ontluisterende, concrete termen. De vreemde beschrijving van seks moet wat tegenwicht bieden aan de sterke neiging om achter een prettig gevoel aan te gaan. Hetzelfde kun je doen bij een zorgvuldig geënsceneerde foto of een promotie waar je veel van verwacht. Kijk welk werk, welke toevalligheden en welke gewone details achter de indrukwekkende buitenkant zitten. Voor Holiday en Hanselman kan dat de verleiding minder overweldigend maken en ruimte geven voor een objectiever oordeel.", "reflectionNl": "Welk beeld of vooruitzicht krijgt voor jou bijna magische aantrekkingskracht zolang je het alleen van zijn mooiste kant ziet?", "exerciseNl": "Beschrijf iets waar je jaloers op bent in drie feitelijke details over hoe het tot stand komt.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "04-25": {"dateKey": "04-25", "day": 25, "month": 4, "sourceTitle": "THERE’S NOTHING WRONG WITH BEING WRONG", "thinker": "Marcus Aurelius", "thoughtNl": "Wanneer iemand een echte fout in je oordeel laat zien, mag je van mening veranderen en verder denken.", "explanationNl": "Holiday en Hanselman vertellen hoe Cicero reageerde toen iemand hem op een vroegere, afwijkende mening wees. Voor hem hoorde bij vrij oordelen dat hij kon uitspreken wat hem op dat moment aannemelijk leek. De auteurs halen ook Emerson aan over de neiging om consequent te willen lijken. Wie zich bewust blootstelt aan kennis, zal juist soms ontdekken eerder verkeerd te hebben gedacht. Een terecht bezwaar biedt dan een kans om je oordeel of handelen te verbeteren zonder je vast te klampen aan je eerdere woorden.", "reflectionNl": "Welke opvatting houd je nog aan omdat je haar ooit met veel overtuiging hebt verdedigd?", "exerciseNl": "Noem één punt waarop je inmiddels anders denkt en schrijf op welke reden jou van mening deed veranderen.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "04-26": {"dateKey": "04-26", "day": 26, "month": 4, "sourceTitle": "THINGS HAPPEN IN TRAINING", "thinker": "Marcus Aurelius", "thoughtNl": "Zie een lastige ontmoeting als oefening. Een fout kan jou en de ander iets leren over hoe jullie reageren.", "explanationNl": "De auteurs stellen voor alledaagse situaties te bekijken zoals een trainingspartij. Daarmee krijgt een fout van jezelf of een ander minder gewicht dan wanneer iedere ontmoeting als een finale voelt. Een ongelukkige elleboogstoot tijdens het sparren kan pijn doen en tegelijk iets duidelijk maken over degene tegenover je. Je reactie geeft de ander op zijn beurt informatie over jou. Holiday en Hanselman verwachten dat die instelling ruimte geeft om een onaangename gebeurtenis te verwerken en aan beide kanten iets te leren.", "reflectionNl": "Welke ontmoeting voelde als een beslissende proef terwijl je haar ook als oefening had kunnen behandelen?", "exerciseNl": "Noteer na één lastig gesprek wat je over je eigen reactie en over de ander hebt geleerd.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "04-27": {"dateKey": "04-27", "day": 27, "month": 4, "sourceTitle": "TURN IT INSIDE OUT", "thinker": "Marcus Aurelius", "thoughtNl": "Verander van gezichtspunt als je vastloopt. Kijk bij tegenslag naar de feiten en bij uiterlijk vertoon naar wat erachter zit.", "explanationNl": "Holiday en Hanselman geven twee manieren om een situatie scherper te zien. Bij een mogelijke tegenslag kan een feitelijke blik helpen om te registreren wat er gebeurt zonder onmiddellijk oorzaken of verborgen betekenissen in te vullen. Bij iets indrukwekkends kan het juist zin hebben te onderzoeken waaruit het bestaat en wat buiten beeld blijft. Ze stellen voor hetzelfde te doen met angst voor de dood of onbekendheid en met een imponerende ceremonie. Een andere kijk kan verminderen hoe sterk angst of bewondering je oordeel stuurt.", "reflectionNl": "Wat verandert er aan iets dat je vandaag ontzag inboezemt wanneer je het van dichtbij bekijkt?", "exerciseNl": "Kies één gebeurtenis en schrijf zowel een feitelijke beschrijving als een korte schets van wat doorgaans buiten beeld blijft.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "04-28": {"dateKey": "04-28", "day": 28, "month": 4, "sourceTitle": "WANTS MAKE YOU A SERVANT", "thinker": "Seneca", "thoughtNl": "Andermans invloed groeit wanneer je sterk verlangt naar wat die persoon kan geven. Onderzoek waar je wat losser kunt laten.", "explanationNl": "Holiday en Hanselman bespreken hoeveel invloed we soms zelf aan anderen geven omdat we inkomen, erkenning of aansluiting zoeken. Als voorbeeld noemen ze modefotograaf Bill Cunningham, die soms geen rekening stuurde omdat betaling opdrachtgevers meer gelegenheid zou geven hem te vertellen wat hij moest doen. De schrijvers lezen daarin dezelfde gedachte als bij Seneca. Wie minder afhankelijk wordt van de beloning of instemming die een ander kan geven, kan op dat punt meer vrijheid krijgen om zelf te kiezen.", "reflectionNl": "Bij wiens goedkeuring pas je jezelf het sterkst aan, en wat wil je er precies voor terugkrijgen?", "exerciseNl": "Kies één kleine beslissing waarbij je je vandaag minder laat leiden door de wens om erbij te horen.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "04-29": {"dateKey": "04-29", "day": 29, "month": 4, "sourceTitle": "WASHING AWAY THE DUST OF LIFE", "thinker": "Marcus Aurelius", "thoughtNl": "Kijk naar de nachtelijke hemel en geef dagelijkse beslommeringen even een plek binnen iets wat veel groter is.", "explanationNl": "Holiday en Hanselman halen Neil deGrasse Tyson aan om twee ervaringen bij de sterrenhemel te beschrijven. Je merkt hoe klein je bent en kunt tegelijk verbondenheid voelen met het grotere geheel. Doordat we voortdurend onze eigen omstandigheden beleven, kunnen ze al snel het middelpunt lijken. De auteurs vinden bij Marcus en Seneca een aansporing om regelmatig naar natuur en kosmos te kijken. Het zicht op die grotere schaal kan relativeren wat op een gewone dag alle aandacht opeist.", "reflectionNl": "Welke kleine ergernis krijgt een andere plaats als je haar bekijkt na een paar minuten onder de open hemel?", "exerciseNl": "Kijk vanavond even omhoog naar de hemel en merk op hoe je daarna naar één zorg van vandaag kijkt.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "04-30": {"dateKey": "04-30", "day": 30, "month": 4, "sourceTitle": "WHAT IS IN KEEPING WITH YOUR CHARACTER?", "thinker": "Epictetus", "thoughtNl": "Onderzoek de gewoonten en verwachtingen die je volgt, zodat je kunt kiezen welke overtuigingen werkelijk bij je karakter passen.", "explanationNl": "De auteurs vergelijken vanzelfsprekende meningen met onzichtbare instructies die je kunt volgen zonder hun oorsprong te kennen. Door die patronen te bevragen en te toetsen aan wat je leert, kun je overtuigingen ontwikkelen die je zelf begrijpt en onderschrijft. Dat geeft karakter gewicht in een omgeving die je op allerlei manieren probeert te verleiden of te veranderen. Weten waarin je gelooft en waarom helpt volgens Holiday en Hanselman om keuzes te herkennen die slecht bij je passen, van een baan tot een vriendschap.", "reflectionNl": "Welke regel volg je al jaren terwijl je nog nooit hebt onderzocht of die bij jouw overtuigingen past?", "exerciseNl": "Kies één regel die je uit gewoonte volgt en schrijf op welke eigen reden je hebt om haar te behouden.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "05-01": {"dateKey": "05-01", "day": 1, "month": 5, "sourceTitle": "MAKE CHARACTER YOUR LOUDEST STATEMENT", "thinker": "Musonius Rufus", "thoughtNl": "Wat mensen over je karakter leren, zit in hoe je handelt als er weinig aan je uiterlijk valt af te lezen.", "explanationNl": "De auteurs noemen herkenbare uiterlijke tekens van verschillende beroepen en levenswijzen, zoals het gewaad van een monnik en het kostuum van een bankier. Bij iemand die stoïcijns leeft, helpt zo'n herkenningsteken je nergens mee. Je kunt aan iemands kleding, stem of uitstraling nauwelijks zien of diegene aandacht heeft voor wat een situatie vraagt. Dat blijkt gaandeweg uit het karakter dat zichtbaar wordt in de manier waarop iemand handelt.", "reflectionNl": "Welke gewoonte zou iemand die je vandaag tegenkomt iets over je karakter vertellen?", "exerciseNl": "Doe één klein behulpzaam ding en laat het daarbij.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "05-02": {"dateKey": "05-02", "day": 2, "month": 5, "sourceTitle": "BE THE PERSON YOU WANT TO BE", "thinker": "Epictetus", "thoughtNl": "Bepaal welk karakter je wilt ontwikkelen en geef dat besluit vandaag vorm met een handeling die erbij past.", "explanationNl": "Met het voorbeeld van een boogschutter leggen de auteurs uit waarom richting en uitvoering allebei nodig zijn. Eerst moet je weten waarop je wilt mikken. Daarvoor loont het om ongestoord stil te staan bij wat voor jou werkelijk belangrijk is. Vervolgens bepaalt wat je doet of je daar dichterbij komt. Gericht kiezen betekent ook andere doelen laten liggen. Een verlangen wordt pas richtinggevend als het merkbaar invloed heeft op hoe je je tijd en aandacht gebruikt.", "reflectionNl": "Welke keuze vandaag past bij de persoon die je wilt worden?", "exerciseNl": "Reserveer vijf minuten om één prioriteit te kiezen en zet daarna de eerste stap.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "05-03": {"dateKey": "05-03", "day": 3, "month": 5, "sourceTitle": "SHOW, NOT TELL, WHAT YOU KNOW", "thinker": "Epictetus", "thoughtNl": "Laat een inzicht dat je waardevol vindt zichtbaar worden in een keuze die iemand daadwerkelijk van je kan merken.", "explanationNl": "Een bondige spreuk onthouden en op het juiste moment aanhalen kan indruk maken. De auteurs leggen de lat voor filosofie hoger. Wat je hebt geleerd, moet eerst genoeg tot je doordringen om je oordeel en gedrag te veranderen. Ze verbinden dat met Musonius Rufus, voor wie goed onderricht in de praktijk terugkomt als goed handelen. Als je merkt dat je iemand graag de les wilt lezen, biedt de situatie vaak ook een gelegenheid om het inzicht zelf voor te leven.", "reflectionNl": "Welk advies dat je vaak geeft, zou vandaag overtuigender worden als je het zelf toepast?", "exerciseNl": "Vervang vandaag één ongevraagd advies door een handeling die hetzelfde laat zien.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "05-04": {"dateKey": "05-04", "day": 4, "month": 5, "sourceTitle": "WHAT’S TRULY IMPRESSIVE", "thinker": "Musonius Rufus", "thoughtNl": "Bewonder hoe iemand geld en aanzien inzet voor anderen, want daarin wordt zichtbaar wat diegene belangrijk vindt.", "explanationNl": "Verhalen over de extravagante aankopen van rijke mensen trokken volgens de auteurs in Rome al dezelfde aandacht als tegenwoordig. Wie daarvoor geld genoeg heeft, kan gemakkelijk indruk maken met uitgaven en er precies de gewenste reputatie mee opbouwen. Moeilijker vinden de auteurs het om privileges ter beschikking van anderen te stellen. Als voorbeelden noemen ze Marcus Aurelius, die keizerlijke bezittingen verkocht om oorlogsschulden te betalen, en José Mujica, die een groot deel van zijn presidentssalaris weggaf.", "reflectionNl": "Bij wiens omgang met geld bewonder je de keuzes die diegene ermee maakt?", "exerciseNl": "Gebruik een klein bedrag of wat tijd voor iets waar iemand anders concreet baat bij heeft.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "05-05": {"dateKey": "05-05", "day": 5, "month": 5, "sourceTitle": "YOU ARE THE PROJECT", "thinker": "Epictetus", "thoughtNl": "Behandel je manier van denken en oordelen als iets waarin je door geregelde oefening bedrevener kunt worden.", "explanationNl": "Bij uiteenlopende beroepen vinden we het vanzelfsprekend dat iemand tijd investeert in het oefenen van zijn vak. De materialen en omstandigheden verschillen, maar vakmanschap ontstaat doordat iemand er steeds opnieuw mee werkt en kleine verbeteringen maakt. De auteurs passen dat beeld toe op het innerlijke werk van de stoïcijn. Het belangrijkste materiaal is je eigen denk- en oordeelsvermogen. Dat verdient zowel oefening als aandacht voor de manier waarop het functioneert, juist omdat je het bij zo veel keuzes gebruikt.", "reflectionNl": "In welk terugkerend soort situatie wil je je oordeel beter leren kennen?", "exerciseNl": "Noteer bij één lastige keuze welk feit, welke aanname en welk principe je oordeel sturen.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "05-06": {"dateKey": "05-06", "day": 6, "month": 5, "sourceTitle": "RIGHTEOUSNESS IS BEAUTIFUL", "thinker": "Epictetus", "thoughtNl": "Rechtvaardigheid, zelfbeheersing en kalmte geven je een vorm van schoonheid die je zelf kunt ontwikkelen.", "explanationNl": "Veel moderne schoonheidsidealen belonen kenmerken waar je grotendeels mee geboren wordt, zoals lengte of gezichtsvorm. De auteurs stellen daar de schoonheid tegenover die in beslissingen en gedrag zichtbaar wordt. Ze noemen een gevoel voor rechtvaardigheid, een gelijkmatig humeur en trouw aan je verantwoordelijkheid. Zulke eigenschappen worden geoefend in situaties waarin ze moeite kosten of iets van je vragen. Dat geeft je vandaag al invloed op wat een mooi mens zijn concreet kan betekenen.", "reflectionNl": "Bij welke ontmoeting kun je vandaag iets van de eigenschappen laten zien die je zelf bewondert?", "exerciseNl": "Kies voor één lastig gesprek vooraf welke vorm van zelfbeheersing je wilt oefenen.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "05-07": {"dateKey": "05-07", "day": 7, "month": 5, "sourceTitle": "HOW TO HAVE A GOOD DAY", "thinker": "Epictetus", "thoughtNl": "Geef vandaag zelf iets goeds aan je dag door iets te doen dat je oprecht goed vindt.", "explanationNl": "Voor de auteurs is goed handelen de betrouwbaarste bron van een goede dag. De gebruikelijke redenen om tevreden te zijn, zoals een gunstige afloop of iets plezierigs dat je toevallig krijgt, hangen vaak af van omstandigheden. Sommige zijn bovendien snel uitgeput. Een goede handeling blijft een mogelijkheid die van je eigen keuze afhangt. Daardoor kun je ook op een teleurstellende dag iets waardevols toevoegen, zonder te wachten tot de situatie omslaat.", "reflectionNl": "Welke handeling zou je vanavond waarderen, ongeacht hoe je dag verder verloopt?", "exerciseNl": "Doe vandaag één concrete goede daad waar je zelf over kunt beslissen.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "05-08": {"dateKey": "05-08", "day": 8, "month": 5, "sourceTitle": "GOOD AND EVIL? LOOK AT YOUR CHOICES", "thinker": "Epictetus", "thoughtNl": "Beoordeel je beslissing op de redenen ervoor, want beloning en succes vertellen je weinig over haar morele waarde.", "explanationNl": "In de loop van de dag kunnen gebeurtenissen en mogelijke gevolgen door elkaar gaan lopen als je probeert te bepalen wat juist is. De auteurs gebruiken Epictetus om de beoordeling eenvoudiger te maken. Het morele gewicht ligt in de keuze die jij met je verstand maakt. Een beloning zegt daar weinig over, en ook een gunstige uitkomst beslist de vraag niet. Bij twijfel kun je je aandacht weer richten op de redenen die je hebt om een bepaalde handeling te kiezen.", "reflectionNl": "Welke beslissing vind je verdedigbaar, zelfs als ze je niets oplevert?", "exerciseNl": "Schrijf bij één keuze de inhoudelijke reden op voordat je de mogelijke beloning meeweegt.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "05-09": {"dateKey": "05-09", "day": 9, "month": 5, "sourceTitle": "CARPE DIEM", "thinker": "Seneca", "thoughtNl": "Geef deze dag bewust vorm terwijl hij nog openligt, want dezelfde uren komen nooit meer terug.", "explanationNl": "De auteurs brengen Seneca's aandacht voor de vluchtigheid van tijd terug tot één dag. Je kunt deze dag maar één keer meemaken en zodra hij voorbij is, kun je de keuzes van vandaag niet terughalen. Hun uitnodiging is om de beschikbare uren actief te bewonen en naar vermogen te gebruiken. De vraag wat je morgen over vandaag zou kunnen vertellen, maakt zichtbaar of je deze dag zelf vorm hebt gegeven of hem ongemerkt hebt laten verlopen.", "reflectionNl": "Welk moment wil je vanavond kunnen aanwijzen als iets dat je bewust hebt gedaan?", "exerciseNl": "Geef één gekozen activiteit vandaag tien minuten onverdeelde aandacht.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "05-10": {"dateKey": "05-10", "day": 10, "month": 5, "sourceTitle": "DON’T BE INSPIRED, BE INSPIRATIONAL", "thinker": "Seneca", "thoughtNl": "Maak van bewondering voor een voorbeeld één eigen daad die iets van dezelfde deugd in praktijk brengt.", "explanationNl": "De auteurs vergelijken politieke lof over grote prestaties uit het verleden met het bewonderen van inspirerende spreuken. Demosthenes zag volgens hen hoe graag mensen luisteren naar verhalen over hun voorouders, terwijl zulke verhalen gemakkelijk bij zelfvoldaanheid blijven steken. De oorspronkelijke waarde van een voorbeeld ligt in de deugden die anderen ermee kunnen oefenen. Dat geldt ook voor de woorden in dit boek. De bewondering krijgt betekenis zodra zij uitmondt in iets wat je zelf doet.", "reflectionNl": "Van wiens voorbeeld kun je vandaag één eigenschap navolgen in een gewone situatie?", "exerciseNl": "Kies een inspirerende gedachte en vertaal haar naar een handeling die vandaag binnen bereik ligt.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "05-11": {"dateKey": "05-11", "day": 11, "month": 5, "sourceTitle": "GUILT IS WORSE THAN JAIL", "thinker": "Seneca", "thoughtNl": "Wie iets verkeerds moet blijven verbergen, betaalt daarvoor vaak al voordat iemand anders er iets van merkt.", "explanationNl": "De auteurs beschrijven waarom iemand na jaren op de vlucht alsnog zichzelf aangeeft. De voortdurende spanning en schuld kunnen zwaarder worden dan het vooruitzicht op straf. Ze herkennen hetzelfde mechanisme in het opbiechten van een leugen of ontrouw waarvan de ander niets wist. Verkeerd handelen heeft dus ook voor degene die het doet een prijs. Achter de beslissing om verantwoordelijkheid te nemen kan een verlangen schuilgaan naar de rust die eerlijk handelen mogelijk maakt.", "reflectionNl": "Welke kleine onwaarheid kost je meer aandacht dan je had verwacht?", "exerciseNl": "Neem bij een kleine fout één concrete stap om die recht te zetten.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "05-12": {"dateKey": "05-12", "day": 12, "month": 5, "sourceTitle": "KINDNESS IS ALWAYS THE RIGHT RESPONSE", "thinker": "Marcus Aurelius", "thoughtNl": "Oprechte vriendelijkheid tegenover iemand die scherp doet, vraagt zelfbeheersing en kan de verwachte ruzie doorbreken.", "explanationNl": "Op vijandigheid volgt gemakkelijk opnieuw vijandigheid. De auteurs vragen wat er gebeurt als je jezelf daar niet alleen van weerhoudt, maar ook oprecht vriendelijk reageert. Zo'n antwoord doorbreekt de reactie waarop de ander rekende en kan diegene aan het denken zetten. Ze verbinden dat met het Bijbelse idee om goed te doen voor je vijand. Achter grofheid gaat volgens hen vaak zwakte schuil. Vriendelijkheid bewaren in zo'n ontmoeting vraagt juist innerlijke kracht.", "reflectionNl": "Welke vriendelijke reactie zou je kunnen geven als iemand vandaag kortaf tegen je doet?", "exerciseNl": "Formuleer één rustige zin waarmee je een scherpe opmerking kunt beantwoorden.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "05-13": {"dateKey": "05-13", "day": 13, "month": 5, "sourceTitle": "FUELING THE HABIT BONFIRE", "thinker": "Epictetus", "thoughtNl": "Elke herhaling oefent een gewoonte, dus kijk welke versie van jezelf je deze week vaker hebt ingeoefend.", "explanationNl": "De auteurs betrekken de gedachte dat we door herhaald gedrag gevormd worden ook op onze gedachten. Een enkele boze reactie heeft bijvoorbeeld een onmiddellijk effect en maakt tegelijk dat die manier van reageren vertrouwder wordt. Daardoor vertellen je dagelijkse bezigheden en denkpatronen iets over wie je aan het worden bent. Kijk volgens hen zowel terug op de afgelopen week als vooruit naar wat je van plan bent. Beide laten zien hoeveel ruimte de gewoonten krijgen die passen bij wie je wilt zijn.", "reflectionNl": "Welk patroon van afgelopen week wil je volgende week minder vaak herhalen?", "exerciseNl": "Kies voor één herkenbare aanleiding alvast de reactie die je ervoor in de plaats wilt oefenen.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "05-14": {"dateKey": "05-14", "day": 14, "month": 5, "sourceTitle": "OUR WELL-BEING LIES IN OUR ACTIONS", "thinker": "Marcus Aurelius", "thoughtNl": "Zoek voldoening in wat je met aandacht en volle inzet doet, ook als de uitkomst onzeker blijft.", "explanationNl": "Als tevredenheid afhangt van applaus, succes of bereikte doelen, kunnen omstandigheden haar elk moment onderuit halen. De auteurs gebruiken een acteur als voorbeeld. De ontvangst van het werk ligt bij publiek en recensenten, terwijl de acteur wel invloed heeft op de zorg en inzet waarmee de rol gespeeld wordt. Diezelfde verschuiving kun je maken bij je eigen doelen. Je kunt voluit spelen, proberen te helpen en zorgvuldig reageren. Daarin ligt een steviger vorm van voldoening dan in waardering die iemand anders moet geven.", "reflectionNl": "Welke inspanning zou je vandaag zelf waarderen als niemand haar opmerkt?", "exerciseNl": "Kies voor één taak een maatstaf die je zelf kunt beïnvloeden en beoordeel jezelf daarop.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "05-15": {"dateKey": "05-15", "day": 15, "month": 5, "sourceTitle": "COUNT YOUR BLESSINGS", "thinker": "Marcus Aurelius", "thoughtNl": "Kijk met frisse ogen naar wat je al hebt en gebruik het vandaag met aandacht en waardering.", "explanationNl": "De auteurs beschrijven hoe mensen elkaar proberen bij te houden terwijl de anderen mogelijk hetzelfde doen. Die wederzijdse vergelijking voedt het verlangen om steeds meer te verzamelen. Hun advies is te zien wat er al beschikbaar is en er bewust iets mee te doen. De gedachte van Marcus die eraan voorafgaat geeft daar een tweede kant aan. Je kunt je voorstellen hoe graag je iets zou willen als je het nog miste, en het tegelijk waarderen met ruimte voor de mogelijkheid dat je het ooit kwijtraakt.", "reflectionNl": "Wat bezit je al dat je graag zou willen hebben als het er vandaag ineens niet was?", "exerciseNl": "Gebruik of verzorg vandaag iets goeds dat je normaal vanzelfsprekend vindt.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "05-16": {"dateKey": "05-16", "day": 16, "month": 5, "sourceTitle": "THE CHAIN METHOD", "thinker": "Epictetus", "thoughtNl": "Een ongewenste gewoonte verliest terrein wanneer je één dag oefent en die oefening morgen bewust herhaalt.", "explanationNl": "De auteurs vertellen hoe Jerry Seinfeld een beginnende komiek aanraadde elke schrijfdag op de kalender te markeren. Een reeks kruisjes maakt de opgebouwde regelmaat zichtbaar en kan helpen om door te gaan. Epictetus stelde volgens hen een soortgelijke aanpak voor om een ongewenste gewoonte af te bouwen, bijvoorbeeld opvliegend reageren. Daarbij begint vooruitgang met één dag waarop het lukt, gevolgd door nog zo'n dag. Je maakt de opgave hanteerbaar door te kijken naar wat je vandaag kunt oefenen.", "reflectionNl": "Welke concrete reactie wil je vandaag één keer met meer zelfbeheersing aanpakken?", "exerciseNl": "Markeer vanavond op je kalender of je de gekozen reactie hebt geoefend.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "05-17": {"dateKey": "05-17", "day": 17, "month": 5, "sourceTitle": "THE STOIC IS A WORK IN PROGRESS", "thinker": "Epictetus", "thoughtNl": "De stoïcijnse oefening duurt je hele leven en krijgt vorm in kleine stappen die je blijft herhalen.", "explanationNl": "De auteurs zien filosofie als een levenslange praktijk. Het beeld van de volmaakte stoïcijn helpt als richtpunt, maar Epictetus daagde zijn leerlingen uit om vooral werkelijk te laten zien dat ze zich nog aan het vormen waren. Zelfgenoegzaamheid over vooruitgang kan het dagelijkse trainen in de weg staan. Een plotseling inzicht geeft hooguit een begin. Wat verschil maakt, is het volhouden van de oefening, ook wanneer er niemand meekijkt en je merkt dat er nog veel te leren valt.", "reflectionNl": "Welke vaardigheid blijft oefening vragen, ook al vind je jezelf er al redelijk goed in?", "exerciseNl": "Kies één situatie van vandaag om een vertrouwd principe nog eens bewust toe te passen.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "05-18": {"dateKey": "05-18", "day": 18, "month": 5, "sourceTitle": "HOW YOU DO ANYTHING IS HOW YOU DO EVERYTHING", "thinker": "Marcus Aurelius", "thoughtNl": "De aandacht waarmee je een gewone taak doet, oefent de manier waarop je ook grotere taken aanpakt.", "explanationNl": "Vooruitdenken en terugkijken vragen vaak minder moeite dan werkelijk aandacht schenken aan een taak die tegenstaat. De auteurs herkennen de neiging om zo'n taak weg te zetten als bijzaak, bijvoorbeeld omdat je werk niet helemaal uitdrukt wie je bent. Toch telt de manier waarop je de eerstvolgende minuut besteedt. Daarin oefen je een houding die ook op andere momenten terugkomt. De nadruk ligt op het concrete werk dat nu voor je ligt, hoe alledaags dat ook lijkt.", "reflectionNl": "Welke taak doe je vaak half omdat je haar onbelangrijk vindt?", "exerciseNl": "Doe die taak vandaag van begin tot einde met dezelfde aandacht die je aan iets belangrijkers zou geven.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "05-19": {"dateKey": "05-19", "day": 19, "month": 5, "sourceTitle": "LEARN, PRACTICE, TRAIN", "thinker": "Epictetus", "thoughtNl": "Oefen een goed inzicht zo geregeld dat je het ook kunt toepassen wanneer je onder druk komt te staan.", "explanationNl": "Een uitleg begrijpen is volgens de auteurs meestal het eerste stadium van leren. Vechtsporters en andere atleten oefenen eenvoudige bewegingen zo lang dat ze er ook op een spannend moment op kunnen vertrouwen. Morele principes vragen iets vergelijkbaars. Een inzicht dat je zelden toepast, is moeilijk terug te vinden zodra je moe bent of de druk oploopt. De auteurs zien Marcus Aurelius als voorbeeld. Hij schreef zijn overdenkingen voor zichzelf en bleef zijn oordeel en gedrag oefenen, ook toen hij al veel ervaring had.", "reflectionNl": "Welk goed inzicht schiet je pas te binnen als een moeilijk moment voorbij is?", "exerciseNl": "Oefen bij een kleine ergernis alvast de reactie die je in een moeilijker situatie nodig hebt.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "05-20": {"dateKey": "05-20", "day": 20, "month": 5, "sourceTitle": "QUALITY OVER QUANTITY", "thinker": "Seneca", "thoughtNl": "Geef een goed boek tijd om je denken te veranderen voordat je alweer naar het volgende grijpt.", "explanationNl": "De auteurs wijzen erop dat zelfs iemand die uitzonderlijk veel leest nooit in de buurt komt van alles wat beschikbaar is. Zodra het aantal uitgelezen boeken de maatstaf wordt, blijft er weinig reden over om bij een moeilijk of waardevol idee stil te staan. Zij stellen voor om een kleiner aantal goede boeken grondiger te lezen. Zo kan een tekst langer doorwerken in wat je begrijpt en hoe je leeft. Die opbrengst laat zich slecht aflezen aan een volle boekenkast.", "reflectionNl": "Welk boek zou meer voor je kunnen betekenen als je één passage opnieuw las?", "exerciseNl": "Lees vandaag een paar bladzijden opnieuw en vat één bruikbaar inzicht in je eigen woorden samen.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "05-21": {"dateKey": "05-21", "day": 21, "month": 5, "sourceTitle": "WHAT KIND OF BOXER ARE YOU?", "thinker": "Epictetus", "thoughtNl": "Zie tegenslag als het moment waarop je oefening van pas komt, zoals een bokser rekening houdt met klappen.", "explanationNl": "Boksen en worstelen waren voor de stoïcijnen vertrouwde beelden om over tegenslag te spreken. De auteurs halen ook Seneca aan, die ongeteste voorspoed kwetsbaar vindt en ziet hoe herhaalde moeilijkheden iemand leren stand te houden. Wie een bokswedstrijd aangaat, weet dat geraakt worden bij de sport hoort. Zo bezien geeft een tegenvaller je een aanleiding om te gebruiken wat je hebt geoefend. De vraag is hoe je verdergaat wanneer het moment komt waarvoor je je hebt voorbereid.", "reflectionNl": "Bij welke tegenslag van deze week komt een vaardigheid van jou van pas?", "exerciseNl": "Noem bij de eerstvolgende tegenvaller hardop of in gedachten wat je nu kunt oefenen.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "05-22": {"dateKey": "05-22", "day": 22, "month": 5, "sourceTitle": "TODAY IS THE DAY", "thinker": "Marcus Aurelius en Seneca", "thoughtNl": "Begin vandaag met een goede keuze die je steeds naar morgen doorschuift, ook als het moment onhandig voelt.", "explanationNl": "De auteurs merken op hoe vaak we al weten wat verstandig of juist is en toch wachten met handelen. Het echte werk zit in het besluit op het moment zelf, bijvoorbeeld wanneer je je aangevallen voelt of ergens aandacht voor moet vrijmaken. Met een voorbeeld van schrijver Steven Pressfield laten ze zien hoe overtuigend uitstel kan klinken. Je belooft jezelf dat het doel er nog steeds toe doet, terwijl je het begin steeds naar morgen schuift. Vandaag kun je dat patroon onderbreken.", "reflectionNl": "Welke goede keuze verplaats je al een paar dagen met hetzelfde excuus naar morgen?", "exerciseNl": "Zet vandaag twee minuten de eerste stap bij iets waarvan je steeds zegt dat je het morgen doet.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "05-23": {"dateKey": "05-23", "day": 23, "month": 5, "sourceTitle": "SHOW ME HOW TO LIVE", "thinker": "Seneca", "thoughtNl": "Een vol leven krijgt zijn waarde door hoe je je tijd gebruikt, tot en met de gewone taak van nu.", "explanationNl": "De auteurs vragen je zelf te onderzoeken wat een vol leven betekent, ongeacht hoeveel jaren je krijgt. Ze denken daarbij aan mensen die vroeg stierven en van wie het leven toch rijk aan betekenis was. Hun voorbeeld verschuift de aandacht van de kalender naar het gebruik van je tijd. Volgens de auteurs oefen je dat in wat nu voor je ligt. Door je bewust aan de taak van dit moment te wijden, geef je ook een klein deel van je leven zijn volle gewicht.", "reflectionNl": "Waar wil je vandaag echt bij aanwezig zijn, ook als het maar een gewoon kwartier is?", "exerciseNl": "Laat afleiding bij één alledaagse taak liggen tot je die met aandacht hebt afgemaakt.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "05-24": {"dateKey": "05-24", "day": 24, "month": 5, "sourceTitle": "MAKING YOUR OWN GOOD FORTUNE", "thinker": "Marcus Aurelius", "thoughtNl": "Bereid je goed voor en handel zorgvuldig, zodat je een kans kunt benutten zodra die zich voordoet.", "explanationNl": "De auteurs bespreken geluk als iets waarop je door voorbereiding enige invloed kunt uitoefenen. Goede beslissingen en degelijk werk veranderen de kans dat je iets aan een gelegenheid hebt, al geven ze geen garantie dat die zich aandient. Ze wijzen op een lang bestaande traditie van spreekwoorden waarin ijver en geluk samengaan. Voor vandaag betekent dat vooral dat je je kunt richten op de juiste handeling op het juiste moment. Daardoor wordt het toeval minder bepalend voor wat je uit een kans haalt.", "reflectionNl": "Op welke mogelijke gelegenheid kun je je nu al voorbereiden zonder te weten of die komt?", "exerciseNl": "Werk tien minuten aan een vaardigheid die je nodig hebt als een gewenste kans zich voordoet.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "05-25": {"dateKey": "05-25", "day": 25, "month": 5, "sourceTitle": "WHERE TO FIND JOY", "thinker": "Marcus Aurelius", "thoughtNl": "Zoek vreugde in bezigheden die iets menselijks in je aanspreken, zoals helpen, zorgvuldig oordelen en aandachtig kijken.", "explanationNl": "De auteurs vergelijken ons met een hond die onrustig of ongelukkig wordt wanneer hij weinig gelegenheid krijgt om te bewegen en te doen waarvoor hij aanleg heeft. Een comfortabel leven neemt die behoefte niet weg. Zij zien bij mensen eveneens vreugde ontstaan uit bezigheden die bij hun aard passen. De terughoudendheid van de stoïcijnen tegenover luxe en sommige emoties betekent in die lezing dat ze de aandacht richten op die diepere voldoening. Marcus noemt onder meer vriendelijkheid en het beoordelen van indrukken.", "reflectionNl": "Welke bezigheid geeft je een tevreden gevoel omdat je er iets van jezelf in kunt gebruiken?", "exerciseNl": "Help vandaag tien minuten met iets concreets dat bij je vaardigheden past.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "05-26": {"dateKey": "05-26", "day": 26, "month": 5, "sourceTitle": "STOP CARING WHAT PEOPLE THINK", "thinker": "Marcus Aurelius", "thoughtNl": "Vraag eerst wat je zelf van je keuze vindt en welk effect die heeft, voordat je bevestiging bij anderen zoekt.", "explanationNl": "Een losse opmerking kan volgens de auteurs plotseling veranderen wat je van je kleding, prestaties of eigen leven vindt. Vergelijking maakt dat effect nog sterker, vooral wanneer je pas tevreden durft te zijn nadat een ander je bevestigt. Het probleem is dat de mening van anderen buiten je invloed ligt. Je kunt wel nagaan wat je zelf denkt, welk gevolg je keuze heeft en of ze juist is. Dat geeft je iets om op te steunen wanneer reacties alle kanten opgaan.", "reflectionNl": "Welke keuze voelde goed totdat iemand anders er iets van zei?", "exerciseNl": "Schrijf je eigen oordeel en één reden op voordat je iemand om feedback vraagt.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "05-27": {"dateKey": "05-27", "day": 27, "month": 5, "sourceTitle": "SWEAT THE SMALL STUFF", "thinker": "Zeno", "thoughtNl": "Kleine goede keuzes krijgen gewicht door herhaling en bepalen samen meer dan ze op zichzelf lijken te doen.", "explanationNl": "Volgens de auteurs maakt de onzekerheid over de herkomst van deze uitspraak haar praktische inzicht nauwelijks minder scherp. Diogenes Laërtius noemt Zeno, met de mogelijkheid dat Socrates de uitspraak eerder deed. De tekst richt zich vervolgens op de optelsom van kleine keuzes. Een taak zorgvuldig afronden, opstaan op de afgesproken tijd en een verleidelijke kortere route laten liggen lijken afzonderlijk weinig voor te stellen. Samen kunnen ze merkbaar veranderen hoe je leeft en wat je van jezelf kunt verwachten.", "reflectionNl": "Bij welke dagelijkse keuze heeft de gemakkelijkste optie op termijn de grootste kosten?", "exerciseNl": "Kies vandaag één keer bewust de zorgvuldige aanpak op een moment waarop je meestal de kortste weg neemt.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "05-28": {"dateKey": "05-28", "day": 28, "month": 5, "sourceTitle": "THE FIRST TWO THINGS BEFORE ACTING", "thinker": "Marcus Aurelius", "thoughtNl": "Laat de eerste onrust zakken en toets daarna je volgende handeling aan het principe dat je wilt volgen.", "explanationNl": "Marcus Aurelius moest als keizer volgens de auteurs voortdurend beslissingen nemen, in bestuur, oorlog en allerlei verzoeken. Ze halen uit zijn aantekening twee stappen die ook bij gewone keuzes bruikbaar zijn. Begin met kalmeren, omdat ergernis of paniek het oordeel kleurt en de beslissing ingewikkelder kan maken. Haal daarna het doel en de principes terug die je belangrijk vindt. Daarmee kun je mogelijke reacties wegen en kiezen wat je in deze concrete situatie rechtvaardig en passend acht.", "reflectionNl": "Welke terugkerende beslissing wordt moeilijker zodra je geërgerd raakt?", "exerciseNl": "Neem bij één lastige keuze een korte pauze en benoem daarna het principe waarop je wilt beslissen.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "05-29": {"dateKey": "05-29", "day": 29, "month": 5, "sourceTitle": "WORK IS THERAPY", "thinker": "Seneca", "thoughtNl": "Geef je hoofd en lichaam een zinvolle taak wanneer je merkt dat doelloosheid omslaat in onrust.", "explanationNl": "De auteurs herkennen een rusteloos gevoel na een tijd zonder training, nuttige bezigheid of structuur, bijvoorbeeld op een lange vakantie of vlak na pensionering. Volgens hen vragen hoofd en lichaam om gebruik en kan ongebruikte energie zich keren tegen degene die haar heeft. Ze noemen kopen, ruziemaken en drama zoeken als manieren waarop mensen die onrust soms verdringen. Hun antwoord is betekenisvolle inspanning. Het gaat om een bezigheid die werkelijk iets vraagt en je mogelijkheden weer aanspreekt.", "reflectionNl": "Wanneer merk je dat vrije tijd overgaat in doelloze onrust, en welke bezigheid zou dan voldoening geven?", "exerciseNl": "Besteed tien minuten aan een klein onafgemaakt klusje dat je hoofd of handen actief houdt.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "05-30": {"dateKey": "05-30", "day": 30, "month": 5, "sourceTitle": "WORKING HARD OR HARDLY WORKING?", "thinker": "Epictetus", "thoughtNl": "Bekijk waarvoor je je inspant en waar het werk toe leidt voordat je drukte als bewijs van goed werk ziet.", "explanationNl": "De auteurs stellen de vanzelfsprekende waardering voor drukte ter discussie. Iemand kan veel uren maken en voortdurend bezig zijn, terwijl het werk nauwelijks bijdraagt aan iets dat de moeite waard is. Ze vragen je daarom te kijken naar wat je doet, waarom je het doet en waar het voltooien ervan je brengt. Epictetus legt daarbij de nadruk op een doel dat ook je oordeel en handelen vormt. Als je voor je inspanning geen goede reden vindt, kun je haar opnieuw wegen en zo nodig stoppen.", "reflectionNl": "Welke bezigheid kost je veel tijd terwijl haar doel je eigenlijk niet helder is?", "exerciseNl": "Neem één drukke taak onder de loep en schrijf in één zin op waarvoor je haar doet.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "05-31": {"dateKey": "05-31", "day": 31, "month": 5, "sourceTitle": "WE HAVE BUT ONE OBLIGATION", "thinker": "Marcus Aurelius", "thoughtNl": "Onder alle rollen die je vandaag vervult, ligt de opdracht om je als een goed mens te gedragen.", "explanationNl": "De auteurs vatten de fundamentele stoïcijnse plicht eenvoudig op. Een goed mens zijn is het werk dat bij ieder van ons hoort, welke functie of verantwoordelijkheid we verder ook hebben. De eenvoud van die opdracht maakt haar gemakkelijk te begrijpen en legt tegelijk bloot hoe bedreven we zijn in het bedenken van uitvluchten. Met een korte verwijzing naar coach Bill Belichick houden de auteurs het bij een directe aansporing om die taak in de praktijk te vervullen.", "reflectionNl": "In welke situatie gebruik je je rol of drukte het gemakkelijkst als excuus voor gedrag dat je zelf afkeurt?", "exerciseNl": "Kies bij één gewone verplichting vandaag bewust de faire of behulpzame manier om haar te vervullen.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "06-01": {"dateKey": "06-01", "day": 1, "month": 6, "sourceTitle": "ALWAYS HAVE A MENTAL REVERSE CLAUSE", "thinker": "Marcus Aurelius", "thoughtNl": "Houd bij een plan ruimte voor een tweede reactie, zodat een tegenslag je richting kan veranderen zonder je oordeel over te nemen.", "explanationNl": "De auteurs beschrijven een mentale reserve voor het geval je oorspronkelijke plan strandt. Als een vriend je verraadt, kun je bijvoorbeeld onderzoeken wat er gebeurde en of vergeving mogelijk is. Bij verloren werk kan de volgende stap zijn om opnieuw te beginnen en te benutten wat je inmiddels weet. Er verandert dan echt iets aan wat haalbaar is. De ruimte die overblijft, zit in je vermogen om je doel of werkwijze bewust bij te stellen. Obstakels zijn gewoon genoeg om die mogelijkheid vooraf open te houden.", "reflectionNl": "Welk plan van vandaag kan vastlopen en wat zou je dan nog waardevols kunnen doen?", "exerciseNl": "Schrijf bij één plan een korte tweede stap op die ook zinvol is als de eerste wegvalt.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "06-02": {"dateKey": "06-02", "day": 2, "month": 6, "sourceTitle": "PLATO’S VIEW", "thinker": "Marcus Aurelius", "thoughtNl": "Bekijk je zorgen van grote hoogte om te zien welke nog even zwaar wegen en welke hun proporties terugkrijgen.", "explanationNl": "De auteurs koppelen het vogelperspectief van Plato aan twee beelden. Bij de dichter Lucianus ziet een vliegende verteller hoe klein rijkdom, landgoederen en strijd van bovenaf lijken. Astronaut Edgar Mitchell kon de aarde werkelijk van grote afstand zien en beschreef hoe klein internationale ruzies daar leken. Hij voelde tegelijk meer betrokkenheid bij de toestand van de wereld. Afstand nemen kan dus tegelijk de omvang van een eigen twist relativeren en zichtbaar maken aan welk groter probleem je iets wilt doen.", "reflectionNl": "Welke zorg ziet er anders uit als je haar naast de bezigheden van een hele stad legt?", "exerciseNl": "Neem één minuut om een actuele ergernis eerst van boven je straat en daarna van boven de aarde te bekijken.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "06-03": {"dateKey": "06-03", "day": 3, "month": 6, "sourceTitle": "IT IS WELL TO BE FLEXIBLE", "thinker": "Seneca", "thoughtNl": "Als de eerste manier om iets bij te dragen wegvalt, zoek dan welke verantwoordelijkheid je nog wél kunt opnemen.", "explanationNl": "De auteurs vertellen hoe iemand bij Abraham Lincoln achtereenvolgens om steeds bescheidener gunsten vroeg toen de vorige verzoeken werden afgewezen. In zijn verhaal eindigde dat met een vraag om een oude broek. De stoïcijnse les zit in de bereidheid om van aanpak te veranderen en te blijven kijken wat mogelijk is. Ook als een officiële functie of een publieke rol onbereikbaar blijkt, kun je nog iets voor anderen betekenen. Soms bestaat de bijdrage eenvoudig uit de manier waarop je een vriend of medemens bent.", "reflectionNl": "Waarvoor heb je minder invloed dan je zou willen, en welke bescheiden bijdrage ligt nog binnen bereik?", "exerciseNl": "Bedenk voor één geblokkeerd plan een kleinere vorm waarin je vandaag iets kunt bijdragen.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "06-04": {"dateKey": "06-04", "day": 4, "month": 6, "sourceTitle": "THIS IS WHAT WE’RE HERE FOR", "thinker": "Seneca", "thoughtNl": "Houd bij tegenslag in gedachten dat je voortkomt uit mensen die zich al generaties door moeilijke omstandigheden heen sloegen.", "explanationNl": "De auteurs erkennen dat het leven zwaar en onrechtvaardig kan zijn. Hun antwoord is om op zo'n moment aan de lange lijn van voorouders te denken die allerlei tegenslagen hebben doorstaan. Zonder hun uithoudingsvermogen zou jij er niet zijn. De auteurs zien daarin een erfenis waarop je je kunt beroepen als je het moeilijk krijgt. De gedachte geeft tegenslag een plaats in een groter verhaal van mensen die onder lastige omstandigheden telkens verder moesten.", "reflectionNl": "Aan welk voorbeeld van volhouden uit je familie of omgeving denk je als het vandaag lastig wordt?", "exerciseNl": "Haal één concreet voorbeeld van doorzetten voor de geest en benoem welke houding je daarvan kunt lenen.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "06-05": {"dateKey": "06-05", "day": 5, "month": 6, "sourceTitle": "BLOW YOUR OWN NOSE", "thinker": "Epictetus", "thoughtNl": "Erken wat je is overkomen en gebruik je beschikbare energie voor een concrete stap in je eigen herstel.", "explanationNl": "De auteurs laten ruimte voor de mogelijkheid dat je werkelijk onrecht is aangedaan. Ze vragen vervolgens wat het je op dit moment oplevert om je aandacht vooral op de schuldvraag te richten. Een rapport of sympathiek verhaal kan iets bevestigen, terwijl praktische zaken nog steeds om actie vragen. Zelfmedelijden kan juist de energie kosten die je voor die actie nodig hebt. Met een aansporing van Marcus Aurelius leggen de auteurs de nadruk op meewerken aan je eigen uitweg zolang je daar invloed op hebt.", "reflectionNl": "Welke praktische stap ligt nog in je bereik bij iets waarover je vooral aan het malen bent?", "exerciseNl": "Besteed vijf minuten aan één handeling die je situatie daadwerkelijk iets verder helpt.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "06-06": {"dateKey": "06-06", "day": 6, "month": 6, "sourceTitle": "WHEN TO STICK AND WHEN TO QUIT", "thinker": "Seneca", "thoughtNl": "Verander van koers als de belemmering duidelijk is en je een beter pad ziet dat je kunt volgen.", "explanationNl": "De auteurs gebruiken Seth Godins vergelijking met drie soorten mensen in een supermarktrij. De eerste blijft uit gewoonte staan, de tweede wisselt telkens bij de kleinste kans op tijdwinst, en de derde verplaatst zich wanneer de vertraging duidelijk is en er een geloofwaardig alternatief bestaat. In die laatste houding herkennen zij Seneca. Veranderen kan moed vragen, ook als het oorspronkelijke plan al loopt. Je hebt tegelijk aandacht en discipline nodig om te zien wanneer een nieuwe optie vooral aantrekkelijk lijkt omdat ze nieuw is.", "reflectionNl": "Aan welke concrete aanwijzing zou je merken dat doorgaan met je huidige aanpak weinig meer oplevert?", "exerciseNl": "Noteer bij één twijfelgeval welk signaal een overstap rechtvaardigt.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "06-07": {"dateKey": "06-07", "day": 7, "month": 6, "sourceTitle": "FINDING THE RIGHT MENTORS", "thinker": "Seneca", "thoughtNl": "Je kunt uit boeken en levensverhalen zelf voorbeelden kiezen die je leren wat je graag wilt ontwikkelen.", "explanationNl": "Door dagboeken, boeken en zorgvuldig geschreven biografieën kunnen de ervaringen van mensen uit andere eeuwen je volgens de auteurs nog bereiken. Dat biedt ook mogelijkheden als je thuis weinig goede voorbeelden had of nooit een mentor hebt gevonden. Je kunt zelf op zoek gaan naar mensen op wie je in bepaalde opzichten wilt lijken en leren van hun wijsheid én hun dwaasheden. De auteurs zien het volgen en doorgeven van waardevolle voorbeelden ook als een manier om recht te doen aan wie de moeite nam zijn ervaringen vast te leggen.", "reflectionNl": "Wiens voorbeeld zou je willen volgen voor een kwaliteit die je in je directe omgeving weinig ziet?", "exerciseNl": "Lees een korte passage uit een biografie of dagboek en benoem één handelwijze die je aanspreekt.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "06-08": {"dateKey": "06-08", "day": 8, "month": 6, "sourceTitle": "BRICK BY BORING BRICK", "thinker": "Marcus Aurelius", "thoughtNl": "Bouw aan je doel door de kleinste uitvoerbare stap goed te doen en daarna de volgende te kiezen.", "explanationNl": "Coach Nick Saban liet spelers volgens de auteurs hun aandacht richten op een training, actie of balbezit tegelijk. Een achterstand en een heel seizoen zijn moeilijk als één geheel te hanteren, terwijl de eerstvolgende actie enkele seconden duurt. Goed uitgevoerde acties kunnen samen een wedstrijd dragen. De auteurs passen dat toe op dagelijkse keuzes. Zoek steeds wat je nu goed kunt doen. Als iets die stap blokkeert, helpt dezelfde aandacht je om vlot een andere haalbare handeling te vinden die bij je richting past.", "reflectionNl": "Wat is de kleinste stap die vandaag iets bijdraagt aan een groot doel dat je bezighoudt?", "exerciseNl": "Doe die stap met volle aandacht en bepaal pas daarna wat de volgende wordt.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "06-09": {"dateKey": "06-09", "day": 9, "month": 6, "sourceTitle": "SOLVE PROBLEMS EARLY", "thinker": "Seneca", "thoughtNl": "Grijp in wanneer een slechte gewoonte of heftige reactie pas begint en je haar nog gemakkelijk kunt bijsturen.", "explanationNl": "De auteurs gebruiken een rivier als beeld voor de groei van een probleem. Dicht bij de bron is het water nog kalm en kun je gemakkelijk oversteken. Wat later een gevaarlijke stroom wordt, kan in het begin nauwelijks opvallen. Ze zien hetzelfde bij gewoonten, emoties en wanorde. Hoe langer zoiets de ruimte krijgt, hoe moeilijker het wordt om te bepalen wanneer het ophoudt. De uitnodiging is om juist in het onopvallende begin een kleine ingreep te doen.", "reflectionNl": "Welk klein signaal vertelt je meestal vroeg genoeg dat een probleem groter gaat worden?", "exerciseNl": "Pak één beginnend probleem vandaag aan met de kleinste stap die het kan afremmen.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "06-10": {"dateKey": "06-10", "day": 10, "month": 6, "sourceTitle": "YOU CAN DO IT", "thinker": "Marcus Aurelius", "thoughtNl": "Zie wat een ander bereikt heeft als aanwijzing dat er iets te leren valt voor je eigen poging.", "explanationNl": "De auteurs beschrijven twee manieren om te kijken naar iemand die iets moeilijks bereikt. In de eerste voelt het succes van de ander als iets dat jou is ontzegd, waardoor je vooral bezig bent met de vraag waarom diegene het wel heeft. In de tweede geeft hetzelfde voorbeeld je een reden om te onderzoeken wat voor jou mogelijk is. De auteurs stellen die houding voor omdat bewondering en nieuwsgierigheid je verder kunnen brengen, terwijl afgunst je gemakkelijk bij de vergelijking laat steken.", "reflectionNl": "Wiens prestatie wekt afgunst bij je en welke concrete vaardigheid kun je ervan afkijken?", "exerciseNl": "Zoek bij die prestatie één stap die jij op je eigen niveau kunt oefenen.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "06-11": {"dateKey": "06-11", "day": 11, "month": 6, "sourceTitle": "JUST DON’T MAKE THINGS WORSE", "thinker": "Marcus Aurelius", "thoughtNl": "Laat een tegenvaller even bezinken, zodat boosheid of haast geen extra probleem aan de situatie toevoegt.", "explanationNl": "De auteurs vergelijken een tegenvaller met een kuil waar je per ongeluk in bent beland. Een eerste neiging kan zijn om door te graven, bijvoorbeeld door boos te worden of meteen wild om je heen te handelen. De reactie kan dan meer schade doen dan de oorspronkelijke gebeurtenis. De eenvoudigste opdracht is eerst te stoppen met toevoegen. Laat de situatie even zoals zij is, zodat je vervolgens een uitweg kunt bedenken met meer overzicht.", "reflectionNl": "Welke impuls zou jouw huidige probleem groter maken als je er meteen aan toegaf?", "exerciseNl": "Neem bij een tegenvaller een korte pauze voordat je antwoordt of iets probeert te herstellen.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "06-12": {"dateKey": "06-12", "day": 12, "month": 6, "sourceTitle": "A TRAINED MIND IS BETTER THAN ANY SCRIPT", "thinker": "Epictetus", "thoughtNl": "Oefen hoe je met onverwachte situaties omgaat, zodat je kunt bijsturen als een vooraf bedacht plan wegvalt.", "explanationNl": "De auteurs wijzen op de verleiding om vooraf voor iedere situatie instructies te willen krijgen. Plannen helpen, maar kunnen door één onverwachte gebeurtenis hun bruikbaarheid verliezen, zoals in de boksvergelijking die ze aan Mike Tyson ontlenen. De stoïcijnse voorbereiding bestaat daarom uit het ontwikkelen van eigenschappen waarop je in nieuwe situaties kunt terugvallen, zoals creativiteit, zelfstandigheid en probleemoplossend vermogen. Inzien hoe je een keuze kunt maken is duurzamer dan alleen horen welke stap je volgens een vast recept moet zetten.", "reflectionNl": "Welke vaardigheid helpt je wanneer een vertrouwde werkwijze ineens niet meer past?", "exerciseNl": "Bedenk voor een bekende taak één andere aanpak die ook zou kunnen werken.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "06-13": {"dateKey": "06-13", "day": 13, "month": 6, "sourceTitle": "LIFE IS A BATTLEFIELD", "thinker": "Epictetus", "thoughtNl": "Gebruik discipline en moed bij de dagelijkse strijd om te handelen als de persoon die je wilt zijn.", "explanationNl": "De auteurs nemen het militaire beeld van Epictetus ruim op. Strijd is voor hen zowel de letterlijke inspanning om te overleven als de dagelijkse moeite om een doel trouw te blijven of een impuls te weerstaan. De eigenschappen die volgens hen helpen zijn onder meer discipline, standvastigheid, helder denken en bereidheid iets voor anderen op te geven. Overmoed, haast en egoïsme maken je juist kwetsbaar. Hun vraag is welke van die eigenschappen je inzet in de gewone verantwoordelijkheden die vandaag op je wachten.", "reflectionNl": "Welke afspraak met jezelf vraagt vandaag om discipline zodra je zin krijgt om ervan af te wijken?", "exerciseNl": "Kies vooraf één eigenschap die je in een lastig moment van vandaag bewust wilt inzetten.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "06-14": {"dateKey": "06-14", "day": 14, "month": 6, "sourceTitle": "TRY THE OTHER HANDLE", "thinker": "Epictetus", "thoughtNl": "Probeer bij een vastgelopen situatie een ander gezichtspunt dat je helpt er concreet iets mee te doen.", "explanationNl": "Journalist William Seabrook beschrijft volgens de auteurs hoe hij tijdens de behandeling van zijn alcoholverslaving vastliep doordat hij de begeleiding als tegenstander benaderde. Epictetus’ beeld van twee handvatten hielp hem een andere houding te proberen. Hij stelde zich open voor wat anderen hem konden leren en begon de mogelijkheid van herstel en nuchterheid te waarderen. De auteurs beloven geen vergelijkbaar resultaat. Ze vragen waarom je zou blijven trekken aan een manier van kijken die je tot nu toe weinig verder heeft gebracht.", "reflectionNl": "Welk gezichtspunt helpt je iets te doen met een situatie die je nu vooral tegenstaat?", "exerciseNl": "Beschrijf één vastgelopen kwestie vanuit een tweede perspectief en kijk welke stap dat opent.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "06-15": {"dateKey": "06-15", "day": 15, "month": 6, "sourceTitle": "LISTENING ACCOMPLISHES MORE THAN SPEAKING", "thinker": "Zeno", "thoughtNl": "Luister naar wat werkelijk mogelijk is en bedenk vooraf hoe je zorgvuldig reageert als een plan anders loopt.", "explanationNl": "Het citaat laat Zeno aansporen tot meer luisteren. De auteurs besteden hun uitleg aan drie gewoonten die volgens hen helpen om minder overvallen te worden. Je houdt verwachtingen haalbaar, denkt zowel het gunstige als het moeilijke scenario door en houdt een alternatief klaar voor als iets misloopt. In dat laatste scenario kun je zelfs een gelegenheid herkennen om goed te handelen. Zo geef je de werkelijkheid meer ruimte dan wanneer je alleen uitgaat van wat je graag zou zien gebeuren.", "reflectionNl": "Welke afloop van een gesprek neem je vanzelfsprekend aan terwijl je de ander nog moet horen?", "exerciseNl": "Bedenk voor één afspraak twee geloofwaardige uitkomsten en kies wat je bij elk ervan kunt doen.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "06-16": {"dateKey": "06-16", "day": 16, "month": 6, "sourceTitle": "NO SHAME IN NEEDING HELP", "thinker": "Marcus Aurelius", "thoughtNl": "Vraag hulp bij wat je alleen niet kunt dragen, zodat je kunt doen wat je te doen staat.", "explanationNl": "De auteurs herinneren eraan dat niemand het leven begint met alle middelen om ieder probleem zelf op te lossen. Als pasgeborene was je afhankelijk van anderen, en hulp ontvangen was ook een manier waarop je zorg leerde kennen. Die behoefte kan later weer opkomen. Marcus vergelijkt het met een gewonde soldaat die een ander nodig heeft om zijn taak te kunnen uitvoeren. De auteurs nodigen je uit om de benodigde hulp gewoon te vragen wanneer je die nodig hebt.", "reflectionNl": "Waar zou één concrete vraag om hulp je vandaag verder brengen dan blijven proberen het alleen te doen?", "exerciseNl": "Vraag iemand om één afgebakende vorm van hulp die je nu kunt gebruiken.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "06-17": {"dateKey": "06-17", "day": 17, "month": 6, "sourceTitle": "OFFENSE OR DEFENSE?", "thinker": "Seneca", "thoughtNl": "Je wordt minder afhankelijk van het lot wanneer je greep krijgt op de verlangens en angsten die eraan vastzitten.", "explanationNl": "De auteurs leggen Machiavelli’s drang om het lot te bedwingen naast Seneca’s idee dat je juist kwetsbaar wordt als je er alles van laat afhangen. Filosofie biedt volgens Seneca bescherming door hebzucht en angst hanteerbaar te maken. De auteurs vergelijken de eerste houding met uitputtend aanvallen en de tweede met een verdediging die tegen een stoot kan en zich kan aanpassen. Ze vragen welk soort leven voortkomt uit de voortdurende inspanning om de omstandigheden naar je hand te zetten.", "reflectionNl": "Bij welke uitkomst maakt de behoefte aan controle je vandaag onrustiger dan de situatie zelf?", "exerciseNl": "Benoem één angst of verlangen onder die controledrang en kies één reactie waarop je wél invloed hebt.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "06-18": {"dateKey": "06-18", "day": 18, "month": 6, "sourceTitle": "PREPARED AND ACTIVE", "thinker": "Seneca", "thoughtNl": "Houd rekening met tegenvallers en wees klaar om je reactie te veranderen zodra de werkelijkheid iets anders vraagt.", "explanationNl": "De auteurs verbinden aanvaarding met actief blijven. Ze stellen voor om rekening te houden met moeilijkheden en met mensen die zich anders gedragen dan je hoopte. Als iets eenmaal is gebeurd, kost het veel energie om te verlangen dat de tijd wordt teruggedraaid of dat de wereld aan je voorkeur voldoet. De werkbare ruimte zit in hoe je jezelf aanpast en wat je met de gegeven omstandigheden doet. Voorbereiding helpt je die ruimte sneller te vinden wanneer het erop aankomt.", "reflectionNl": "Welke lastige situatie van vandaag kun je beter opvangen als je er nu al rekening mee houdt?", "exerciseNl": "Kies vooraf één werkbare reactie op een realistische tegenvaller van vandaag.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "06-19": {"dateKey": "06-19", "day": 19, "month": 6, "sourceTitle": "STAY FOCUSED ON THE PRESENT", "thinker": "Marcus Aurelius", "thoughtNl": "Verklein je blik tot wat zich nu voor je afspeelt wanneer alle mogelijke problemen tegelijk op je drukken.", "explanationNl": "De auteurs vragen hoe je in het verleden door iets moeilijks bent gekomen. Mogelijk ging je aandacht toen op in de details, waardoor je minder bezig was met de omvang van het hele probleem. Soms is overzicht zinvol, erkennen ze, maar het kan ook verlammend worden om alles wat nog komt tegelijk te overzien. Een koorddanser kan zijn blik beter bij de eerstvolgende stap houden. Zo helpt het heden je onderscheiden wat werkelijk nu van je wordt gevraagd.", "reflectionNl": "Welke huidige taak voelt zwaarder doordat je er al alle volgende stappen bij denkt?", "exerciseNl": "Beperk je aandacht de komende vijf minuten tot de eerste stap die nu nodig is.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "06-20": {"dateKey": "06-20", "day": 20, "month": 6, "sourceTitle": "CALM IS CONTAGIOUS", "thinker": "Marcus Aurelius", "thoughtNl": "Jouw kalmte kan anderen helpen rustig te blijven wanneer een groep haar overzicht dreigt te verliezen.", "explanationNl": "De auteurs halen een vuistregel van de Navy SEALs aan waarin kalmte zich binnen een groep kan verspreiden. Dat telt vooral wanneer mensen op iemand letten voor richting en onzeker worden over de volgende stap. Een leidinggevende kan dan met de eigen houding rust laten zien, zonder die bij anderen af te dwingen. Volgens de auteurs geldt dat ook buiten een militaire omgeving. Wie zelf beheerst blijft, kan de groep helpen ademruimte te vinden en voorkomen dat de spanning verder oploopt.", "reflectionNl": "In welke groep of situatie nemen anderen vandaag gemakkelijk jouw spanning of rust over?", "exerciseNl": "Vertraag in een hectisch moment je stem en benoem rustig één concrete volgende stap.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "06-21": {"dateKey": "06-21", "day": 21, "month": 6, "sourceTitle": "TAKE A WALK", "thinker": "Seneca", "thoughtNl": "Een wandeling buiten kan je hoofd ruimte geven wanneer je wilt nadenken, bijkomen of met iemand wilt praten.", "explanationNl": "De auteurs schetsen het lawaai en de drukte van het oude Rome om duidelijk te maken waarom denkers geregeld naar buiten gingen voor lucht en een helder hoofd. Zij zien wandelen ook als tijd waarin gedachten zich verder kunnen ontwikkelen. Hun voorstel is om een wandeling in te zetten bij allerlei gewone gelegenheden, van een lastig besluit tot een telefoongesprek of een afspraak met een vriend. Beweging en frisse lucht geven zo een andere omgeving aan het werk dat je hoofd al doet.", "reflectionNl": "Welke gedachte wil je eens meenemen naar buiten in plaats van er op dezelfde plek over te blijven piekeren?", "exerciseNl": "Maak vandaag een korte wandeling en laat onderweg één vraag rustig meekomen.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "06-22": {"dateKey": "06-22", "day": 22, "month": 6, "sourceTitle": "THE DEFINITION OF INSANITY", "thinker": "Epictetus", "thoughtNl": "Verander iets concreets aan je aanpak wanneer een terugkerend voornemen telkens op hetzelfde moment stukloopt.", "explanationNl": "De auteurs beschrijven hoe gemakkelijk je jezelf dezelfde verbetering belooft terwijl je alle omstandigheden en handelingen precies zo laat als voorheen. Daardoor hangt een andere afloop af van hoop. Leren van een mislukking vraagt volgens hen een besluit om iets te wijzigen, daarna te kijken wat er gebeurt en zo nodig verder bij te sturen. Het oude patroon herhalen kost meestal minder denkwerk. Juist daarom is het waardevol om vooraf te bepalen wat je deze keer daadwerkelijk anders gaat doen.", "reflectionNl": "Welk voornemen herhaal je steeds zonder iets aan het moment, je omgeving of je reactie te veranderen?", "exerciseNl": "Verander vandaag bij één terugkerend probleem één onderdeel van je aanpak en let op het effect.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "06-23": {"dateKey": "06-23", "day": 23, "month": 6, "sourceTitle": "THE LONG WAY AROUND", "thinker": "Marcus Aurelius", "thoughtNl": "Onderzoek welk gevoel of welke vrijheid je van een verre mijlpaal verwacht en wat daarvan nu al bereikbaar is.", "explanationNl": "De auteurs vragen door bij ambities als een indrukwekkende functie, rijkdom of bekendheid. Vaak hopen mensen daarmee uiteindelijk vrijheid, geluk of respect te bereiken. De lange route krijgt dan alle aandacht, terwijl een deel van wat je zoekt volgens hen al besloten ligt in de keuzes die vandaag mogelijk zijn. Ze vergelijken het met overal naar een zonnebril zoeken die al op je hoofd staat. Kijk dus welke ervaring je van de mijlpaal verwacht en of je haar met een huidige keuze kunt benaderen.", "reflectionNl": "Welk deel van de vrijheid die je later hoopt te krijgen, kun je vandaag al uitoefenen?", "exerciseNl": "Schrijf bij één verre ambitie op wat ze je moet geven en kies één kleine handeling die daar nu bij past.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "06-24": {"dateKey": "06-24", "day": 24, "month": 6, "sourceTitle": "THE TRULY EDUCATED AREN’T QUARRELSOME", "thinker": "Epictetus", "thoughtNl": "Probeer bij onenigheid eerst te begrijpen wat iemand bedoelt en laat de behoefte om het gesprek te winnen zakken.", "explanationNl": "De auteurs gebruiken Socrates als voorbeeld van iemand die ook bij scherpe meningsverschillen zijn kalmte hield. Zijn vragen maakten gesprekspartners soms boos, maar zijn aandacht bleef bij wat de ander te zeggen had. In die houding herkennen de auteurs de praktische betekenis van vorming. Als een meningsverschil zich aandient, kun je onderzoeken of strijd iets oplost en welk deel van de situatie bij jou ligt. De drang om in elk klein geschil te winnen kost ruimte voor een gesprek dat daadwerkelijk iets oplevert.", "reflectionNl": "Bij welk meningsverschil wil je vooral gelijk krijgen terwijl je de ander nog niet goed begrijpt?", "exerciseNl": "Stel in een gesprek met verschil van mening eerst één oprechte vraag en wacht het hele antwoord af.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "06-25": {"dateKey": "06-25", "day": 25, "month": 6, "sourceTitle": "THE WISE DON’T HAVE “PROBLEMS”", "thinker": "Seneca", "thoughtNl": "Laat een ander uitpraten voordat je met advies of een verdediging de ruimte vult die voor luisteren nodig is.", "explanationNl": "De auteurs halen Hesiodus en Robert Greene aan over de waarde van weinig spreken. Hun voorbeelden gaan over de gevolgen van te vroeg praten. Iemand die zijn hart lucht kan vooral gehoord willen worden, terwijl jij misschien al met oplossingen komt. Ook bij feedback kun je jezelf in de problemen praten als je meteen probeert je eruit te redden. Eerst luisteren geeft je een kans om te horen wat er werkelijk wordt gevraagd en welke informatie je tot nu toe miste.", "reflectionNl": "Wanneer vul je een stilte met advies terwijl de ander waarschijnlijk vooral wil vertellen wat er speelt?", "exerciseNl": "Laat bij het volgende gesprek een korte stilte vallen en vat samen wat je hoorde voor je iets toevoegt.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "06-26": {"dateKey": "06-26", "day": 26, "month": 6, "sourceTitle": "TRY THE OPPOSITE", "thinker": "Epictetus", "thoughtNl": "Doorbreek een vastgelopen gewoonte door bij één veilige gelegenheid het omgekeerde van je gebruikelijke reactie te proberen.", "explanationNl": "De auteurs illustreren het omkeren van een patroon met Viktor Frankls paradoxale aanpak en een komisch voorbeeld uit Seinfeld. Bij Frankl kon een andere opdracht de hardnekkige aandacht voor een probleem verleggen. In de serie verandert George zijn reactie telkens omdat zijn gebruikelijke gedrag hem steeds op hetzelfde punt brengt. De auteurs gebruiken beide voorbeelden om te laten zien hoe een ingesleten reactie haar eigen probleem kan blijven voeden. Zij stellen een gericht experiment voor bij iets wat al langer vastloopt.", "reflectionNl": "Welke automatische reactie houdt een klein probleem van jou in stand, en wat zou haar bruikbare omkering zijn?", "exerciseNl": "Probeer bij één onschuldige routine bewust de tegengestelde reactie en let op wat er verandert.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "06-27": {"dateKey": "06-27", "day": 27, "month": 6, "sourceTitle": "ADVERSITY REVEALS", "thinker": "Seneca", "thoughtNl": "Een kleine tegenvaller laat zien hoe je anderen behandelt wanneer iets eenvoudigs niet volgens verwachting gaat.", "explanationNl": "De auteurs vertellen over Walt Bettinger, die sollicitanten mee uit ontbijten nam en de restaurantmanager vroeg hun bestelling met opzet verkeerd te serveren. Hij wilde zien hoe zij op het ongemak reageerden. Iemand kan boos of grof worden, het hele gesprek laten kleuren door de fout, of vriendelijk blijven bij het oplossen ervan. Voor de auteurs is het vooral opmerkelijk hoeveel zo'n alledaags voorval over je houding zichtbaar maakt. Juist kleine tegenslag geeft gelegenheid om je reactie te onderzoeken.", "reflectionNl": "Wat zou iemand van je leren door te zien hoe je op een kleine vergissing van diegene reageert?", "exerciseNl": "Reageer bij een kleine vergissing vandaag rustig en benoem zo nodig gewoon wat je nodig hebt.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "06-28": {"dateKey": "06-28", "day": 28, "month": 6, "sourceTitle": "NO SELF-FLAGELLATION NEEDED", "thinker": "Seneca", "thoughtNl": "Bekijk je fouten eerlijk, vraag iets haalbaars van jezelf en gebruik kritiek om een volgende poging te verbeteren.", "explanationNl": "De auteurs wijzen erop dat Marcus Aurelius en andere stoïcijnen zichzelf geregeld kritisch bekeken. De bedoeling van die kritiek was volgens hen opbouwend. Een fout kan je laten zien wat je kunt verbeteren, terwijl jezelf vernederen, straffen of onnodig dingen ontzeggen dat werk niet doet. Zij stellen voor een hogere maar haalbare maatstaf aan te houden en jezelf te vergeven wanneer je er een keer onder blijft. Zo kan de aandacht terug naar de gedragsverandering die je eigenlijk zocht.", "reflectionNl": "Welke fout kun je feitelijk beschrijven zonder er meteen een hard oordeel over jezelf aan te hangen?", "exerciseNl": "Schrijf één fout op, kies een haalbare aanpassing en lees je notitie alsof die van een vriend komt.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "06-29": {"dateKey": "06-29", "day": 29, "month": 6, "sourceTitle": "NO EXCUSES", "thinker": "Marcus Aurelius", "thoughtNl": "Een lastige eigenschap kan veranderen als je haar serieus neemt en telkens één concreet stukje van je reactie oefent.", "explanationNl": "De auteurs noemen verklaringen als opvoeding, aanleg en het gedrag van anderen omdat die gemakkelijk gebruikt worden om alles bij het oude te laten. Zij wijzen op mensen die hebben geleerd hun boosheid of arrogantie te beteugelen en zorgzamer te handelen. Zulke mensen zijn volgens hen niet zonder ego of verleiding begonnen. Ze hebben verbetering belangrijk gemaakt en zijn er stap voor stap aan gaan werken. De aandacht ligt daarmee op het deel van je gedrag waarin je nog kunt oefenen.", "reflectionNl": "Voor welke reactie heb je een vertrouwde verklaring die je zelden laat volgen door een poging tot verandering?", "exerciseNl": "Kies één klein onderdeel van die reactie dat je vandaag bewust kunt wijzigen.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "06-30": {"dateKey": "06-30", "day": 30, "month": 6, "sourceTitle": "THE OBSTACLE IS THE WAY", "thinker": "Marcus Aurelius", "thoughtNl": "Als een obstakel je geplande handeling verhindert, kijk dan welke deugd je juist door die situatie kunt oefenen.", "explanationNl": "De auteurs leggen uit hoe je een geblokkeerd plan kunt ombuigen naar een andere gelegenheid om goed te handelen. Te laat komen door oponthoud geeft bijvoorbeeld ruimte om geduld te oefenen, een fout van iemand anders kan aanleiding zijn om iets uit te leggen en verloren werk biedt een nieuw begin. Het oorspronkelijke probleem heeft echte gevolgen. Tegelijk kan je houding zich aanpassen aan wat er gebeurd is. De auteurs nodigen je uit om te kijken welke kwaliteit je binnen de onverwachte situatie kunt gebruiken.", "reflectionNl": "Welke eigenschap zou je kunnen oefenen als je planning vandaag onverwacht in de war raakt?", "exerciseNl": "Koppel één onvoorziene hinder aan een deugd en oefen die in je eerstvolgende reactie.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "07-01": {"dateKey": "07-01", "day": 1, "month": 7, "sourceTitle": "DO YOUR JOB", "thinker": "Marcus Aurelius", "thoughtNl": "Wat anderen vandaag ook doen, jij kunt trouw blijven aan je eigen taak om goed en verstandig te handelen.", "explanationNl": "Voor de stoïcijnen maakte alles deel uit van een samenhangend geheel. Mensen, dieren en dingen hadden daarin hun eigen plaats. Zelfs slecht handelen was volgens die kijk iets waarmee je in het leven te maken kreeg. De schrijvers halen daar een opdracht voor de lezer uit. Wat er om je heen gebeurt, bepaalt welke omstandigheden je aantreft. Jouw aandeel blijft zorgen dat je zelf goed en verstandig handelt.", "reflectionNl": "Op welk moment neem ik het gedrag van een ander te makkelijk over?", "exerciseNl": "Kies vóór een lastig gesprek één eigenschap die je daarin wilt laten zien.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "07-02": {"dateKey": "07-02", "day": 2, "month": 7, "sourceTitle": "ON DUTY AND CIRCUMSTANCE", "thinker": "Marcus Aurelius", "thoughtNl": "Vraag bij een lastige keuze eerst wat je te doen staat, ook als dat moeite kost of weinig oplevert.", "explanationNl": "Marcus moest als keizer beslissen over rechtszaken, bestuur, geld en oorlog. De schrijvers gebruiken die volle agenda om te laten zien hoeveel belangen tegelijk aan een beslissing kunnen trekken. Wij vragen ons net zo goed af wat iets oplevert, hoeveel moeite het kost en of anderen het waarderen. Zijn aansporing helpt om die vragen te ordenen. Soms is het duidelijk genoeg welke handeling juist is, ook als juist die keuze het moeilijkst voelt.", "reflectionNl": "Welke taak schuif ik voor me uit omdat het alternatief aantrekkelijker is?", "exerciseNl": "Zet vandaag één eerste stap in een taak waarvan je weet dat die bij jou hoort.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "07-03": {"dateKey": "07-03", "day": 3, "month": 7, "sourceTitle": "TURN HAVE TO INTO GET TO", "thinker": "Epictetus", "thoughtNl": "Een verplichting voelt anders als je kijkt naar welke mogelijkheid diezelfde situatie je vandaag biedt.", "explanationNl": "Een lange takenlijst kan voelen als een verzameling dingen die je worden opgelegd. De schrijvers stellen voor om te kijken welke ervaringen of mogelijkheden erin verscholen zitten. Hun overdreven voorbeelden laten zien hoe ver je daarmee kunt gaan. Verkeer levert een paar minuten rust op, pech biedt aanleiding om te lopen, en een bijna-ongeluk maakt gewone ergernissen betrekkelijk. Achter die grap zit een serieuze houding. Je kunt je aandacht richten op wat je kunt aanvangen met de omstandigheden die zich voordoen.", "reflectionNl": "Welke verplichting van vandaag biedt me iets dat ik over het hoofd zie?", "exerciseNl": "Kies één regel op je takenlijst en schrijf erbij welke mogelijkheid die je geeft.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "07-04": {"dateKey": "07-04", "day": 4, "month": 7, "sourceTitle": "PROTECT THE FLAME", "thinker": "Epictetus", "thoughtNl": "Zorg dat je bereidheid om goed te handelen blijft branden, ook als anderen hun eigen verantwoordelijkheid laten liggen.", "explanationNl": "De schrijvers vergelijken het goede in jezelf met een klein vuur dat verzorging nodig heeft. Je kunt het voeden door in concrete situaties verstandig te gebruiken wat je krijgt en te bewaken wat voor jouw handelen telt. Ieder mens draagt zelf die verantwoordelijkheid. Als anderen hun vuur laten doven, kan dat de wereld donkerder maken. Het deel waarop jij invloed hebt, is dat er vanuit jouw handelen nog steeds wat licht komt.", "reflectionNl": "Wat helpt mij om zorgvuldig te blijven als mensen om me heen afhaken?", "exerciseNl": "Bedenk één klein gebaar waarmee je vandaag een waarde zichtbaar maakt.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "07-05": {"dateKey": "07-05", "day": 5, "month": 7, "sourceTitle": "NO ONE SAID IT’D BE EASY", "thinker": "Seneca", "thoughtNl": "Een moeilijke keuze kan juist van jou vragen om eerlijk te handelen wanneer een makkelijk voordeel binnen handbereik ligt.", "explanationNl": "De schrijvers nemen serieus dat verkeerd handelen aantrekkelijk kan zijn. Een keuze die rijkdom, genot of invloed oplevert, kan je verleiden terwijl je al aanvoelt dat er iets aan schort. Plicht kan aan de andere kant inspanning, ongemak of zelfs gevaar meebrengen. Precies daar krijgt de vraag van Seneca gewicht. Als die afweging bij jou terechtkomt, kun je jezelf testen op je bereidheid om de last te dragen en het snelle voordeel te laten gaan.", "reflectionNl": "Bij welke beslissing maakt een aantrekkelijk voordeel het moeilijk om eerlijk te kiezen?", "exerciseNl": "Schrijf vóór die beslissing in één zin op welke keuze je achteraf kunt verdedigen.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "07-06": {"dateKey": "07-06", "day": 6, "month": 7, "sourceTitle": "RISE AND SHINE", "thinker": "Marcus Aurelius", "thoughtNl": "Ook op een trage ochtend begint je bijdrage met opstaan en een eerste handeling die ergens toe dient.", "explanationNl": "Zelfs de Romeinse keizer moest zich blijkbaar soms moed inspreken om onder de dekens vandaan te komen. De schrijvers herkennen daarin dezelfde weerstand die je van je schooltijd tot je pensioen kunt voelen. Ze wijzen op twee redenen om te beginnen. Je hebt werk of een roeping waaraan je je hebt verbonden, en daarnaast kun je anderen en het grotere geheel dienen. Die bijdrage krijgt pas vorm zodra je opstaat en aan de slag gaat.", "reflectionNl": "Voor wie maakt het vandaag verschil dat ik daadwerkelijk begin?", "exerciseNl": "Leg vóór het slapen iets klaar waarmee je morgen direct aan een belangrijke taak kunt beginnen.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "07-07": {"dateKey": "07-07", "day": 7, "month": 7, "sourceTitle": "OUR DUTY TO LEARN", "thinker": "Seneca", "thoughtNl": "Vraag wat een verhaal je leert over leven en keuzes maken wanneer de details je aandacht opeisen.", "explanationNl": "Bij de Odyssee kun je eindeloos praten over Homerus, de mondelinge overlevering en de werking van het houten paard. De schrijvers volgen Seneca in een andere leesvraag. Wat doet Odysseus wanneer hij strandt, wordt afgeleid of te veel op zijn eigen kunnen vertrouwt? Als zulke scènes je iets leren over volhouden, hoogmoed of verleiding, heeft het verhaal je gevormd. Die vorming is voor hen het doel van lezen en studeren, ook buiten school.", "reflectionNl": "Welke keuze uit een verhaal dat ik ken lijkt op een keuze die ik zelf moet maken?", "exerciseNl": "Schrijf bij iets wat je leest één les op die je morgen kunt toepassen.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "07-08": {"dateKey": "07-08", "day": 8, "month": 7, "sourceTitle": "STOP MONKEYING AROUND", "thinker": "Marcus Aurelius", "thoughtNl": "Zelfrespect groeit wanneer je vandaag verantwoordelijkheid neemt voor een beslissing die je al te lang voor je uitschuift.", "explanationNl": "De schrijvers verbinden Marcus’ aansporing met Joan Didions idee dat zelfrespect voortkomt uit verantwoordelijkheid nemen voor je leven. Klagen over gemiste kansen of wachten tot alle vragen zijn beantwoord stelt dat begin uit. Je karakter ontwikkelt zich zodra je serieus kijkt naar je aandeel en ernaar handelt. Didions beschrijving van slapeloze spijt maakt de prijs van uitstel concreet. Onvervulde beloften en verspilde mogelijkheden kunnen lang blijven knagen, juist als ze door eigen nalatigheid ontstonden.", "reflectionNl": "Welke belofte aan mezelf of aan iemand anders kan ik vandaag beginnen na te komen?", "exerciseNl": "Stuur een kort bericht of zet een stap waarmee je één open belofte oppakt.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "07-09": {"dateKey": "07-09", "day": 9, "month": 7, "sourceTitle": "THE PHILOSOPHER KING", "thinker": "Musonius Rufus", "thoughtNl": "Als iemand op jouw oordeel rekent, helpt filosofie je om belangen helder en zorgvuldig tegen elkaar af te wegen.", "explanationNl": "De schrijvers halen generaal Herzl Halevi aan, die filosofie juist praktisch vond bij leidinggeven. Wie onder druk keuzes maakt, heeft gevoel voor prioriteiten, maat en gevolgen nodig. Plato gaf die gedachte vorm in de filosoof-koning, en Marcus Aurelius was een keizer die daadwerkelijk filosofie beoefende. Ook buiten politiek en leger ben je geregeld verantwoordelijk voor een gezin, een team of jezelf. Dan kun je je oordeel en je gevoel voor rechtvaardigheid ontwikkelen voordat er veel van afhangt.", "reflectionNl": "Wie wordt geraakt door een beslissing die ik deze week als leidinggevende of als voorbeeld neem?", "exerciseNl": "Noteer vóór die beslissing één belang dat je gemakkelijk over het hoofd ziet.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "07-10": {"dateKey": "07-10", "day": 10, "month": 7, "sourceTitle": "LOVE THE HUMBLE ART", "thinker": "Marcus Aurelius", "thoughtNl": "Maak tijd voor de eenvoudige oefening van je vak, ook wanneer er weinig publiek of beloning tegenover staat.", "explanationNl": "Zelfs succesvolle komieken stappen soms laat op de avond in een kleine club het podium op. Ze oefenen er hun vak in zijn meest gewone vorm, ondanks het geld en de bekendheid die ze elders al hebben. Voor de schrijvers zit daarin iets vrijs. Deze mensen kiezen voor de oefening omdat ze van hun vak houden, contact zoeken met hun publiek en beter willen worden. Die aandacht voor het ambacht kun je ook in je eigen werk terugbrengen.", "reflectionNl": "Welk onderdeel van mijn vak zou ik oefenen als er niemand keek?", "exerciseNl": "Reserveer tien minuten voor één basisvaardigheid waar je graag beter in wordt.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "07-11": {"dateKey": "07-11", "day": 11, "month": 7, "sourceTitle": "THE START-UP OF YOU", "thinker": "Epictetus", "thoughtNl": "Geef je eigen ontwikkeling minstens zoveel serieuze aandacht als je aan een veelbelovend nieuw project zou besteden.", "explanationNl": "Mensen steken soms jaren, geld en energie in een bedrijf dat als een idee begint. De schrijvers gebruiken dat ondernemerschap als vergelijking voor hoe een mens groeit. Je ontwikkelt je geleidelijk, komt in contact met anderen en bouwt iets op wat eerst alleen een mogelijkheid was. Epictetus voert Socrates aan als iemand die plezier beleeft aan dagelijkse zelfverbetering. Het boek vraagt waarom je dezelfde toewijding die een zakelijke kans krijgt, ook voor jezelf zou kunnen inzetten.", "reflectionNl": "Welke investering in mezelf stel ik uit terwijl ik die voor mijn werk wel zou doen?", "exerciseNl": "Plan deze week één concrete oefening voor een eigenschap die je wilt ontwikkelen.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "07-12": {"dateKey": "07-12", "day": 12, "month": 7, "sourceTitle": "SOME SIMPLE RULES", "thinker": "Marcus Aurelius", "thoughtNl": "Pas één eenvoudige regel meteen toe, bij je eerste taak, je eerste gesprek of de eerstvolgende afleiding.", "explanationNl": "De regels die Marcus zichzelf geeft, zijn kort genoeg om te onthouden. Begin tijdig, spreek helder, houd je aandacht erbij, vind een midden tussen lijdelijkheid en felheid, en geef werk zijn juiste plaats. De schrijvers benadrukken het verschil tussen ze kunnen opnoemen en ze werkelijk toepassen. De eerste taak en het eerste gesprek bieden al oefenruimte. Door er dagelijks op terug te komen, krijgen die simpele regels invloed op hoe je leeft.", "reflectionNl": "Welke van die eenvoudige regels zou vandaag het meeste verschil maken?", "exerciseNl": "Schrijf één regel op een plek waar je die vóór je eerstvolgende taak ziet.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "07-13": {"dateKey": "07-13", "day": 13, "month": 7, "sourceTitle": "A LEADER LEADS", "thinker": "Marcus Aurelius", "thoughtNl": "Leidinggeven betekent dat je iets goeds blijft doen, ook wanneer een ander het overneemt en de dank uitblijft.", "explanationNl": "Wanneer iemand je idee overneemt of je gedrag kopieert, kun je het gevoel krijgen dat je aanspraak op erkenning verliest. De schrijvers zien volwassen leiderschap als bereidheid om daar anders mee om te gaan. Wie een voorbeeld geeft of te hulp schiet, levert al een dienst in het groot of het klein. Bij die rol hoort ook werk waarvoor niemand je bedankt. Zoals Marcus het beschrijft, kan een goede daad vanzelf gevolgd worden door een volgende.", "reflectionNl": "Waar houd ik me in omdat een ander waarschijnlijk met de eer gaat strijken?", "exerciseNl": "Doe één klein nuttig ding voor een ander zonder het later ter sprake te brengen.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "07-14": {"dateKey": "07-14", "day": 14, "month": 7, "sourceTitle": "A LITTLE KNOWLEDGE IS DANGEROUS", "thinker": "Epictetus", "thoughtNl": "Juist als je iets snel oppikt, loont het om de basis rustig te oefenen en vragen te blijven stellen.", "explanationNl": "De schrijvers merken op dat goede leraren soms bijzonder streng zijn voor leerlingen met veel aanleg. Ze willen dat het talent tot zijn recht komt en weten ook wat er mis kan gaan als alles in het begin gemakkelijk lijkt. Snel begrip kan leiden tot overmoed, het overslaan van basislessen en gewoonten die later moeilijk te corrigeren zijn. Epictetus’ waarschuwing vraagt om geduld. Oefen op het niveau dat je beheerst en houd ruimte voor begeleiding.", "reflectionNl": "Welke basisstap sla ik steeds over omdat ik het gevoel heb dat ik die al begrijp?", "exerciseNl": "Herhaal vandaag één beginnersoefening met volle aandacht en let op een detail dat je normaal overslaat.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "07-15": {"dateKey": "07-15", "day": 15, "month": 7, "sourceTitle": "DOING THE RIGHT THING IS ENOUGH", "thinker": "Marcus Aurelius", "thoughtNl": "Een goede daad heeft haar waarde al zodra iemand ermee geholpen is en jij zorgvuldig hebt gehandeld.", "explanationNl": "De schrijvers vragen hoe je reageert wanneer iemand het juiste doet, ook als die persoon daar moeite voor heeft of er zelf iets bij inschiet. Je kunt daarin iets bewonderenswaardigs herkennen, zelfs als niemand de daad beloont. Die maatstaf kun je ook op jezelf toepassen. Marcus telt twee dingen die er al zijn. Jij hebt goed gehandeld en een ander heeft er baat bij. Dank, erkenning of een tegenprestatie voegen daar voor het morele oordeel weinig aan toe.", "reflectionNl": "Bij welke goede daad wacht ik nog op een reactie die ik eigenlijk niet nodig heb?", "exerciseNl": "Kies vandaag iets kleins dat nuttig is, ook als niemand te weten komt wie het deed.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "07-16": {"dateKey": "07-16", "day": 16, "month": 7, "sourceTitle": "PROGRESS OF THE SOUL", "thinker": "Marcus Aurelius", "thoughtNl": "Kijk waarvoor je dagelijkse keuzes in dienst staan en wat dat zegt over de waarden die je noemt.", "explanationNl": "De schrijvers vragen om je waarden naast je werkelijke gedrag te leggen. Waar zet je je voor in, wat doe je dagelijks en waarom? Een doel klinkt overtuigend totdat je bekijkt of je concrete keuzes ermee stroken of voornamelijk je eigen ambitie volgen. Een ongemakkelijk antwoord kan nuttig zijn. Het maakt zichtbaar welk gedrag je kunt bijsturen en helpt uitzoeken welke verantwoordelijkheid je werkelijk wilt dragen. Zo begint de vooruitgang waar Marcus op doelt.", "reflectionNl": "Welke keuze van gisteren paste het minst bij iets wat ik belangrijk zeg te vinden?", "exerciseNl": "Schrijf één waarde en één kleine handeling voor vandaag naast elkaar.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "07-17": {"dateKey": "07-17", "day": 17, "month": 7, "sourceTitle": "DON’T ABANDON OTHERS . . . OR YOURSELF", "thinker": "Marcus Aurelius", "thoughtNl": "Houd vast aan je nieuwe koers en blijf mild tegenover de mensen die nog moeite hebben om mee te gaan.", "explanationNl": "De schrijvers vergelijken persoonlijke vooruitgang met gezonder gaan eten terwijl je omgeving hetzelfde blijft doen. Wat eerst vanzelf ging, zoals samen een restaurant kiezen, kan ineens spanning opleveren. Marcus vraagt aandacht voor twee dingen tegelijk. Blijf redelijk handelen en behoud je welwillendheid tegenover wie het moeilijker maakt. Jij stond misschien kort geleden nog waar zij nu staan. Dat besef kan helpen om standvastig te blijven zonder ruzie te zoeken of relaties achteloos op te geven.", "reflectionNl": "Bij wie kan ik mijn grens duidelijk houden én belangstelling tonen voor diens kant?", "exerciseNl": "Bedenk één voorstel waarin jouw nieuwe gewoonte en de wensen van de ander ruimte krijgen.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "07-18": {"dateKey": "07-18", "day": 18, "month": 7, "sourceTitle": "EACH THE MASTER OF THEIR OWN DOMAIN", "thinker": "Marcus Aurelius", "thoughtNl": "Laat anderen hun eigen keuzes maken zolang ze jouw grenzen respecteren, en geef hun diezelfde ruimte terug.", "explanationNl": "De schrijvers gebruiken de grens tussen iemands bewegingsvrijheid en het lichaam van een ander als beeld voor samenleven. Wie ruimte voor zichzelf wil, heeft ook rekening te houden met de ruimte van anderen. Dat vraagt twee vaardigheden. Je let erop dat je eigen keuzes niemand onnodig hinderen en verdraagt dat anderen binnen hun eigen ruimte anders kiezen dan jij. Zeker bij sterke meningsverschillen kun je aandacht terugbrengen naar de keuzes die werkelijk bij jou horen.", "reflectionNl": "Welke keuze van iemand anders blijf ik beoordelen terwijl ik zelf geen last van die keuze heb?", "exerciseNl": "Schrijf bij een meningsverschil op welke beslissing van jou is en welke van de ander.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "07-19": {"dateKey": "07-19", "day": 19, "month": 7, "sourceTitle": "FORGIVE THEM BECAUSE THEY DON’T KNOW", "thinker": "Marcus Aurelius", "thoughtNl": "Bedenk bij iemands wrede gedrag welke waarheid of welk inzicht diegene mist, zodat je reactie milder kan worden.", "explanationNl": "De schrijvers leggen een verband tussen Plato, Marcus Aurelius en Jezus’ vraag om vergeving tijdens zijn kruisiging. In die scène krijgt de gedachte een zwaar gewicht, juist omdat ze midden in ernstig lijden wordt uitgesproken. Ze merken ook op dat christenen tijdens Marcus’ eigen bewind door Romeinen zijn gedood. Wat die voorbeelden volgens hen met elkaar verbindt, is het besef dat mensen vanuit onwetendheid kunnen handelen. Met dat besef kun je anderen met meer mildheid benaderen.", "reflectionNl": "Bij welke recente belediging zou het helpen om te bedenken wat de ander mogelijk over het hoofd zag?", "exerciseNl": "Schrijf één milde verklaring voor een kleine ergernis op voordat je erop reageert.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "07-20": {"dateKey": "07-20", "day": 20, "month": 7, "sourceTitle": "MADE FOR JUSTICE", "thinker": "Marcus Aurelius", "thoughtNl": "Maak je gevoel voor eerlijkheid sterker met duidelijke afspraken, ook voor de momenten waarop omzeilen gemakkelijk lijkt.", "explanationNl": "De schrijvers herkennen een diep gevoel voor rechtvaardigheid in onze afkeer van voordringen en profiteren, en in regels die kwetsbare mensen beschermen. Over sommige ernstige vormen van onrecht zijn mensen met heel verschillende achtergronden het eens. Tegelijk kunnen diezelfde mensen regels buigen als er weinig kans is dat iemand het merkt. Marcus’ idee dat we voor elkaar zijn gemaakt vraagt daarom om duidelijke grenzen en stevige afspraken. Die helpen ons ook zelf eerlijk te handelen als het iets kost.", "reflectionNl": "Welke regel vind ik terecht totdat ik er zelf voordeel bij heb die te omzeilen?", "exerciseNl": "Kies vooraf hoe je je aan die regel houdt wanneer er geen toezicht is.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "07-21": {"dateKey": "07-21", "day": 21, "month": 7, "sourceTitle": "MADE FOR WORKING TOGETHER", "thinker": "Marcus Aurelius", "thoughtNl": "Als opstaan je moeite kost, denk dan aan de mensen met wie je vandaag iets gezamenlijks mogelijk maakt.", "explanationNl": "Een hond kan gerust de hele dag in bed blijven liggen. Marcus ziet voor mensen een andere opdracht, en de schrijvers leggen de nadruk op samenwerken met elkaar. De samenleving is volgens hen iets wat generaties samen hebben opgebouwd en nog steeds dragen. Dat geeft ook betekenis aan een gewone ochtend waarop je liever blijft liggen. Je kunt denken aan het gezamenlijke werk waarvoor je vandaag nodig bent, en aan de mensen die erop rekenen dat jij verschijnt.", "reflectionNl": "Op welk moment heeft iemand vandaag iets aan mijn aanwezigheid of mijn inzet?", "exerciseNl": "Noem vóór je eerste taak één persoon voor wie jouw bijdrage helpt.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "07-22": {"dateKey": "07-22", "day": 22, "month": 7, "sourceTitle": "NO ONE HAS A GUN TO YOUR HEAD", "thinker": "Seneca", "thoughtNl": "Je kunt vandaag het goede doen omdat je er zelf voor kiest, ook als een makkelijke uitweg openligt.", "explanationNl": "De schrijvers erkennen dat je bij een moeilijke keuze ook egoïstisch of onbeleefd kunt handelen. Soms levert dat zelfs iets op en volgt er geen straf. Ze vragen je om verder te kijken dan die ene uitkomst. Wat voor leven ontstaat er als je vaker die reden volgt? Voor Seneca zit de waarde van een nobele daad in vrijwilligheid. Je kunt je plicht zien als iets waar je voor kiest omdat je het wilt, zelfs als niemand je ertoe dwingt.", "reflectionNl": "Welke goede keuze zou ik maken als ik zeker wist dat niemand mij erop zou aanspreken?", "exerciseNl": "Voer vandaag één taak uit en formuleer vooraf waarom je er zelf voor kiest.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "07-23": {"dateKey": "07-23", "day": 23, "month": 7, "sourceTitle": "RECEIVE HONORS AND SLIGHTS EXACTLY THE SAME WAY", "thinker": "Marcus Aurelius", "thoughtNl": "Neem erkenning en afwijzing allebei rustig aan en laat je inzet afhangen van wat je zaak nodig heeft.", "explanationNl": "Pompeius gaf Cato in de Romeinse burgeroorlog het bevel over de vloot en trok het kort daarna weer in. De schrijvers lezen Cato’s kalme reactie als een voorbeeld van omgaan met zowel eer als gezichtsverlies. Hij bleef de zaak steunen en sprak de soldaten moed in die onder zijn bevel hadden kunnen vallen. De functie kon hem worden gegeven en weer worden afgenomen. Zijn gedrag op dat moment liet zien wat hij zelf van belang vond.", "reflectionNl": "Welk onderdeel van mijn inzet zou hetzelfde moeten blijven als een compliment of promotie uitblijft?", "exerciseNl": "Kies na een compliment of teleurstelling de eerstvolgende taak die de zaak echt verder helpt.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "07-24": {"dateKey": "07-24", "day": 24, "month": 7, "sourceTitle": "SOMEWHERE SOMEONE’S DYING", "thinker": "Epictetus", "thoughtNl": "Vraag bij schrijnend nieuws of je iets kunt bijdragen en richt je aandacht daarna op wat je werkelijk kunt doen.", "explanationNl": "De schrijvers schetsen een gesprek waarin twee mensen zich naar aanleiding van een verre ramp vreselijk voelen, terwijl de getroffenen daar niets mee opschieten. Hun bezwaar betreft vooral nieuws dat alle aandacht opslokt zonder dat er een handeling uit volgt. Betrokkenheid kan wel degelijk betekenis krijgen als je iemand daadwerkelijk kunt helpen. Epictetus’ onderscheid maakt daar ruimte voor. Als je geen zinvolle bijdrage kunt leveren, kun je je aandacht terugbrengen naar verantwoordelijkheden dicht bij huis.", "reflectionNl": "Bij welk nieuws blijf ik hangen terwijl ik nog niet heb onderzocht of ik iets kan doen?", "exerciseNl": "Bedenk bij één nieuwsbericht een haalbare bijdrage. Leg het bericht weg als je die vandaag niet kunt leveren.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "07-25": {"dateKey": "07-25", "day": 25, "month": 7, "sourceTitle": "WHAT’S ON YOUR TOMBSTONE?", "thinker": "Seneca", "thoughtNl": "Vraag wat je werk je kost als je er steeds meer tijd, relaties en aandacht voor andere mensen aan opgeeft.", "explanationNl": "Een bestuurder kan verwaarlozing van zijn gezin verdedigen met zijn ambt. Een schrijver kan het eigen talent aanvoeren om neerbuigend gedrag goed te praten. De schrijvers gebruiken die voorbeelden om te tonen hoe makkelijk toewijding aan werk een rechtvaardiging voor eigenbelang wordt. Hard werken kan iets opleveren waar je trots op bent. Seneca vraagt welke prijs daarvoor wordt betaald. Wie alles voor aanzien en succes inlevert, kan aan het eind vooral een functie overhouden die op een grafsteen past.", "reflectionNl": "Welke opoffering voor mijn werk ben ik als vanzelfsprekend gaan beschouwen?", "exerciseNl": "Maak vandaag bewust tijd voor één persoon of bezigheid waarvoor werk gewoonlijk voorgaat.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "07-26": {"dateKey": "07-26", "day": 26, "month": 7, "sourceTitle": "WHEN GOOD MEN DO NOTHING", "thinker": "Marcus Aurelius", "thoughtNl": "Ook zwijgen of wegkijken kan onrecht ruimte geven, dus zoek uit welke kleine bijdrage jij daadwerkelijk kunt leveren.", "explanationNl": "De schrijvers wijzen op historische voorbeelden van groot onrecht, waaronder slavernij, de Holocaust en segregatie. Naast directe daders vragen ze aandacht voor gewone mensen die om allerlei redenen weigerden in te grijpen. Marcus’ uitspraak brengt ook het nalaten van een handeling binnen het morele oordeel. Je kunt zelf geen kwaad plegen en intussen aan de kant blijven staan terwijl iemand anders wordt geschaad. De schrijvers vragen om, binnen je mogelijkheden, actief iets goeds bij te dragen.", "reflectionNl": "Wanneer hield ik laatst mijn mond terwijl ik iemand op een veilige manier had kunnen steunen?", "exerciseNl": "Kies één haalbare manier om iemand die onrecht ervaart te steunen, bijvoorbeeld door te vragen wat die nodig heeft.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "07-27": {"dateKey": "07-27", "day": 27, "month": 7, "sourceTitle": "WHERE IS ANYTHING BETTER?", "thinker": "Marcus Aurelius", "thoughtNl": "Geld, erkenning en liefde kunnen veel betekenen, terwijl eerlijkheid en moed hun waarde in het handelen zelf hebben.", "explanationNl": "De schrijvers erkennen dat geld, succes en liefde waardevol kunnen zijn. Ze beschrijven ook wat je ontdekt wanneer een langverwacht doel is bereikt. Geld kan nieuwe zorgen brengen, na de ene top verschijnt een volgende en liefde kun je steeds meer blijven verlangen. De verwachting dat zulke dingen alles oplossen houdt daardoor moeilijk stand. Voor Marcus ligt het duurzame goed in rechtvaardigheid, eerlijkheid, zelfbeheersing en moed. De schrijvers zien dat als iets wat al waarde heeft op het moment dat je ernaar handelt.", "reflectionNl": "Welk resultaat verwacht ik zo veel van dat ik vergeet hoe ik het wil bereiken?", "exerciseNl": "Schrijf naast één belangrijk doel de kwaliteit die je onderweg wilt laten zien.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "07-28": {"dateKey": "07-28", "day": 28, "month": 7, "sourceTitle": "CHECK YOUR PRIVILEGE", "thinker": "Musonius Rufus", "thoughtNl": "Als iemand iets minder snel oppakt, bedenk dan welke hulp of voorsprong jij zelf ooit hebt gekregen.", "explanationNl": "De schrijvers nemen een ergernis als vertrekpunt. Iemand doet iets anders dan je verwacht en je concludeert snel dat diegene weinig begrijpt. Musonius wijst op verschillen in aanleg, opvoeding en omstandigheden. Sommige mensen hebben daardoor meer uitleg of zorg nodig om dezelfde stap te zetten. Ook wanneer jij zelf genoeg hebt moeten overwinnen, kun je op een bepaald punt voorsprong hebben gehad. Dat onder ogen zien kan je helpen om geduldiger en bruikbaarder te reageren.", "reflectionNl": "Welke uitleg of ervaring die mij hielp, heeft de ander misschien nooit gehad?", "exerciseNl": "Leg een lastige stap nog eens uit met een concreet voorbeeld en vraag waar die onduidelijk blijft.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "07-29": {"dateKey": "07-29", "day": 29, "month": 7, "sourceTitle": "A CURE FOR THE SELF", "thinker": "Seneca", "thoughtNl": "Gebruik filosofie om een schadelijke gewoonte te onderzoeken en te oefenen met het soort mens dat je wilt worden.", "explanationNl": "Volgens de schrijvers vormen aanleg en opvoeding samen een mengsel van behulpzame en schadelijke eigenschappen. Wanneer de schadelijke trekken gevolgen krijgen, kunnen mensen bijvoorbeeld steun zoeken in therapie of bij een groep. Seneca’s idee van filosofie als zorg voor jezelf plaatsen ze in dezelfde brede vraag hoe je verandert. Filosofische oefening richt zich bij hen ook op wat er kan groeien, zoals zelfvertrouwen en innerlijke stevigheid. Het gaat om hoe je je leven vormgeeft, ook buiten acute problemen om.", "reflectionNl": "Welke terugkerende eigenschap van mezelf wil ik beter leren herkennen voordat die mijn gedrag bepaalt?", "exerciseNl": "Schrijf bij één voorval op wat je deed, wat het effect was en welke reactie je wilt oefenen.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "07-30": {"dateKey": "07-30", "day": 30, "month": 7, "sourceTitle": "STOIC JOY", "thinker": "Seneca", "thoughtNl": "Vreugde kan ook stil zijn, als een gevoel van richting en tevredenheid dat je bij tegenslag blijft dragen.", "explanationNl": "Volgens de schrijvers gebruiken we vreugde vaak voor iets dat meer op opgewektheid lijkt. Seneca bedoelt een diepere tevredenheid, die ook kan samengaan met het onder ogen zien van sterfelijkheid, armoede of pijn. Dat iemand weinig lacht, zegt volgens deze uitleg weinig over zijn vermogen om tevreden te leven. De auteurs herkennen stoïcijnse vreugde in het terugveren na tegenslag en het vermogen om voor anderen een bron van kracht te zijn. Toewijding, goed handelen en een doel geven die vreugde houvast.", "reflectionNl": "Welk deel van mijn leven geeft me een rustige tevredenheid, ook op dagen waarop ik me somber voel?", "exerciseNl": "Noteer vanavond één handeling die voldoening gaf zonder dat er meteen iets te vieren viel.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "07-31": {"dateKey": "07-31", "day": 31, "month": 7, "sourceTitle": "YOUR CAREER IS NOT A LIFE SENTENCE", "thinker": "Seneca", "thoughtNl": "Wees trots op je werk en maak ook ruimte voor de dag waarop iemand anders het van je overneemt.", "explanationNl": "De schrijvers schetsen hoe een ouder wordende ondernemer de regie kan blijven vasthouden tot zijn familie en aandeelhouders bij de rechter belanden. Doordat hij geen opvolging voorbereidde, komen juist zijn kwetsbaarste kanten publiekelijk bloot te liggen. Seneca’s advocaat die zelfs op hoge leeftijd nog om goedkeuring pleit, roept dezelfde vraag op. Wie zijn leven helemaal om een functie bouwt, maakt het moeilijk om waardig los te laten. Werk verdient aandacht, naast andere dingen die je leven betekenis geven.", "reflectionNl": "Welke verantwoordelijkheid zou ik moeilijk kunnen loslaten, en wat zou die overgang makkelijker maken?", "exerciseNl": "Schrijf één taak op die iemand anders met jouw uitleg zou kunnen overnemen.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "08-01": {"dateKey": "08-01", "day": 1, "month": 8, "sourceTitle": "DON’T GO EXPECTING PERFECTION", "thinker": "Marcus Aurelius", "thoughtNl": "Begin met de omstandigheden die je werkelijk aantreft en laat kleine ergernissen de belangrijke taak vandaag niet bepalen.", "explanationNl": "De schrijvers herkennen het verlangen naar ideale omstandigheden voordat je ergens aan begint. Marcus herinnerde zichzelf eraan dat hij geen volmaakte samenleving hoefde af te wachten. Josef Pieper verwoordt de achterliggende gedachte volgens hen treffend. Wie goed wil handelen, moet weten hoe de situatie werkelijk in elkaar zit. Met die kennis kun je iets doen aan wat voor je ligt. Soms volstaat het om een klein obstakel te ontwijken en je aandacht bij het belangrijke werk te houden.", "reflectionNl": "Welke kleine ergernis behandel ik alsof die mijn hele plan onmogelijk maakt?", "exerciseNl": "Haal één praktisch obstakel weg en begin vervolgens vijf minuten aan de taak.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "08-02": {"dateKey": "08-02", "day": 2, "month": 8, "sourceTitle": "WE CAN WORK ANY WAY", "thinker": "Musonius Rufus", "thoughtNl": "Ook als je omstandigheden ingrijpend veranderen, kun je onderzoeken welke vormen van leren en bijdragen nog mogelijk zijn.", "explanationNl": "Theodore Roosevelt hoorde na een operatie dat hij misschien voortaan een rolstoel nodig zou hebben. Volgens de schrijvers ging zijn aandacht meteen naar hoe hij ook dan kon werken. Musonius Rufus zag eveneens mogelijkheden nadat hij herhaaldelijk was verbannen. Hij bleef filosofie beoefenen en gaf tussen zijn ballingschappen les aan Epictetus. Zulke situaties brengen beperkingen mee en kunnen je ook iets leren waarvoor je zelf nooit zou hebben gekozen. De beschikbare speelruimte verdient daarom aandacht.", "reflectionNl": "Welke manier om verder te gaan heb ik nog niet bekeken sinds mijn omstandigheden veranderden?", "exerciseNl": "Kies iets wat je wilt blijven leren en probeer er vandaag een aangepaste vorm van.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "08-03": {"dateKey": "08-03", "day": 3, "month": 8, "sourceTitle": "THE GOOD LIFE IS ANYWHERE", "thinker": "Seneca", "thoughtNl": "Begin waar je nu bent en oefen om goed te werken en te leven op de plek die je hebt.", "explanationNl": "Een succesvolle schrijver uit het boek ging in op uitnodigingen om in prachtige huizen te werken. Telkens lonkte er een nog betere plek, en telkens reisden zijn onzekerheid en gebrek aan inspiratie met hem mee. De schrijvers herkennen dezelfde redenering wanneer we verwachten dat een vakantie vanzelf een relatie verbetert of dat een ideale werkplek ons eindelijk aan het werk zet. Seneca’s antwoord is om aanpassingsvermogen te oefenen. Een rumoerige of alledaagse plek kan ook ruimte bieden om goed te leven.", "reflectionNl": "Welke plek of omstandigheid maak ik in gedachten onmisbaar om eindelijk te beginnen?", "exerciseNl": "Werk vandaag tien minuten aan die taak met wat er op je huidige plek beschikbaar is.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "08-04": {"dateKey": "08-04", "day": 4, "month": 8, "sourceTitle": "NO BLAME, JUST FOCUS", "thinker": "Epictetus", "thoughtNl": "Breng je aandacht terug naar de keuzes die je nog hebt wanneer de omstandigheden je weinig ruimte laten.", "explanationNl": "De schrijvers beschrijven hoe het apartheidsregime Nelson Mandela jarenlang onder vernederende omstandigheden vasthield. Binnen die beperkte ruimte bepaalde hij toch zijn houding. Hij bewoog op een tempo dat hij zelf koos, hield zichzelf fit met schaduwboksen en moedigde medegevangenen aan. Daarmee maakte hij concreet wat Epictetus bedoelt met aandacht voor keuzes die nog bij jezelf liggen. Woede en verwijt kunnen alle aandacht innemen. De schrijvers vragen om ook te zien waar je nog doelgericht kunt handelen.", "reflectionNl": "Welke keuze ligt nog bij mij in een situatie waarin ik me machteloos voel?", "exerciseNl": "Noteer één aspect waarop je geen invloed hebt en kies daarna één handeling die wel binnen je bereik ligt.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "08-05": {"dateKey": "08-05", "day": 5, "month": 8, "sourceTitle": "SILENCE IS STRENGTH", "thinker": "Seneca", "thoughtNl": "Laat af en toe een stilte vallen zodat je kunt luisteren zonder steeds te hoeven bewijzen dat je erbij hoort.", "explanationNl": "De schrijvers vragen je terug te denken aan een opmerking waarvan je later spijt had. Misschien sprak je omdat je slim wilde lijken of aansluiting zocht bij de groep. Wie steeds iets zegt, vergroot volgens hen ook de kans dat die belangrijke feedback of een kans mist. Bewust even buiten een gesprek blijven vergt stevigheid, zeker als praten je normaal geruststelt. Stilte kan ruimte maken om werkelijk te luisteren en minder afhankelijk te worden van bevestiging.", "reflectionNl": "In welk soort gesprek praat ik vooral om ongemak of onzekerheid te verbergen?", "exerciseNl": "Laat in je volgende gesprek na een antwoord twee tellen stilte voordat je zelf reageert.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "08-06": {"dateKey": "08-06", "day": 6, "month": 8, "sourceTitle": "THERE IS ALWAYS MORE ROOM TO MANEUVER THAN YOU THINK", "thinker": "Seneca", "thoughtNl": "Als bijna alles tegenzit, onderzoek dan precies waar nog ruimte zit en zet je aandacht op die kleine mogelijkheid.", "explanationNl": "De schrijvers herinneren aan wedstrijden die onverwacht kantelden en ingevingen die iets opleverden nadat anderen waren afgehaakt. Zulke ervaringen laten zien hoeveel ruimte in het begin aan je blik kan ontsnappen. Seneca stelt voor de moeilijkheid goed te onderzoeken en te zoeken waar gerichte druk iets verandert. Volgens de auteurs helpen energie, vindingrijkheid en vertrouwen om de kleine opening die je nog hebt goed te benutten. In gedachten al opgeven maakt die opening alleen maar moeilijker te zien.", "reflectionNl": "Wat kan ik nog proberen als ik de uitkomst van dit probleem een uur te vroeg heb afgeschreven?", "exerciseNl": "Schrijf drie kleine manieren op waarop de situatie nog kan bewegen en probeer de meest haalbare.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "08-07": {"dateKey": "08-07", "day": 7, "month": 8, "sourceTitle": "PRAGMATIC AND PRINCIPLED", "thinker": "Marcus Aurelius", "thoughtNl": "Ook in een omgeving met weinig ruimte voor je principes kun je oefenen om zorgvuldig en eerlijk te handelen.", "explanationNl": "In zijn biografie van Abraham Lincoln wijst William Lee Miller erop hoe gemakkelijk bewonderaars vergeten dat Lincoln ook politicus was. Voor de schrijvers krijgt zijn houding juist daardoor betekenis. Hij probeerde eerlijk, open en doelgericht te blijven binnen een beroep dat vaak met tegenovergestelde eigenschappen wordt geassocieerd. Marcus ziet dezelfde mogelijkheid aan het keizerlijke hof. Een lastige omgeving vraagt om praktische keuzes, en binnen die keuzes kun je nog altijd laten blijken welke principes je belangrijk vindt.", "reflectionNl": "In welke omgeving geef ik mijn gedrag te snel uit handen aan wat daar gebruikelijk is?", "exerciseNl": "Kies in die omgeving één praktische handeling waarin je vandaag eerlijkheid of zorg kunt laten zien.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "08-08": {"dateKey": "08-08", "day": 8, "month": 8, "sourceTitle": "START WITH WHERE THE WORLD IS", "thinker": "Marcus Aurelius", "thoughtNl": "Neem de wereld zoals je haar aantreft als vertrekpunt en zet vandaag een kleine stap in de richting die telt.", "explanationNl": "De schrijvers halen buurtorganisator Saul Alinsky aan. Wie de wereld wil veranderen, moet volgens hem beginnen bij hoe die er werkelijk voor staat. Dat helpt om te voorkomen dat idealen elke uitvoerbare stap blokkeren. Marcus vraagt om te doen wat binnen je bereik ligt, zonder eerst op erkenning te letten. De auteurs voegen eraan toe dat je een kleine verbetering gerust klein mag noemen. Je kunt aan een hoog doel vasthouden en tegelijkertijd tevreden zijn dat er vandaag iets is opgeschoven.", "reflectionNl": "Welke bescheiden verbetering kan ik vandaag al in gang zetten zonder op een ideaal moment te wachten?", "exerciseNl": "Doe die kleine stap en beschrijf het resultaat in één feitelijke zin.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "08-09": {"dateKey": "08-09", "day": 9, "month": 8, "sourceTitle": "STICK WITH JUST THE FACTS", "thinker": "Marcus Aurelius", "thoughtNl": "Houd even stil bij wat je werkelijk weet voordat een bericht of eerste indruk uitgroeit tot een groter verhaal.", "explanationNl": "Kritisch nadenken helpt vaak om verder te kijken dan wat direct zichtbaar is. De schrijvers merken op dat die gewoonte soms doorschiet en je dingen laat toevoegen die je nog helemaal niet weet. Ze halen Nietzsche aan over de moed om bij de oppervlakte te stoppen. Marcus biedt daarvoor concrete voorbeelden. Dat iemand over je praat en dat jij schade hebt geleden zijn afzonderlijke beweringen. Je kunt de gebeurtenis eerst zo eenvoudig mogelijk beschrijven en pas daarna bepalen wat je ermee doet.", "reflectionNl": "Welke conclusie trok ik vandaag die verder ging dan wat ik feitelijk hoorde of zag?", "exerciseNl": "Splits een voorval in twee korte regels, één voor de waarneming en één voor wat je erbij dacht.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "08-10": {"dateKey": "08-10", "day": 10, "month": 8, "sourceTitle": "PERFECTION IS THE ENEMY OF ACTION", "thinker": "Epictetus", "thoughtNl": "Geef een goed doel ruimte om onvolmaakt te blijven en meet vandaag wat er al een beetje vooruitgaat.", "explanationNl": "De schrijvers verbinden perfectionisme met alles-of-nietsdenken. Wie alleen volmaakt resultaat als succes ziet, raakt gemakkelijk gefrustreerd en verliest zicht op de voortgang die wel mogelijk is. Epictetus vraagt volgens hen om een praktischere maatstaf. Een streven kan de moeite waard blijven zolang je er als mens iets in kunt verbeteren. Een kleine stap telt ook als duidelijk is dat je het geheel nooit perfect zult beheersen. Dat geeft je reden om door te gaan terwijl er nog fouten en beperkingen zijn.", "reflectionNl": "Welke bezigheid heb ik opgegeven omdat ik er niet snel goed genoeg in werd?", "exerciseNl": "Kies één onderdeel van die bezigheid en oefen het kort met een haalbaar doel.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "08-11": {"dateKey": "08-11", "day": 11, "month": 8, "sourceTitle": "NO TIME FOR THEORIES, JUST RESULTS", "thinker": "Musonius Rufus", "thoughtNl": "Oefen goed handelen in de situatie die voor je ligt, zodat je het ook onder lastige omstandigheden kunt toepassen.", "explanationNl": "Musonius Rufus gaf bij het vormen van karakter voorrang aan gewoonte. Een theorie kan vertellen hoe je hoort te handelen, maar door te oefenen leer je het ook daadwerkelijk te doen. De schrijvers halen Hamlet aan om te wijzen op hoeveel meer er in de wereld gebeurt dan een helder schema kan bevatten. In echte situaties moet je afwegen welke reactie hier passend is. Het resultaat van die afweging laat zien hoeveel houvast je ideeën je onder druk geven.", "reflectionNl": "Welk principe kan ik goed uitleggen terwijl ik het in een lastige situatie nauwelijks toepas?", "exerciseNl": "Oefen vandaag één reactie waarin dat principe zichtbaar wordt, bijvoorbeeld rustig doorvragen wanneer je wilt onderbreken.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "08-12": {"dateKey": "08-12", "day": 12, "month": 8, "sourceTitle": "MAKE THE WORDS YOUR OWN", "thinker": "Seneca", "thoughtNl": "Maak een gedachte van een filosoof eigen door te laten zien wat die in jouw gewone keuzes verandert.", "explanationNl": "Sommige lezers vinden dat stoïcijnen veel herhalen en dat Marcus weinig origineel klinkt naast zijn voorgangers. De schrijvers wijzen erop dat Seneca al wist hoeveel denkers van elkaar overnamen. Voor hem woog het gebruik van een inzicht zwaarder dan de vraag wie het als eerste verwoordde. Je kunt een oude gedachte ook aanpassen aan een nieuwe situatie. De overtuigendste manier om te laten zien dat je haar begrijpt, is een handeling waarin je haar werkelijk toepast.", "reflectionNl": "Welk advies haal ik graag aan terwijl het nog weinig verandert aan mijn gedrag?", "exerciseNl": "Kies één advies dat je geregeld deelt en handel er vandaag één keer bewust naar.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "08-13": {"dateKey": "08-13", "day": 13, "month": 8, "sourceTitle": "TAKE CHARGE AND END YOUR TROUBLES", "thinker": "Marcus Aurelius", "thoughtNl": "Gebruik je oordeel voordat angst, jaloezie of frustratie een beslissing stuurt waar je later spijt van hebt.", "explanationNl": "De schrijvers vragen hoeveel van je gevreesde scenario’s werkelijk uitkwamen, en hoeveel last ontstond doordat je uit angst of frustratie reageerde. Je oordeel op tijd gebruiken kost misschien wat moeite, maar kan veel herstelwerk voorkomen. Zij verbinden dat met Benjamin Franklins idee dat voorkomen minder kost dan herstellen. Je kunt je verstand gebruiken om te wegen welk probleem werkelijk aandacht nodig heeft en welke prikkel vooral groter wordt doordat je er meteen op ingaat.", "reflectionNl": "Bij welke terugkerende gedachte reageer ik vaak al voordat ik heb onderzocht of er iets aan de hand is?", "exerciseNl": "Stel één reactie even uit en noteer welke concrete aanwijzingen je werkelijk hebt.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "08-14": {"dateKey": "08-14", "day": 14, "month": 8, "sourceTitle": "THIS ISN’T FOR FUN. IT’S FOR LIFE", "thinker": "Seneca", "thoughtNl": "Laat een filosofisch idee richting geven aan een echte keuze, zeker wanneer je makkelijk over beide kanten kunt blijven praten.", "explanationNl": "De schrijvers vertellen hoe de scepticus Carneades eerst vurig voor rechtvaardigheid pleitte en die de volgende dag als maatschappelijke uitvinding voorstelde. In het verhaal stoorde Cato de Oudere zich eraan dat zo’n belangrijke zaak werd behandeld als gelegenheid om redeneerkunst te tonen. De auteurs herkennen daarin het verschil tussen vrijblijvend debatteren en de manier waarop Seneca filosofie gebruikte. Voor hem hoort zij beslissingen richting te geven wanneer je in het echte leven onzeker bent over wat je moet doen.", "reflectionNl": "Over welk moreel onderwerp voer ik vaak discussies zonder te bepalen wat ik er zelf mee doe?", "exerciseNl": "Kies één concrete beslissing waarin je deze week kunt laten zien welk standpunt je serieus neemt.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "08-15": {"dateKey": "08-15", "day": 15, "month": 8, "sourceTitle": "THE SUPREME COURT OF YOUR MIND", "thinker": "Seneca", "thoughtNl": "Je karakter wordt zichtbaar in de keuzes die je telkens maakt, ook wanneer eerlijkheid of moed minder goed uitkomen.", "explanationNl": "De schrijvers vragen wat iemand in je omgeving zo betrouwbaar maakt. Vaak is het een patroon dat in veel verschillende handelingen opduikt. Ze noemen Theodore Roosevelt, bij wie ze dezelfde volharding herkennen in lichamelijke oefening en in de manier waarop hij na een groot verlies verderging. Voor Seneca begint deugd bij een waarachtig en stevig oordeel. De auteurs wijzen op het verband tussen oefenen en vanzelf reageren. De keuzes die je herhaalt, vormen gaandeweg de neiging waaruit je volgende keuzes ontstaan.", "reflectionNl": "Welke kwaliteit kan iemand aan mijn gewone gedrag herkennen zonder te weten wat ik belangrijk vind?", "exerciseNl": "Kies vandaag twee verschillende momenten om dezelfde kwaliteit bewust in praktijk te brengen.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "08-16": {"dateKey": "08-16", "day": 16, "month": 8, "sourceTitle": "ANYTHING CAN BE AN ADVANTAGE", "thinker": "Marcus Aurelius", "thoughtNl": "Onderzoek wat een vermeende beperking je juist laat doen dat anderen minder makkelijk kunnen of minder snel verwachten.", "explanationNl": "De schrijvers halen basketballer Muggsy Bogues aan, die door zijn lengte vaak werd onderschat. Op het veld bracht diezelfde lengte ook voordelen mee. Hij was snel en kon langere tegenstanders de bal ontfutselen, juist als ze zijn kansen gering inschatten. Marcus’ gedachte wordt daardoor concreet. Je kunt een obstakel bekijken als materiaal waarmee je iets doet. Dat begint bij het onderzoeken van welke mogelijkheden in die eigenschap of situatie besloten liggen, ook als de nadelen meteen duidelijk zijn.", "reflectionNl": "Wat kan ik dankzij een eigenschap die ik doorgaans als beperking beschouw?", "exerciseNl": "Schrijf bij één nadeel een concreet gebruik dat je er deze week van kunt maken.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "08-17": {"dateKey": "08-17", "day": 17, "month": 8, "sourceTitle": "THE BUCK STOPS HERE", "thinker": "Epictetus", "thoughtNl": "Onderzoek bij een tegenvaller welk deel van je reactie bij jou ligt voordat je je aandacht op de schuldvraag richt.", "explanationNl": "De schrijvers stellen een proef voor. Probeer een dag lang bij elke tegenvaller eerst je eigen verwachtingen, interpretaties en keuzes te onderzoeken. Wanneer iemand een instructie verkeerd uitvoert of iets zegt dat je kwetst, kun je bekijken wat je verwachtte en welk oordeel je eraan verbond. Zelfs bij een financieel verlies kun je vragen welke risico’s je bewust nam. Lukt dit een hele dag nauwelijks, probeer het dan tien minuten. Epictetus ziet vooruitgang in het oefenen van dat eigen oordeel.", "reflectionNl": "Bij welke tegenvaller zou aandacht voor mijn eigen verwachtingen iets veranderen aan mijn volgende stap?", "exerciseNl": "Let tien minuten op momenten waarop je een verwijt voelt opkomen en benoem één keuze die nog bij jou ligt.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "08-18": {"dateKey": "08-18", "day": 18, "month": 8, "sourceTitle": "ONLY FOOLS RUSH IN", "thinker": "Epictetus", "thoughtNl": "Kies bewust waaraan je meedoet en besteed je energie aan de beslissingen waarover je zelf zeggenschap hebt.", "explanationNl": "Bij vechtsport heeft het weinig zin een tegenstander aan te vallen op het punt waar die het sterkst is. De schrijvers herkennen hetzelfde probleem bij mensen die overal ja op zeggen of zich zonder voorbereiding tot een krachtmeting laten verleiden. Voor Epictetus is voorzichtig kiezen een manier om je te richten op je eigen oordeel. Bezit en positie kunnen je worden afgenomen, terwijl je zelf bepaalt welke inzet je de moeite waard vindt. Zo vermijd je strijd die vooral onnodige schade oplevert.", "reflectionNl": "Waarvoor dreig ik ja te zeggen omdat iemand me ter plekke om een antwoord vraagt?", "exerciseNl": "Vraag bij één nieuw verzoek bedenktijd en beoordeel dan wat de toezegging werkelijk vraagt.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "08-19": {"dateKey": "08-19", "day": 19, "month": 8, "sourceTitle": "CORRALLING THE UNNECESSARY", "thinker": "Marcus Aurelius", "thoughtNl": "Haal overbodige taken en gedachten weg zodat je de dingen waarvoor je echt verantwoordelijk bent goed kunt doen.", "explanationNl": "De schrijvers benadrukken dat de stoïcijnen hun filosofie midden in een druk leven beoefenden. Zij waren bestuurders, ondernemers, soldaten en kunstenaars. Rust ontstaat volgens Marcus wanneer je je noodzakelijke werk goed doet en overbodige woorden, daden en gedachten begrenst. De auteurs vragen om eerlijk te kijken naar de herkomst van wat je druk houdt. IJdelheid, hebzucht, gebrek aan discipline en moeite om nee te zeggen kunnen je agenda voller maken dan je werkelijke verantwoordelijkheden vragen.", "reflectionNl": "Welke verplichting heb ik vooral aangenomen omdat ik indruk wilde maken of geen nee durfde zeggen?", "exerciseNl": "Haal één overbodige taak uit je planning en geef de vrijgekomen tijd aan een verantwoordelijkheid die ertoe doet.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "08-20": {"dateKey": "08-20", "day": 20, "month": 8, "sourceTitle": "WHERE IT COUNTS", "thinker": "Seneca", "thoughtNl": "Werk aan de verandering die in je keuzes zichtbaar wordt, ook als je uiterlijk er hetzelfde bij blijft.", "explanationNl": "De schrijvers halen Diogenes aan als iemand wiens woorden nog steeds tot nadenken stemmen, maar wiens opvallende manier van leven tijdgenoten gemakkelijk kon afschrikken. Ze vragen wie ermee geholpen is wanneer je filosofische overtuigingen vooral via extreme uiterlijke keuzes kenbaar maakt. Nieuwe kleren, een andere auto of een ander uiterlijk kunnen voelen als een grote stap. Seneca hecht meer waarde aan innerlijke verandering, ook wanneer de mensen om je heen die aanvankelijk helemaal niet opmerken.", "reflectionNl": "Welke uiterlijke verandering zou mij het gevoel geven dat ik groei, en welke gewoonte vraagt werkelijk om aandacht?", "exerciseNl": "Kies één innerlijke houding die je vandaag kunt oefenen zonder daar iets aan je uiterlijk voor te veranderen.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "08-21": {"dateKey": "08-21", "day": 21, "month": 8, "sourceTitle": "DON’T BE MISERABLE IN ADVANCE", "thinker": "Seneca", "thoughtNl": "Gebruik de tijd waarin je op mogelijk slecht nieuws wacht voor iets dat je vandaag nog kunt doen.", "explanationNl": "De schrijvers beschrijven hoe wachten op slecht nieuws kan leiden tot lichamelijke spanning en een kort lontje bij de mensen om je heen. Komt het gevreesde nieuws nooit, dan heeft de angst je toch tijd gekost. Komt het wel, dan heb je de moeilijke periode in gedachten eerder laten beginnen. Seneca vraagt aandacht voor wat er in het heden beschikbaar blijft. Terwijl je op een uitslag wacht, kun je aan iets werken of iemand aandacht geven waar je vandaag werkelijk iets mee kunt.", "reflectionNl": "Wat krijgt nu minder aandacht doordat ik in gedachten op een onzekere uitkomst vooruitloop?", "exerciseNl": "Kies tijdens het wachten een taak van tien minuten die voor jou of iemand anders betekenis heeft.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "08-22": {"dateKey": "08-22", "day": 22, "month": 8, "sourceTitle": "DON’T SWEAT THE SMALL STUFF", "thinker": "Marcus Aurelius", "thoughtNl": "Geef een kleine taak de tijd die ze nodig heeft en bescherm zo je aandacht voor wat belangrijker is.", "explanationNl": "De schrijvers herkennen in Richard Carlsons advies over kleine ergernissen dezelfde gedachte als bij Marcus. Je tijd is kostbaar en komt nooit terug. Sommige onbelangrijke taken zijn verplicht, maar je kunt beperken hoeveel tijd en gepieker ze in beslag nemen. Wanneer je iets kleins eindeloos aandacht geeft, maak je het belangrijk door het aandeel van je leven dat je eraan besteedt. Die aandacht gaat dan ten koste van mensen, gezondheid of verbintenissen die je zelf hoger aanslaat.", "reflectionNl": "Welke kleine taak krijgt structureel meer aandacht dan het resultaat voor mij waard is?", "exerciseNl": "Geef die taak een korte eindtijd en gebruik de resterende tijd voor iets dat meer waarde heeft.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "08-23": {"dateKey": "08-23", "day": 23, "month": 8, "sourceTitle": "IT’S IN YOUR SELF-INTEREST", "thinker": "Seneca", "thoughtNl": "Laat bij een gedragsverandering zien welk concreet voordeel die oplevert en wat er gebeurt wanneer plezier zijn maat verliest.", "explanationNl": "Een preek over een abstract principe overtuigt volgens de schrijvers zelden. Seneca gebruikt dronkenschap als voorbeeld. Je kunt laten zien wat iemand overkomt wanneer een plezier doorschiet en in ongemak verandert. De auteurs passen dat toe op pogingen om anderen tot verandering te bewegen. Benoem welke winst een andere manier van doen voor hen heeft en maak de gevolgen concreet. Dezelfde aanpak werkt als onderzoek naar je eigen gedrag. Je kunt je afvragen wat een gewoonte je werkelijk oplevert en waar ze je begint te schaden.", "reflectionNl": "Bij welke gewoonte kan ik het omslagpunt aanwijzen waarop plezier overgaat in last?", "exerciseNl": "Noteer bij die gewoonte één voordeel van matiging dat je de volgende keer direct kunt merken.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "08-24": {"dateKey": "08-24", "day": 24, "month": 8, "sourceTitle": "PILLAGE FROM ALL SOURCES", "thinker": "Seneca", "thoughtNl": "Beoordeel een inzicht op wat je ermee kunt leren, ook wanneer het van een denker komt met wie je vaak verschilt.", "explanationNl": "Seneca citeert Epicurus geregeld, hoewel hun filosofische scholen vaak als tegenpolen worden gezien. De schrijvers merken op dat die verschillen betekenis hebben en ook gemakkelijk worden uitvergroot. Wat zij aan Seneca waarderen, is zijn bereidheid om bruikbare wijsheid te vinden waar die zich aandient. Een idee verdient aandacht op grond van wat het bijdraagt aan je handelen en ontwikkeling. Reputatie, groepsnaam en de vraag of alles in dezelfde leer past, kunnen je blik anders onnodig vernauwen.", "reflectionNl": "Van wie neem ik zelden iets aan terwijl die persoon op één punt misschien iets scherps ziet?", "exerciseNl": "Zoek één bruikbaar inzicht bij iemand met wie je vaak van mening verschilt en bekijk wat eraan klopt.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "08-25": {"dateKey": "08-25", "day": 25, "month": 8, "sourceTitle": "RESPECT THE PAST, BUT BE OPEN TO THE FUTURE", "thinker": "Seneca", "thoughtNl": "Gebruik een beproefde traditie als gids en geef een betere aanpak ruimte zodra je ziet waarom die beter werkt.", "explanationNl": "De schrijvers erkennen dat tradities vaak lang geteste manieren van werken bewaren. Ze herinneren er ook aan dat gevestigde ideeën ooit nieuw en omstreden konden zijn. Seneca gebruikte oudere denkers als gidsen en hield ruimte om verder te zoeken. Op dezelfde manier kan een inzicht uit latere psychologie of uit eigen ervaring iets toevoegen aan een oud filosofisch advies. Een nieuwe aanpak verdient volgens de auteurs ruimte zodra je goede redenen hebt om die voor juister of beter te houden.", "reflectionNl": "Welke werkwijze volg ik vooral omdat die altijd zo werd gedaan?", "exerciseNl": "Probeer bij één kleine taak een alternatief en vergelijk het resultaat met de bestaande werkwijze.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "08-26": {"dateKey": "08-26", "day": 26, "month": 8, "sourceTitle": "SEEKING OUT SHIPWRECKS", "thinker": "Seneca", "thoughtNl": "Houd ruimte voor de mogelijkheid dat een verlies je leven een richting geeft die je nog niet kunt zien.", "explanationNl": "De schrijvers vertellen hoe Zeno volgens de overlevering bij een schipbreuk zijn handelswaar verloor. In Athene kwam hij daarna via een boekhandel in aanraking met Socrates’ filosofie en later met de filosoof Crates. Dat hielp de koers bepalen die uiteindelijk naar de stoïcijnse school leidde. Voor de auteurs laat dit verhaal zien waarom stoïcijnen hun plannen maakten met ruimte voor een andere afloop. Zelfs een ingrijpende mislukking kan mogelijkheden openen die vanuit het oorspronkelijke plan ondenkbaar waren.", "reflectionNl": "Welke onverwachte richting is beschikbaar geworden sinds iets anders is weggevallen?", "exerciseNl": "Kies een veranderde situatie en onderzoek één mogelijkheid die je oude plan niet bood.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "08-27": {"dateKey": "08-27", "day": 27, "month": 8, "sourceTitle": "LAUGH, OR CRY?", "thinker": "Seneca", "thoughtNl": "Zoek naar de humor in een frustrerende situatie wanneer die je helpt om haar met minder zwaarte te dragen.", "explanationNl": "Seneca plaatst Heraclitus, die volgens het verhaal bij het zien van de wereld huilde, naast Democritus, die erom lachte. De schrijvers herkennen daarin de vertrouwde twijfel of je bij iets frustrerends moet lachen of huilen. Ze wijzen erop dat woede of verdriet een situatie soms alleen zwaarder maakt, vooral als die situatie door jouw gevoelens niet verandert. Humor kan op zulke momenten ruimte scheppen. Dat past bij een filosofie die volgens hen ook midden in tegenslag plaats maakt voor lichtheid.", "reflectionNl": "Welk alledaags gedoe zou ik later met een glimlach kunnen navertellen?", "exerciseNl": "Beschrijf een kleine ergernis als een korte komische scène waarin je ook je eigen rol meeneemt.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "08-28": {"dateKey": "08-28", "day": 28, "month": 8, "sourceTitle": "THE OPULENT STOIC", "thinker": "Seneca", "thoughtNl": "Geniet van wat je hebt zonder je leven zo in te richten dat je steeds meer luxe moet bekostigen.", "explanationNl": "Seneca kreeg kritiek omdat hij grote rijkdom bezat terwijl hij matigheid preekte. Zijn verdediging was dat hij het geld wel had, maar er naar eigen zeggen niet van afhankelijk was. De schrijvers laten open hoe overtuigend die verdediging bij hemzelf was. Ze nemen er een praktische vraag uit mee. Kun je geld hebben zonder uitgaven te doen die je dwingen steeds meer te werken en steeds minder tijd aan studie of nadenken te besteden? Goed leven kan volgens hen met betrekkelijk weinig.", "reflectionNl": "Welke uitgave bindt mij aan meer werk of verplichtingen dan ik ervoor overheb?", "exerciseNl": "Kijk naar één terugkerende luxe-uitgave en schrijf op hoeveel tijd en vrijheid ermee gemoeid zijn.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "08-29": {"dateKey": "08-29", "day": 29, "month": 8, "sourceTitle": "WANT NOTHING = HAVE EVERYTHING", "thinker": "Seneca", "thoughtNl": "Kijk welke wensen je kunt loslaten en wat je al hebt dat je met plezier beter kunt gebruiken.", "explanationNl": "Zelfs de rijkste mensen kunnen volgens de schrijvers zaken als liefde, respect en invloed lang niet altijd kopen. Meer vermogen lost dus maar een deel van de spanning tussen bezit en verlangen op. Ze halen John D. Rockefeller aan, die rijkdom ook zag als verhouding tussen inkomen, uitgaven en wensen. Seneca richt je aandacht op de kant waarop je zelf invloed hebt. Als je minder nodig vindt, kan wat je al hebt eerder genoeg zijn en beter van pas komen.", "reflectionNl": "Welk verlangen zou minder belangrijk worden als ik beter gebruikte wat ik al heb?", "exerciseNl": "Stel één voorgenomen aankoop uit en probeer eerst wat je met iets dat je al bezit kunt doen.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "08-30": {"dateKey": "08-30", "day": 30, "month": 8, "sourceTitle": "WHEN YOU FEEL LAZY", "thinker": "Seneca", "thoughtNl": "Onderzoek je tegenzin, bepaal of de taak nodig is en geef haar daarna de aandacht die ze verdient.", "explanationNl": "De schrijvers stellen voor om bij luiheid of irritatie eerst te onderzoeken waarom je aan een taak begon. Als ze echt moet gebeuren, kun je vervolgens vragen waar de weerstand vandaan komt. Angst, wrok en vermoeidheid vragen verschillende antwoorden. Halverwege hopen dat iemand je komt aflossen, houdt je verdeeld tussen je toezegging en je gedrag. De verwijzing naar Steve Jobs benadrukt de waarde van de kwaliteit van je inzet. Een taak bewust aanpakken kan meer opleveren dan meerdere taken met halve aandacht doen.", "reflectionNl": "Waar zeg ik in woorden ja tegen terwijl mijn manier van werken laat zien dat ik ertegenin ga?", "exerciseNl": "Benoem bij één taak de oorzaak van je tegenzin en kies daarna één concrete stap waaraan je volle aandacht geeft.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "08-31": {"dateKey": "08-31", "day": 31, "month": 8, "sourceTitle": "CONSIDER YOUR FAILINGS TOO", "thinker": "Marcus Aurelius", "thoughtNl": "Denk bij andermans fout aan een vergelijkbare keer dat jij tekortschoot en kijk wat je daardoor beter begrijpt.", "explanationNl": "De schrijvers verbinden Marcus met Socrates’ idee dat mensen vaak verkeerd handelen zonder dat ze kwaad willen. Ze nodigen je uit om je eigen voorbeelden op te halen. Misschien was je onbeleefd door slaapgebrek, handelde je op verkeerde informatie of begreep je iets verkeerd. De mildheid waarmee je zulke gevallen bij jezelf bekijkt, kun je ook een ander gunnen. Dat kan helpen om iemand na een fout weer als samenwerkingspartner te zien en diens goede eigenschappen te blijven waarderen.", "reflectionNl": "Welke vergelijkbare fout maakte ik zelf met minder slechte bedoelingen dan iemand van buitenaf misschien dacht?", "exerciseNl": "Schrijf bij een ergernis eerst op welke omstandigheden je bij jezelf zou meewegen.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "09-01": {"dateKey": "09-01", "day": 1, "month": 9, "sourceTitle": "A STRONG SOUL IS BETTER THAN GOOD LUCK", "thinker": "Seneca", "thoughtNl": "Oefen omgaan met ongemak terwijl je kunt kiezen, zodat veranderende omstandigheden minder vat op je krijgen.", "explanationNl": "Cato de Jongere kon zich mooie kleding en uitgebreid eten veroorloven. Toch liep hij in Rome vaak blootsvoets, at hij eenvoudig en liet hij regen en hitte op zich inwerken zonder zijn hoofd te bedekken. De auteurs lezen die keuzes als training. Cato maakte zijn kalmte minder afhankelijk van comfort en van wat voorbijgangers van hem dachten. Zo bereidde hij zich voor op omstandigheden die hij als soldaat, staatsman en vader niet kon kiezen.", "reflectionNl": "Welk gemak ben je gaan beschouwen als voorwaarde om een gewone dag goed door te komen?", "exerciseNl": "Laat vandaag bij één kleine klus een gewoon gemak weg en kijk hoe snel je eraan went.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "09-02": {"dateKey": "09-02", "day": 2, "month": 9, "sourceTitle": "THE PHILOSOPHER’S SCHOOL IS A HOSPITAL", "thinker": "Epictetus", "thoughtNl": "Een oefening die een gevoelig punt raakt, kan je laten zien waar je nog kracht moet opbouwen.", "explanationNl": "De auteurs vergelijken filosofie met fysiotherapie. Een therapeut weet waar gerichte druk of belasting nodig is om een verzwakt lichaamsdeel sterker te maken. Dat kan tijdens de behandeling onaangenaam zijn. Een stoïcijnse oefening kan op dezelfde manier precies de overtuiging raken waar je het liefst omheen loopt. De wrijving hoort bij het oefenen. Door daar aandacht aan te geven, ontwikkel je volgens de auteurs het vermogen om bij moeilijkheden langer vol te houden.", "reflectionNl": "Welke opmerking bleef bij je hangen omdat ze iets raakte waar je zelf onzeker over bent?", "exerciseNl": "Schrijf op welk deel van die opmerking je aan het denken zet.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "09-03": {"dateKey": "09-03", "day": 3, "month": 9, "sourceTitle": "FIRST, A HARD WINTER TRAINING", "thinker": "Epictetus", "thoughtNl": "De rustige dagen geven je tijd om te oefenen voor situaties waarin je die voorbereiding nodig hebt.", "explanationNl": "Vroeger hielden militaire campagnes in de winter vaak op. De auteurs lezen Epictetus' wintertraining als een aansporing om de periode tussen beproevingen serieus te gebruiken. Ze vergelijken die houding met die van LeBron James, die de zomer benut om onderdelen van zijn spel te verbeteren, en met soldaten die in vredestijd oefenen. Ook bij gewone tegenslag hangt je reactie mede af van wat je eerder hebt geoefend. Zodra het erop aankomt, helpt die voorbereiding je volhouden.", "reflectionNl": "Welke situatie komt steeds terug waarvoor je telkens ter plekke een oplossing moet bedenken?", "exerciseNl": "Oefen vandaag alvast één handeling die je in die situatie wilt kunnen uitvoeren.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "09-04": {"dateKey": "09-04", "day": 4, "month": 9, "sourceTitle": "HOW CAN YOU KNOW WHETHER YOU’VE NEVER BEEN TESTED?", "thinker": "Seneca", "thoughtNl": "Een moeilijke periode kan zichtbaar maken hoeveel je aankunt en waar je voortaan op kunt vertrouwen.", "explanationNl": "De auteurs merken op dat mensen soms met trots terugkijken op jaren die tijdens het meemaken zwaar vielen. Een moeilijke tijd kan hun karakter vormen en hun tegelijk iets leren wat ze in rustige jaren niet konden ontdekken: hoe ze reageren wanneer er werkelijk iets op het spel staat. Wie al eens door tegenslag heen is gekomen, heeft bij een volgende beproeving een concrete herinnering aan zijn eigen vermogen om stand te houden.", "reflectionNl": "Welke moeilijke periode heeft je iets over jezelf geleerd waar je bij een volgend probleem op kunt terugvallen?", "exerciseNl": "Noteer één concrete handeling uit die tijd die je opnieuw zou kunnen inzetten.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "09-05": {"dateKey": "09-05", "day": 5, "month": 9, "sourceTitle": "FOCUS ON WHAT IS YOURS ALONE", "thinker": "Epictetus", "thoughtNl": "Richt je aandacht op keuzes die je zelf kunt maken, juist wanneer de afloop volledig buiten je macht ligt.", "explanationNl": "De auteurs vertellen hoe James Stockdale na zijn gevangenneming in Vietnam terugviel op Epictetus. Hij wist dat zijn gevangenschap lang kon duren en hield zich bezig met zijn eigen handelen onder die omstandigheden. Medegevangenen die hun hoop telkens op een naderende feestdag vestigden, kregen volgens zijn herinnering steeds opnieuw een klap als de datum verstreek. Stockdales houding laat zien hoe een uitkomst waarop je geen invloed hebt je aandacht kan wegtrekken bij de keuzes die je nog wel kunt maken.", "reflectionNl": "Waar wacht je op een datum of besluit dat iemand anders bepaalt?", "exerciseNl": "Kies iets kleins wat je vandaag kunt doen, ongeacht wanneer dat besluit valt.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "09-06": {"dateKey": "09-06", "day": 6, "month": 9, "sourceTitle": "THEY CAN THROW YOU IN CHAINS, BUT . . .", "thinker": "Epictetus", "thoughtNl": "Zelfs onder zware druk kun je zoeken naar een keuze die trouw blijft aan wat jij belangrijk vindt.", "explanationNl": "De auteurs plaatsen Epictetus naast twee krijgsgevangenen uit de Vietnamoorlog. Over Epictetus gaat het verhaal dat hij door zijn ketenen mank liep. James Stockdale werd eveneens vastgeketend. John McCain kreeg de kans eerder vrij te komen als hij zijn medegevangenen achterliet en sloeg die af. Voor de auteurs maakt dat verschil duidelijk wat Epictetus bedoelt met keuzevrijheid. Iemand kan je bewegingsvrijheid ontnemen en je onder grote druk zetten, terwijl je nog een eigen besluit kunt nemen over je principes.", "reflectionNl": "Bij welke keuze zou je achteraf trots zijn dat je je aan je principes hield, ook als ze je iets kost?", "exerciseNl": "Schrijf in één zin welk principe je bij die keuze wilt volgen.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "09-07": {"dateKey": "09-07", "day": 7, "month": 9, "sourceTitle": "OUR HIDDEN POWER", "thinker": "Epictetus", "thoughtNl": "Zoek onder druk naar de kleine keuzes die je nog hebt over je houding en wat je kunt bijdragen.", "explanationNl": "De auteurs halen Viktor Frankl aan, die in concentratiekampen gevangenzat en zijn familie en werk verloor. Ze beschrijven hoe hij binnen die omstandigheden bleef nadenken over de betekenis van zijn ervaringen, zijn psychologische ideeën onderzocht en mogelijkheden zag om anderen te helpen. Zijn voorbeeld verlegt de aandacht naar de kleine beslissingen die soms overblijven wanneer bijna alles voor je wordt bepaald. De auteurs vragen waar je zulke beslissingen in je eigen verplichtingen over het hoofd ziet.", "reflectionNl": "Welke kleine keuze kun je vandaag zelf maken binnen een verplichting die je liever niet had gehad?", "exerciseNl": "Maak die keuze bewust en merk op welk verschil ze maakt in je dag.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "09-08": {"dateKey": "09-08", "day": 8, "month": 9, "sourceTitle": "DO NOT BE DECEIVED BY FORTUNE", "thinker": "Seneca", "thoughtNl": "Geniet van voorspoed zolang die duurt en oefen om je evenwicht te bewaren als je omstandigheden veranderen.", "explanationNl": "Na zijn verbanning naar Corsica schreef Seneca zijn moeder een troostbrief. De auteurs lezen er ook een poging in om zichzelf moed in te spreken. Hij wilde wel degelijk terug naar Rome en vroeg daar ook om. Ondertussen hielp zijn filosofie hem het wachten en de vernedering te dragen. Toen hij zijn positie terugkreeg, kon hij volgens de auteurs beter beseffen hoe voorlopig die was. Een volgende machtswisseling liet zien hoe snel voorspoed opnieuw kon omslaan.", "reflectionNl": "Welke meevaller voelt inmiddels als iets waar je vanzelfsprekend op kunt rekenen?", "exerciseNl": "Bedenk één manier waarop je met een gewone verandering daarin zou omgaan.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "09-09": {"dateKey": "09-09", "day": 9, "month": 9, "sourceTitle": "NOTHING TO FEAR BUT FEAR ITSELF", "thinker": "Seneca", "thoughtNl": "Angst kan het probleem vergroten als ze je weghoudt van de eerste stap die werkelijk helpt.", "explanationNl": "Bij zijn aantreden tijdens de Grote Depressie sprak Roosevelt een land toe waar banken omvielen en veel mensen bang waren. In zijn rede ging het de auteurs vooral om het verlammende effect van paniek: die staat juist de inspanningen in de weg die herstel mogelijk maken. De stoïcijnse toepassing ligt in het verschil tussen de oorspronkelijke moeilijkheid en de extra schade die ontstaat wanneer je overhaast handelt om maar aan je angst te ontkomen.", "reflectionNl": "Waar zou je eerst naar kijken als je de neiging om onmiddellijk te reageren even liet zakken?", "exerciseNl": "Beschrijf het concrete probleem in één zin en kies één actie die daar rechtstreeks bij helpt.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "09-10": {"dateKey": "09-10", "day": 10, "month": 9, "sourceTitle": "PREPARING ON THE SUNNY DAY", "thinker": "Seneca", "thoughtNl": "Gebruik een goede dag om op kleine schaal te oefenen met iets waarvan het wegvallen je onzeker maakt.", "explanationNl": "De auteurs stellen voor een gevreesde verandering tijdelijk na te bootsen, bijvoorbeeld door ergens heen te lopen in plaats van de auto te nemen. De eerste schrik kan afnemen zodra je merkt hoe het dagelijks leven onder andere omstandigheden aanvoelt. Ze halen Seneca aan omdat hij die oefening juist voor rustige tijden aanbeveelt. Dan kun je met enige speelruimte ontdekken wat er lastig aan is, hoe je ermee omgaat en welke problemen je vooraf al kunt oplossen.", "reflectionNl": "Welk klein ongemak lijkt je op afstand erger dan het in de praktijk misschien is?", "exerciseNl": "Kies één veilige oefening, bijvoorbeeld een bekende korte rit vandaag te voet afleggen.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "09-11": {"dateKey": "09-11", "day": 11, "month": 9, "sourceTitle": "WHAT WOULD LESS LOOK LIKE?", "thinker": "Seneca", "thoughtNl": "Wennen aan wat minder kan je helpen wanneer geld, aanzien of bewegingsvrijheid buiten je wil om afnemen.", "explanationNl": "De auteurs noemen schrijver Stefan Zweig, die wereldwijd succes kende en door de opkomst van Hitler zijn bestaan zag ontwricht. Zulke omslagen kunnen ook mensen treffen die eerlijk hebben gewerkt of buiten hun schuld iets verliezen. Met ouder worden kunnen bovendien energie en bewegingsvrijheid afnemen. De auteurs zien binnen je middelen leven als een manier om je alvast vertrouwd te maken met minder. Daardoor kan de emotionele schok van een onverwachte terugval kleiner worden.", "reflectionNl": "Waarop zou je als eerste besparen als je tijdelijk minder geld of energie had?", "exerciseNl": "Probeer vandaag één eenvoudige, goedkopere of minder inspannende versie van een vaste gewoonte.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "09-12": {"dateKey": "09-12", "day": 12, "month": 9, "sourceTitle": "BE DOWN TO EARTH, OR BE BROUGHT DOWN", "thinker": "Diogenes Laërtius", "thoughtNl": "Blijf benaderbaar en bescheiden, zodat anderen je kunnen bereiken voordat je zelfvertrouwen omslaat in zelfoverschatting.", "explanationNl": "De auteurs brengen Zeno's waarschuwing samen met het advies van Isocrates aan de jonge Demonicus om vriendelijk en toegankelijk te blijven. Ze herkennen dezelfde les in verhalen waarin een overmoedige jongeling door een oudere figuur op zijn plaats wordt gezet. Zulke botsingen ontstaan gemakkelijk wanneer iemand denkt alles al te begrijpen en anderen op afstand houdt. Wie zelf met beide benen op de grond blijft, verkleint de kans op een harde correctie door de werkelijkheid.", "reflectionNl": "In welk gesprek zou je vandaag kunnen erkennen dat iemand anders iets beter weet dan jij?", "exerciseNl": "Stel die persoon één oprechte vraag over wat je nog niet weet.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "09-13": {"dateKey": "09-13", "day": 13, "month": 9, "sourceTitle": "PROTECTING OUR INNER FORTRESS FROM FEAR", "thinker": "Epictetus", "thoughtNl": "Je oordeel is een plek waar je invloed houdt, zolang angst en hebzucht je besluiten niet ongemerkt overnemen.", "explanationNl": "De auteurs beschrijven de stoïcijnse innerlijke vesting als de plek die van jou blijft, ook wanneer je lichaam kwetsbaar is en het lot je bewegingsruimte beperkt. Ze voegen een waarschuwing toe uit de geschiedenis van echte vestingen. Zelfs sterke muren bieden weinig bescherming als mensen binnen de poort uit angst of hebzucht openzetten. De vergelijking helpt zichtbaar maken hoe je eigen reactie een bedreiging toegang kan geven tot je oordeel en handelen.", "reflectionNl": "Bij welk besluit merk je dat angst je eerste ingeving stuurt?", "exerciseNl": "Noteer welke informatie je nog nodig hebt om dat besluit kalmer te nemen.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "09-14": {"dateKey": "09-14", "day": 14, "month": 9, "sourceTitle": "A DIFFERENT WAY TO PRAY", "thinker": "Marcus Aurelius", "thoughtNl": "Vraag bij tegenslag om de kracht en helderheid om te doen wat op dit moment binnen je bereik ligt.", "explanationNl": "Iedereen hoopt weleens in stilte dat iets goed zal aflopen, ook zonder religieus geloof. De auteurs zien daar een vorm van bidden in. Veel van die wensen gaan over een uitkomst die ons leven gemakkelijker zou maken, van een tweede kans tot de uitslag van een wedstrijd. Bij Marcus Aurelius lezen zij een andere mogelijkheid: vragen om de moed om te handelen of om zicht op wat je zelf kunt doen. Soms blijkt die mogelijkheid er al te zijn.", "reflectionNl": "Welke wens over de afloop kun je vandaag omzetten in een vraag over je eigen handelen?", "exerciseNl": "Formuleer die vraag en geef jezelf één concreet antwoord.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "09-15": {"dateKey": "09-15", "day": 15, "month": 9, "sourceTitle": "A GARDEN IS NOT FOR SHOW", "thinker": "Epictetus", "thoughtNl": "Je merkt pas of een filosofie wortel schiet wanneer je haar gebruikt bij een beslissing die moeite kost.", "explanationNl": "De auteurs vergelijken filosofie met een tuin die je kunt aanleggen om indruk te maken of om je gezin te voeden. Boeken verzamelen en instemmen met ideeën kan prettig zijn, maar het zegt weinig over wat je ermee doet. De waarde ontstaat wanneer je aandacht geeft aan gewoonten en overtuigingen terwijl hun ontwikkeling voor anderen nog onzichtbaar is. Door ze herhaaldelijk in de praktijk te brengen, krijgen ze volgens de auteurs tijd om te wortelen vóór een zware periode aanbreekt.", "reflectionNl": "Welk inzicht kun je gemakkelijk navertellen maar vind je nog lastig om toe te passen?", "exerciseNl": "Kies één moment vandaag waarop je dat inzicht bewust kunt gebruiken.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "09-16": {"dateKey": "09-16", "day": 16, "month": 9, "sourceTitle": "ANYONE CAN GET LUCKY, NOT EVERYONE CAN PERSEVERE", "thinker": "Seneca", "thoughtNl": "Kijk bij succes ook naar het geduld, de eerlijkheid en de zelfbeheersing die iemand onderweg heeft laten zien.", "explanationNl": "De auteurs wijzen op het verschil tussen voorspoed die iemand toevalt en standhouden onder moeilijke omstandigheden. Het is begrijpelijk dat een leven waarin veel vanzelf lijkt te gaan aantrekkelijk oogt. Wat zij bij Seneca bewonderenswaardig vinden, is hoe iemand zijn weg vervolgt terwijl er goede redenen zijn om op te geven. Daarbij tellen zowel de obstakels onderweg als de manier waarop die persoon met zijn eigen emoties omgaat en eerlijk blijft handelen.", "reflectionNl": "Van wie waardeer je de manier waarop diegene volhield, ook los van het behaalde resultaat?", "exerciseNl": "Benoem één gedrag van die persoon dat je bij je eigen werk kunt oefenen.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "09-17": {"dateKey": "09-17", "day": 17, "month": 9, "sourceTitle": "DEALING WITH HATERS", "thinker": "Marcus Aurelius", "thoughtNl": "Reageer op andermans oordeel als je er invloed op kunt hebben, en laat het daarna bij die persoon.", "explanationNl": "Volgens de auteurs kan een fel oordeel veel zeggen over degene die het uitspreekt. Dat geldt in het bijzonder voor haat en wrok. Hun stoïcijnse reactie begint met de vraag of je iets aan die mening kunt veranderen. Een open gesprek kan zin hebben wanneer iemand ervoor ontvankelijk is. Als die ruimte ontbreekt, kun je diegene laten zoals hij is. De auteurs waarschuwen dat wederzijdse haat en blijven gissen naar iemands gedachten energie vragen die je voor je eigen handelen nodig hebt.", "reflectionNl": "Welke negatieve mening blijft je bezighouden, en welk deel daarvan kun je daadwerkelijk beïnvloeden?", "exerciseNl": "Kies één passende reactie of schrijf op waarom je die mening vandaag laat rusten.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "09-18": {"dateKey": "09-18", "day": 18, "month": 9, "sourceTitle": "DEALING WITH PAIN", "thinker": "Marcus Aurelius", "thoughtNl": "Pijn kan je aandacht opeisen, terwijl er soms toch ruimte overblijft om zorgvuldig met een ander om te gaan.", "explanationNl": "De auteurs beschrijven hoe Churchill in New York werd aangereden. Ondanks zijn verwondingen nam hij tegenover de politie de verantwoordelijkheid op zich. Toen de bestuurder hem in het ziekenhuis bezocht, wilde Churchill hem zelfs helpen, uit zorg over de gevolgen van de publiciteit voor zijn kansen op werk. De auteurs verbinden die ruimhartigheid met het besef dat pijn uiteindelijk verandert of eindigt. Zijn voorbeeld laat zien welke houding je tijdens een beproeving nog kunt proberen in te nemen.", "reflectionNl": "Wanneer maakte je eigen ongemak het laatst moeilijk om rekening te houden met iemand anders?", "exerciseNl": "Denk bij een klein ongemak vandaag kort na over wie er nog meer door geraakt wordt.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "09-19": {"dateKey": "09-19", "day": 19, "month": 9, "sourceTitle": "FLEXIBILITY OF THE WILL", "thinker": "Marcus Aurelius", "thoughtNl": "Houd vast aan het doel dat de moeite waard is en verander je aanpak zodra de feiten daarom vragen.", "explanationNl": "De auteurs waarderen het vermogen om af te maken wat je begint. Die vastberadenheid kan je echter vastzetten wanneer de omstandigheden intussen veranderen. Wie nieuwe informatie blijft negeren, gebruikt zijn oordeel niet meer om te bepalen welke actie bij het doel past. Daarom zien zij bij Marcus Aurelius soepelheid als een vorm van kracht. Je kunt je inzet behouden en tegelijk je oordeel, eerste neiging of plan herzien als je daardoor beter handelt.", "reflectionNl": "Welk plan houd je vooral aan omdat je er eenmaal aan begonnen bent?", "exerciseNl": "Schrijf één nieuw feit op en bepaal of het om een andere volgende stap vraagt.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "09-20": {"dateKey": "09-20", "day": 20, "month": 9, "sourceTitle": "LIFE ISN’T A DANCE", "thinker": "Marcus Aurelius", "thoughtNl": "Reken erop dat weerstand en verrassingen bij moeilijke doelen horen en train om onder druk te blijven handelen.", "explanationNl": "De auteurs vinden de vergelijking tussen leven en dansen te beperkt. Ritme en soepel bewegen zijn nuttig, maar een danser wordt op het podium doorgaans niet door een tegenstander tegen de grond gewerkt. Voor een worstelaar horen weerstand en onverwachte bewegingen juist bij het vak. Die moet tegelijk omgaan met zijn tegenstander, zijn emoties en de grenzen van zijn training. Zo helpt filosofie volgens de auteurs om ook buiten de sport je vastberadenheid onder druk te oefenen.", "reflectionNl": "Welke vorm van tegenstand verrast je telkens bij een doel dat je belangrijk vindt?", "exerciseNl": "Oefen één reactie op een te verwachten tegenslag voordat die zich voordoet.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "09-21": {"dateKey": "09-21", "day": 21, "month": 9, "sourceTitle": "MAINTAIN COMPOSURE, MAINTAIN CONTROL", "thinker": "Marcus Aurelius", "thoughtNl": "Als een onverwachte gebeurtenis je uit balans brengt, geef jezelf dan even tijd om je aandacht weer te verzamelen.", "explanationNl": "Een lege accu, een afgezegde afspraak of plotselinge klachten kunnen een planning ontregelen die op heel gewone verwachtingen was gebouwd. Volgens de auteurs is het begrijpelijk als je daarvan even in de war raakt. Ook muzikanten raken soms de draad kwijt wanneer hun apparatuur hapert. Hun vaardigheid blijkt uit hoe ze hun plek terugvinden. Bij een verrassing in je eigen dag kun je op dezelfde manier nagaan waar je weer kunt aanhaken.", "reflectionNl": "Welke volgende stap helpt je vandaag verder als je oorspronkelijke plan wegvalt?", "exerciseNl": "Noem eerst wat er is veranderd en pak daarna de kleinste nog haalbare stap op.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "09-22": {"dateKey": "09-22", "day": 22, "month": 9, "sourceTitle": "NO PAIN, NO GAIN", "thinker": "Epictetus", "thoughtNl": "Een sterkere tegenstander kan je laten zien welke vaardigheid je juist door die weerstand verder kunt ontwikkelen.", "explanationNl": "De auteurs zien in de sportvoorbeelden van de stoïcijnen een oefenplaats voor moeilijkheden buiten het stadion. Een tegenstander die sneller is of iets beter ziet, brengt je eigen beperkingen aan het licht. Je kunt je beklagen, een makkelijkere wedstrijd zoeken of onderzoeken wat er te leren valt. Volgens de auteurs zoeken goede sporters zulke beproevingen juist op. Een zware wedstrijd laat zien hoe ver ze zijn en geeft tegelijk aanwijzingen voor wat ze verder kunnen ontwikkelen.", "reflectionNl": "Waar zou iemand die beter is dan jij je nu het snelst iets kunnen leren?", "exerciseNl": "Vraag die persoon om één concreet punt waarop je je kunt verbeteren.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "09-23": {"dateKey": "09-23", "day": 23, "month": 9, "sourceTitle": "THE MOST SECURE FORTRESS", "thinker": "Marcus Aurelius", "thoughtNl": "Herhaal de reactie die je onder druk wilt kunnen kiezen, totdat die je makkelijker afgaat op moeilijke momenten.", "explanationNl": "De auteurs halen Bruce Lee aan om te laten zien wat herhaling kan doen. Een beweging die vaak en met aandacht is geoefend, is onder druk beschikbaar zonder dat je iedere stap hoeft te bedenken. Volgens de auteurs geldt dat ook voor hoe je met boosheid of roddel omgaat. Als je in gewone situaties herhaaldelijk oefent om er niet in mee te gaan, wordt die reactie makkelijker bereikbaar wanneer iemand je onverwacht raakt of verleidt.", "reflectionNl": "Welke reactie zou je vanzelfsprekender willen maken wanneer iemand je irriteert of bij geroddel betrekt?", "exerciseNl": "Oefen vandaag één korte zin waarmee je dat gesprek rustig kunt verleggen.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "09-24": {"dateKey": "09-24", "day": 24, "month": 9, "sourceTitle": "IT COULD HAPPEN TO YOU", "thinker": "Seneca", "thoughtNl": "Wanneer je iemand helpt bij tegenslag, bedenk dan dat je ooit zelf diezelfde hulp nodig kunt hebben.", "explanationNl": "Na een brand in Rome stuurde Lyon geld. Toen Lyon het jaar daarop zelf door brand werd getroffen, stuurde Nero een even groot bedrag terug. De auteurs zien in Seneca's beschrijving hoe snel rollen kunnen wisselen. De helper van vandaag kan morgen hulp nodig hebben. Ze betrekken dat ook op Seneca zelf. Toen Nero hem later veroordeelde, zag hij daarin een mogelijkheid waarop hij zich door zijn eerdere studie al had voorbereid.", "reflectionNl": "Welke moeilijkheid die je bij een ander ziet, zou jou onder andere omstandigheden ook kunnen treffen?", "exerciseNl": "Bedenk wie jij om hulp zou vragen als je in die situatie belandde.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "09-25": {"dateKey": "09-25", "day": 25, "month": 9, "sourceTitle": "THE VULNERABILITY OF DEPENDENCE", "thinker": "Seneca", "thoughtNl": "Probeer af en toe zonder een vertrouwd gemak te leven en merk hoeveel vrijheid je dan nog hebt.", "explanationNl": "De auteurs noemen gewoonten en verlangens die je dag kunnen gaan bepalen, zoals koffie, comfort of iemands goedkeuring. Als je gemoedsrust daarvan afhangt, maakt een plotselinge verandering je kwetsbaar. Epictetus verbindt vrijheid aan waar je zeggenschap over hebt. De auteurs stellen daarom voor afhankelijkheden vroeg en op kleine schaal te beproeven. Wie een tijdje zonder iets vertrouwds kan, ontdekt hoe zwaar het werkelijk weegt en hoe hij kan reageren als het ongevraagd wegvalt.", "reflectionNl": "Bij welke gewoonte merk je dat een kleine verstoring meteen veel van je humeur bepaalt?", "exerciseNl": "Stel één onschuldig gemak vandaag kort uit en observeer wat je er ondertussen bij voelt.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "09-26": {"dateKey": "09-26", "day": 26, "month": 9, "sourceTitle": "WHAT TIME OFF IS FOR", "thinker": "Seneca", "thoughtNl": "Gun jezelf rust van je werk en blijf in je vrije tijd nieuwsgierig naar wat je kunt leren.", "explanationNl": "De auteurs gunnen je vakantie en stellen voor die tijd aandachtig door te brengen. Lezen, observeren en nadenken kunnen goed samengaan met uitrusten. Ze trekken dat door naar pensioen: zodra werk minder tijd opeist, ontstaat ruimte om te onderzoeken wat je werkelijk wilt doen. Dagen vullen met televisie of reizen die vooral om het afvinken draaien, benut volgens hen die vrijheid maar beperkt. Wat je met je aandacht doet, bepaalt mede wat vrije tijd je brengt.", "reflectionNl": "Wat zou je op een vrije middag uit nieuwsgierigheid willen doen als het nergens toe hoefde te leiden?", "exerciseNl": "Maak vandaag kort ruimte voor die activiteit zonder er een prestatiedoel aan te hangen.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "09-27": {"dateKey": "09-27", "day": 27, "month": 9, "sourceTitle": "WHAT WILL PROSPERITY REVEAL?", "thinker": "Seneca", "thoughtNl": "Voorspoed kan bestaande gewoonten uitvergroten, dus werk aan de manier waarop je omgaat met wat je straks hebt.", "explanationNl": "De auteurs vergelijken voorspoed met geld of macht die zichtbaar maken welke trekken iemand al heeft. Wie gewend is te piekeren, houdt die neiging waarschijnlijk wanneer de omstandigheden verbeteren. Meer bezittingen of status kunnen zelfs nieuwe redenen geven om iets te vrezen. Volgens de auteurs is het daarom zinvoller te werken aan het karakter waarmee je voorspoed kunt dragen. Alledaagse gedachten en handelingen bieden kansen om dat karakter en het bijbehorende vertrouwen op te bouwen.", "reflectionNl": "Welke gewoonte zou bij meer succes of verantwoordelijkheid een groter probleem voor je kunnen worden?", "exerciseNl": "Kies één handeling vandaag waarmee je die gewoonte op kleine schaal kunt bijsturen.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "09-28": {"dateKey": "09-28", "day": 28, "month": 9, "sourceTitle": "YOU HOLD THE TRUMP CARD", "thinker": "Epictetus", "thoughtNl": "Je kunt niet over elke uitkomst beslissen, maar je hebt wel invloed op de betekenis die je eraan geeft.", "explanationNl": "Dezelfde dag kan er ontmoedigend uitzien als je let op het weer, andermans besluiten of een project dat al uit handen is. De auteurs verleggen de aandacht naar het oordeel dat je over zulke gebeurtenissen vormt. Daar heb je zelf invloed op, net als op je antwoord erop. Ze vinden dit een eerlijkere vorm van zeggenschap dan macht over anderen. Zij hoeven jou evenmin te besturen om hun eigen reactie te kunnen bepalen.", "reflectionNl": "Welke gebeurtenis van vandaag heb je meteen een betekenis gegeven waar je ook anders naar kunt kijken?", "exerciseNl": "Schrijf een tweede mogelijke interpretatie op en kies welke reactie bij de feiten past.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "09-29": {"dateKey": "09-29", "day": 29, "month": 9, "sourceTitle": "YOUR ACTUAL NEEDS ARE SMALL", "thinker": "Seneca", "thoughtNl": "Denk terug aan wat vroeger genoeg was en gebruik die ervaring om je huidige zorgen in verhouding te zien.", "explanationNl": "De auteurs vragen terug te denken aan een eerste salaris of een eenvoudig appartement dat toen als vooruitgang voelde. Zodra omstandigheden verbeteren, schuift de maatstaf op en lijkt hetzelfde comfort onmisbaar. Daardoor vergeet je gemakkelijk hoeveel je eerder met minder kon. De auteurs herinneren ook aan generaties die tijdelijk met rantsoenen leefden. Hun punt is dat herinneringen aan eenvoud kunnen helpen onderscheiden wat je werkelijk nodig hebt en welke onzekerheid vooral voortkomt uit wennen aan meer.", "reflectionNl": "Wat voelt nu onmisbaar terwijl je vroeger zonder leefde en tevreden kon zijn?", "exerciseNl": "Maak voor één zorg twee korte lijstjes met wat je nodig hebt en wat alleen prettig zou zijn.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "09-30": {"dateKey": "09-30", "day": 30, "month": 9, "sourceTitle": "YOU CAN’T TOUCH ME", "thinker": "Zeno van Citium", "thoughtNl": "Onrecht kan je omstandigheden bepalen, terwijl je nog ruimte kunt zoeken om je eigen oordeel te vormen.", "explanationNl": "De auteurs lezen Zeno's woorden als een uitspraak over de geest wanneer het lichaam kwetsbaar is. Filosofie, die hij onder Stilpo oefende, helpt volgens hen om je oordeel te bewaren onder dwang. Ze noemen de onterecht veroordeelde bokser Rubin Carter. Hij zat jarenlang fysiek vast en weigerde zijn denken door de gevangenis te laten bepalen. Het voorbeeld maakt duidelijk welke innerlijke ruimte zij bedoelen, ook bij tegenslag die veel kleiner is dan gevangenschap.", "reflectionNl": "Welke lastige omstandigheid krijgt in je gedachten meer zeggenschap dan in je handelen nodig is?", "exerciseNl": "Kies één kleine beslissing die je binnen die omstandigheid nog zelf kunt nemen.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "10-01": {"dateKey": "10-01", "day": 1, "month": 10, "sourceTitle": "LET VIRTUE SHINE BRIGHT", "thinker": "Marcus Aurelius", "thoughtNl": "Ook als je pas laat begint, kun je vanaf vandaag eerlijkheid, rechtvaardigheid en zelfbeheersing in de praktijk brengen.", "explanationNl": "De auteurs verbinden Marcus' beeld van een lamp met wat Seneca, in navolging van Heraclitus, schrijft over ons oplichten en uitdoven. Ze zien de rede als het licht waardoor de mens deugdzaam kan handelen. Een lamp kan voor het eerst aangaan of na lang donker opnieuw worden aangestoken. Ook als de tijd kort is, blijft er licht zolang er brandstof is. Daarom is waar je vandaag staat voor hen een geschikte plek om te beginnen.", "reflectionNl": "Welke goede gewoonte heb je uitgesteld omdat je vindt dat je er veel eerder mee had moeten beginnen?", "exerciseNl": "Geef die gewoonte vandaag één concrete kans in een alledaagse beslissing.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "10-02": {"dateKey": "10-02", "day": 2, "month": 10, "sourceTitle": "THE MOST VALUABLE ASSET", "thinker": "Seneca", "thoughtNl": "Investeer ook in je karakter, want daarop kun je terugvallen wanneer geld, vrienden en status je weinig helpen.", "explanationNl": "Sommige mensen bouwen volgens de auteurs financiële reserves op. Anderen investeren in relaties of prestaties. Seneca wijst op een bezit dat anders werkt: je vermogen om wijs en goed te handelen. De auteurs illustreren dat met zijn verhouding tot Nero. Seneca bood zijn rijkdom aan om vrij te zijn en trok zich ondanks Nero's weigering terug. Toen het bevel kwam dat hij moest sterven, kon hij vooral putten uit de innerlijke houding die hij had opgebouwd.", "reflectionNl": "Welke eigenschap van jezelf zou je willen kunnen inzetten wanneer hulp en middelen schaars zijn?", "exerciseNl": "Oefen die eigenschap vandaag bij één klein besluit dat toch al op je wacht.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "10-03": {"dateKey": "10-03", "day": 3, "month": 10, "sourceTitle": "A MANTRA OF MUTUAL INTERDEPENDENCE", "thinker": "Marcus Aurelius", "thoughtNl": "Je werk, keuzes en omgeving zijn verweven met die van anderen, ook wanneer die samenhang nauwelijks opvalt.", "explanationNl": "De auteurs beginnen bij Anne Lamotts beeld van schrijvers die ieder aan een groter geheel bijdragen. Ook op een werkplek kunnen mensen vergeten dat hun inspanningen samenkomen. De auteurs trekken het verband breder, tot het fysieke verband tussen generaties en hun leefomgeving. Ze leggen uit hoe het besef van verbondenheid kan tegengaan dat je anderen alleen als middel of vermaak ziet, zoals bij de wreedheden van het Romeinse spektakel en de onderwerping van veroverde bevolkingen.", "reflectionNl": "Wiens bijdrage aan een resultaat dat jij dagelijks gebruikt zie je makkelijk over het hoofd?", "exerciseNl": "Noem voor één alledaags resultaat twee mensen of groepen van wie het mede afhankelijk is.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "10-04": {"dateKey": "10-04", "day": 4, "month": 10, "sourceTitle": "ALL FOR ONE, ONE FOR ALL", "thinker": "Marcus Aurelius", "thoughtNl": "Vraag bij een persoonlijk voordeel ook wat het betekent voor de mensen met wie je het grotere geheel deelt.", "explanationNl": "De auteurs lezen Marcus' vergelijking met een bijenkorf tegen de achtergrond van zijn idee van wereldburgerschap. Het eigen belang en dat van de gemeenschap vallen niet automatisch samen. Zo kan iemand financieel profiteren van een neergang die anderen schaadt. De auteurs vragen daarom of je het soort voordeel zou willen dat van andermans verlies afhankelijk is. In de stoïcijnse opvatting die ze schetsen, houden verstandige beslissingen rekening met wat het geheel goeddoet.", "reflectionNl": "Welk voordeel voor jou zou bij nader inzien een ander met de kosten kunnen laten zitten?", "exerciseNl": "Bekijk één aanstaande keuze vanuit het perspectief van iemand die de gevolgen ervan draagt.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "10-05": {"dateKey": "10-05", "day": 5, "month": 10, "sourceTitle": "WORDS CAN’T BE UNSAID", "thinker": "Zeno van Citium", "thoughtNl": "Sta stil bij wat je wilt zeggen, want uitgesproken woorden kun je achteraf niet meer ongedaan maken.", "explanationNl": "De schrijvers werken Zeno's vergelijking uit met het verschil tussen lichamelijk struikelen en woorden die je eenmaal hebt gezegd. Na een val kun je vaak weer opstaan. Een uitspraak blijft intussen deel van wat de ander heeft meegemaakt. Dat weegt volgens hen vooral bij woorden die hard of kwetsend zijn. Hun korte commentaar verlegt de aandacht daarmee naar het moment vóór je spreekt, wanneer je nog invloed hebt op wat de ander zal horen.", "reflectionNl": "Welke zin zou je in een gespannen gesprek het liefst even willen herlezen voordat je hem uitspreekt?", "exerciseNl": "Laat in zo'n gesprek één ademhaling voorbijgaan en kies dan de woorden waarmee je verder wilt.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "10-06": {"dateKey": "10-06", "day": 6, "month": 10, "sourceTitle": "LOOKING OUT FOR EACH OTHER", "thinker": "Seneca", "thoughtNl": "Oefen om mee te leven met andermans tegenslag en om hun succes ook te vieren wanneer jij zelf baalt.", "explanationNl": "De auteurs beschrijven hoe moeilijk het kan zijn om andermans succes te zien wanneer het bij jezelf tegenzit. Dan lijkt het al gauw alsof wat de ander wint ten koste gaat van wat er voor jou overblijft. Ze lezen bij Seneca dat medeleven en onzelfzuchtigheid te oefenen zijn. Je kunt jezelf aanleren om anderen actief aan te moedigen en geraakt te worden door hun tegenslag, ook wanneer je eigen belangen of jaloezie het lastig maken.", "reflectionNl": "Wiens succes vind je lastig te vieren omdat het raakt aan iets wat jij zelf wilt bereiken?", "exerciseNl": "Bedenk één oprecht compliment over een concrete prestatie en geef het als de gelegenheid zich voordoet.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "10-07": {"dateKey": "10-07", "day": 7, "month": 10, "sourceTitle": "A SELFISH REASON TO BE GOOD", "thinker": "Marcus Aurelius", "thoughtNl": "Bedenk voordat je iets oneerlijks doet hoe je je straks zult voelen als het eenmaal gebeurd is.", "explanationNl": "Wraak, bedrog of een leugen kunnen van tevoren opluchting of voordeel beloven. De auteurs wijzen op de lichamelijke onrust, angst om ontdekt te worden en spijt die er kort daarna op kunnen volgen. Ze stellen voor dat gevoel alvast voor te stellen, vlak voordat je de beslissing neemt. Wie op zo'n moment merkt wat een handeling met zijn zelfrespect zal doen, heeft volgens hen een direct merkbare reden om zich in te houden.", "reflectionNl": "Bij welke kleine leugen zou de opluchting korter duren dan de onrust die je erna verwacht?", "exerciseNl": "Vraag jezelf bij een verleidelijk excuus af hoe je je voelt als iemand later de waarheid ontdekt.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "10-08": {"dateKey": "10-08", "day": 8, "month": 10, "sourceTitle": "A HIGHER PLEASURE", "thinker": "Marcus Aurelius", "thoughtNl": "Geniet van kort plezier en geef ook aandacht aan eigenschappen waar je langer voldoening uit kunt halen.", "explanationNl": "De auteurs erkennen dat plezier werkelijk aangenaam is. Seks, een prestatie of applaus kunnen een sterke maar korte bevrediging geven, waarna je vaak opnieuw naar zo'n ervaring verlangt. Bij Marcus lezen ze een voorkeur voor wat langer meegaat en dichter binnen je eigen invloed ligt. Wijsheid, vriendelijkheid, nuchterheid en goed karakter zijn volgens hen eigenschappen waarin je kunt investeren. Hun waarde hangt minder af van een volgende prikkel of de reactie van een publiek.", "reflectionNl": "Wat gaf je deze week langer voldoening dan het moment zelf duurde?", "exerciseNl": "Herhaal vandaag één kleine vriendelijke of verstandige handeling waar je gisteren tevreden op terugkeek.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "10-09": {"dateKey": "10-09", "day": 9, "month": 10, "sourceTitle": "SET THE STANDARDS AND USE THEM", "thinker": "Epictetus", "thoughtNl": "Maak je waarden concreet door vlak voor een gewone handeling te vragen of die past bij wie je wilt zijn.", "explanationNl": "De auteurs merken op dat veel dagelijkse handelingen uit een onmiddellijke reactie voortkomen. Je kunt ook even stilstaan bij de vraag of je gedrag past bij wat je zelf belangrijk vindt. Zulke momenten liggen overal, bijvoorbeeld in de keuze van je vrienden, in wat je je kind uitlegt en in hoe je reageert als je boos wordt. Een goede bedoeling krijgt volgens de auteurs pas gewicht wanneer je haar aan de eerstvolgende concrete situatie verbindt.", "reflectionNl": "Bij welk moment vandaag wil je vooraf weten aan welke norm je jezelf houdt?", "exerciseNl": "Maak één zin af die begint met: als dat gebeurt, wil ik zo handelen.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "10-10": {"dateKey": "10-10", "day": 10, "month": 10, "sourceTitle": "REVERENCE AND JUSTICE", "thinker": "Marcus Aurelius", "thoughtNl": "Laat respect en rechtvaardigheid bepalen waar je vandaag in volhardt en welke neigingen je wilt weerstaan.", "explanationNl": "De auteurs halen het door Aulus Gellius overgeleverde advies van Epictetus aan om vol te houden en weerstand te bieden. Daar voegen ze de vraag aan toe welke waarden bepalen wat de moeite van het volhouden waard is. Bij Marcus Aurelius vinden ze het antwoord in eerbied en rechtvaardigheid. In de passage krijgt dat betekenis door te aanvaarden wat je is toebedeeld, vrijuit de waarheid te spreken en passend te handelen. Die waarden geven richting aan je inzet in het heden.", "reflectionNl": "Bij welk besluit kun je tegelijk respect tonen voor de situatie en eerlijk zijn over wat er nodig is?", "exerciseNl": "Formuleer voor één gesprek een eerlijke zin die ook rekening houdt met de ander.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "10-11": {"dateKey": "10-11", "day": 11, "month": 10, "sourceTitle": "HONESTY AS OUR DEFAULT", "thinker": "Marcus Aurelius", "thoughtNl": "Maak eerlijkheid zo gewoon dat mensen haar in je woorden en daden herkennen zonder dat je haar hoeft aan te kondigen.", "explanationNl": "Veel mensen leiden een zin in met de verzekering dat ze nu echt eerlijk of rechtuit zullen zijn. De auteurs vragen zich af welke verwachting dat schept over de rest van wat je zegt. Ze stellen voor een reputatie op te bouwen waarin mensen op je woorden kunnen rekenen zonder telkens een garantie nodig te hebben. Het gaat hun om een vaste manier van spreken en handelen, die ook je karakter vormt.", "reflectionNl": "Welke boodschap zou helderder worden als je meteen zei wat je bedoelt, zonder eerst je eerlijkheid te benadrukken?", "exerciseNl": "Schrap bij één bericht een aanloop waarin je verzekert dat je eerlijk bent en lees de rest rustig terug.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "10-12": {"dateKey": "10-12", "day": 12, "month": 10, "sourceTitle": "ALWAYS LOVE", "thinker": "Seneca", "thoughtNl": "Ook bij een stevig verschil van mening kun je proberen begrip, waardering of liefde in je reactie mee te nemen.", "explanationNl": "De auteurs halen een toespraak van Barbara Jordan aan waarin zij na een tijd van verdeeldheid pleitte voor publieke dienstbaarheid, verdraagzaamheid en liefde. Ze trekken die oproep door naar het persoonlijke leven. Volgens hen helpt haat zelden om een situatie te verbeteren. Begrip, medeleven of waardering kan wel iets bijdragen, zelfs wanneer je tegenover iemand staat. Die houding biedt bovendien ruimte voor een vriendelijker antwoord van de ander, zonder dat je daar vooraf op kunt rekenen.", "reflectionNl": "Bij wie zou een beetje begrip het gesprek kunnen verbeteren terwijl je het inhoudelijk oneens blijft?", "exerciseNl": "Noem in je volgende reactie eerst één zorg van die persoon die je begrijpt.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "10-13": {"dateKey": "10-13", "day": 13, "month": 10, "sourceTitle": "REVENGE IS A DISH BEST NOT SERVED", "thinker": "Marcus Aurelius en Seneca", "thoughtNl": "Laat het gedrag dat je bij een ander afkeurt geen voorbeeld worden voor hoe je zelf terugreageert.", "explanationNl": "De auteurs noemen iemand die promotie krijgt door met jouw werk te pronken. Wraak of zelf oneerlijk worden kan dan verleidelijk lijken. Volgens Marcus en Seneca geef je het gedrag daarmee juist meer voet aan de grond. Wie op grofheid met grofheid reageert, bevestigt voor de ander hoe normaal die omgangsvorm is. De auteurs zien een alternatief in het gedrag dat je zelf graag bij anderen zou zien, ook wanneer iemand je heeft teleurgesteld.", "reflectionNl": "Hoe kun je op onrecht reageren op een manier die je bij een ander ook zou respecteren?", "exerciseNl": "Schrijf één zakelijke zin waarmee je kunt benoemen wat er misging zonder de ander te beledigen.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "10-14": {"dateKey": "10-14", "day": 14, "month": 10, "sourceTitle": "DON’T GET MAD. HELP", "thinker": "Marcus Aurelius", "thoughtNl": "Maak bij ergernis eerst een beleefd verzoek dat de ander een eerlijke kans geeft iets te veranderen.", "explanationNl": "De auteurs stellen je voor naast een luidruchtige, onrustige passagier in een vliegtuig. Het kan verleidelijk zijn om in stilte steeds bozer te worden. Een beleefde vraag of het verzoek om een andere stoel zou concreet iets kunnen verbeteren, al voelt zo'n gesprek even ongemakkelijk. De auteurs gebruiken dit voorbeeld om te onderzoeken wie er in die situatie eigenlijk bijdraagt aan de onvriendelijkheid. Een ander krijgt door je ergernis alleen weinig informatie over wat je nodig hebt.", "reflectionNl": "Welk verzoek zou je kunnen doen voordat je aanneemt dat de ander expres geen rekening met je houdt?", "exerciseNl": "Formuleer dat verzoek met één concreet gedrag en vertel rustig welk effect het op je heeft.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "10-15": {"dateKey": "10-15", "day": 15, "month": 10, "sourceTitle": "GIVE PEOPLE THE BENEFIT OF THE DOUBT", "thinker": "Marcus Aurelius", "thoughtNl": "Geef iemand bij een eerste ergernis ruimte voor een vergissing voordat je beslist dat er kwade opzet was.", "explanationNl": "Als iemand per ongeluk op zijn poot trapt, kan een hond eerst schrikken of blaffen. Pas daarna merkt hij wie het was en hoe diegene reageert. De auteurs gebruiken dat beeld voor het verschil tussen de pijn van een eerste indruk en een oordeel over de bedoeling erachter. Het helpt om rekening te houden met onwetendheid, toeval of een eenmalige fout. Wie ruimhartig met aannames omgaat, hoeft minder snel op vermeende vijandigheid te reageren.", "reflectionNl": "Bij welk voorval heb je de bedoeling van de ander ingevuld voordat je wist wat er was gebeurd?", "exerciseNl": "Bedenk één geloofwaardige onschuldige verklaring of vraag diegene rechtstreeks hoe het ging.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "10-16": {"dateKey": "10-16", "day": 16, "month": 10, "sourceTitle": "SPREAD THE WORD", "thinker": "Seneca", "thoughtNl": "Als iemand om raad vraagt, deel dan wat je hebt geleerd en laat je gedrag het voorbeeld geven.", "explanationNl": "De auteurs schrijven dat stoïcisme geen geloof is waarvoor je anderen moet bekeren. Wat je hebt geleerd kan wel van nut zijn voor iemand die met een probleem zit of om raad vraagt. Je kunt dan een inzicht delen of hulp bieden. Je eigen handelen is daarbij vaak overtuigender dan een toespraak. De auteurs lezen bij Seneca dat de praktische voordelen van filosofie voor iedereen toegankelijk horen te zijn, ook buiten een vaste kring.", "reflectionNl": "Wie heeft je om raad gevraagd en zou meer hebben aan een klein voorbeeld dan aan een lange uitleg?", "exerciseNl": "Bied die persoon één concrete vorm van hulp aan die je zelf kunt waarmaken.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "10-17": {"dateKey": "10-17", "day": 17, "month": 10, "sourceTitle": "THE BENEFIT OF KINDNESS", "thinker": "Seneca", "thoughtNl": "Iedere ontmoeting biedt een kans om iemand vriendelijk te behandelen, ook als je weinig weet van diens dag.", "explanationNl": "De auteurs wijzen op twee lezingen van Seneca's gedachte over ontmoetingen. Ze geven je de gelegenheid vriendelijk te zijn en kunnen voor beide mensen iets opleveren. Door te vragen waar iemand vandaan komt of wat diegene nodig heeft, krijg je zicht op wat zijn gedrag mee bepaalt. Die mogelijkheid bestaat bij de eerste persoon die je ziet en bij iedere volgende. Of iemand je vriendelijkheid beantwoordt, is een beslissing die aan de ander blijft.", "reflectionNl": "Welke persoon kom je regelmatig tegen zonder ooit te vragen hoe het met diegene gaat?", "exerciseNl": "Maak bij de eerstvolgende ontmoeting ruimte voor één oprechte vraag of klein vriendelijk gebaar.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "10-18": {"dateKey": "10-18", "day": 18, "month": 10, "sourceTitle": "FRENEMIES", "thinker": "Marcus Aurelius", "thoughtNl": "Onderzoek ook wanneer jij een vriend voor de vorm steunde, terwijl diegene juist op je betrokkenheid rekende.", "explanationNl": "Een waarschuwing voor onbetrouwbare vrienden kun je volgens de auteurs ook op jezelf betrekken. Misschien deed je aardig omdat het iets opleverde en sprak je in ander gezelschap heel anders over die vriend. Misschien bleef je betrokken zolang alles goed ging en verdween je toen iemand hulp nodig had. De auteurs zien in het herkennen van zulke momenten een stoïcijnse oefening. Het geeft je iets concreets om te onderzoeken wanneer je op het punt staat een ander ontrouw te noemen.", "reflectionNl": "Bij wie klopte je gedrag achteraf niet met de betrokkenheid die je die persoon had laten zien?", "exerciseNl": "Kies één vriendschap waarin je vandaag kunt doen wat je eerder beloofde.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "10-19": {"dateKey": "10-19", "day": 19, "month": 10, "sourceTitle": "GOOD HABITS DRIVE OUT BAD HABITS", "thinker": "Epictetus", "thoughtNl": "Onderbreek een gewoonte waar je vanaf wilt door op hetzelfde moment doelbewust een andere handeling te oefenen.", "explanationNl": "De auteurs vergelijken het doorbreken van een slechte gewoonte met het afleiden van een blaffende hond. Schreeuwen tegen een blaffende hond of achter een wegrennende hond aan gaan kan het patroon juist versterken. Een andere opdracht geeft iets concreets om te doen. Dat werkt volgens de auteurs ook bij jezelf: een wandeling kan uitstelgedrag onderbreken en een vriendelijke opmerking kan een nare reactie bijsturen. Door die tegengestelde reactie te oefenen, vergroot je de kans dat je haar de volgende keer op tijd inzet.", "reflectionNl": "Welke handeling kun je in de plaats zetten van een gewoonte die steeds op hetzelfde moment opduikt?", "exerciseNl": "Spreek voor één herkenbare aanleiding een simpele vervangende handeling met jezelf af.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "10-20": {"dateKey": "10-20", "day": 20, "month": 10, "sourceTitle": "MARKS OF THE GOOD LIFE", "thinker": "Marcus Aurelius", "thoughtNl": "Je geeft betekenis aan je leven met wat je in de praktijk doet wanneer een keuze voor je ligt.", "explanationNl": "De auteurs beginnen met de vraag waarvoor je leeft. Via Viktor Frankl keren ze die vraag om: het leven legt je situaties voor en jouw handelen vormt daarop het antwoord. Boeken, reizen of wijze mensen kunnen je bij het denken helpen, maar kunnen dat antwoord niet voor je leven. In de lezing die de auteurs aan Marcus verbinden, laat je door rechtvaardigheid, zelfbeheersing, moed en een vrije keuze in praktijk te brengen zien wat je leven richting geeft.", "reflectionNl": "Welke keuze vandaag laat het duidelijkst zien welke waarde jij werkelijk belangrijk vindt?", "exerciseNl": "Neem één gewone beslissing bewust op basis van die waarde.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "10-21": {"dateKey": "10-21", "day": 21, "month": 10, "sourceTitle": "HEROES, HERE AND NOW", "thinker": "Marcus Aurelius", "thoughtNl": "Besteed je aandacht aan goed handelen zolang je leeft, want je kunt later zelf geen roem meer beleven.", "explanationNl": "Alexandrië draagt nog steeds de naam van Alexander de Grote. De auteurs vragen wat Alexander zelf aan die bekendheid heeft. Hij kan haar immers niet meemaken. Ze zetten zijn oorlogen, woede en grenzeloze ambitie naast zijn roem en vragen of de prijs die hij ervoor betaalde bewondering verdient. Dat maakt hun pleidooi concreet: richt je energie op een goed besluit in het heden, wanneer je handelen echt verschil kan maken voor jezelf en anderen.", "reflectionNl": "Wat zou je vandaag anders doen als de waardering van mensen die je nooit zult ontmoeten geen rol speelde?", "exerciseNl": "Doe één nuttig ding zonder bekend te maken dat jij het hebt gedaan.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "10-22": {"dateKey": "10-22", "day": 22, "month": 10, "sourceTitle": "IT’S EASY TO GET BETTER. BUT BETTER AT WHAT?", "thinker": "Marcus Aurelius", "thoughtNl": "Vraag je bij zelfverbetering ook af of je meer aandacht, tijd of zorg leert geven aan de mensen om je heen.", "explanationNl": "De auteurs waarderen het streven om beter te worden en vragen tegelijk wat achter een ambitie zit. Een marathon kan een serieuze uitdaging zijn of een manier om problemen thuis te ontlopen. Sportprestaties, een goed uiterlijk of extra talen kunnen waarde hebben. Toch zeggen ze op zichzelf weinig over hoe je als partner, ouder of kind met anderen omgaat. Voor de auteurs verdient die kant van je ontwikkeling voorrang wanneer verschillende doelen om dezelfde tijd en aandacht vragen.", "reflectionNl": "Welk verbeterdoel neemt tijd in die je ook zou willen besteden aan iemand die belangrijk voor je is?", "exerciseNl": "Maak vandaag naast je eigen doel concreet tijd vrij voor één afspraak of gesprek dat die relatie helpt.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "10-23": {"dateKey": "10-23", "day": 23, "month": 10, "sourceTitle": "SHOW THE QUALITIES YOU WERE MADE FOR", "thinker": "Marcus Aurelius", "thoughtNl": "Geef vandaag aandacht aan eigenschappen die je kunt oefenen, zoals eerlijkheid, vriendelijkheid en geduld onder moeilijke omstandigheden.", "explanationNl": "Mensen vergelijken zichzelf vaak op eigenschappen die zij bij hun geboorte of door omstandigheden hebben meegekregen. De auteurs noemen lengte, intelligentie en het land waarin je opgroeit. Zulke vergelijkingen kunnen je afleiden van kwaliteiten waarop je wel invloed hebt. Je kunt bijvoorbeeld eerlijk antwoorden, zuinig omgaan met wat je hebt of weigeren mee te doen aan geroddel. De auteurs vinden eigenschappen die je door oefening ontwikkelt juist waardevol omdat ze iets zeggen over wat je zelf hebt gedaan.", "reflectionNl": "Op welke aangeboren eigenschap van jezelf blijf je letten terwijl er een trainbare kwaliteit meer verschil zou maken?", "exerciseNl": "Kies één gedrag dat die trainbare kwaliteit laat zien en pas het toe in een gewone situatie.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "10-24": {"dateKey": "10-24", "day": 24, "month": 10, "sourceTitle": "THE FOUNTAIN OF GOODNESS", "thinker": "Marcus Aurelius", "thoughtNl": "Goed nieuws en mooi weer kunnen je toevallen, terwijl je met je gedachten en handelingen zelf iets goeds kunt bijdragen.", "explanationNl": "De auteurs onderscheiden twee manieren om naar een goede dag uit te kijken. Je kunt hopen dat het weer meewerkt of dat je prettig nieuws ontvangt. Bij Marcus lezen zij ook de mogelijkheid om zelf het goede naar boven te halen. Dat vraagt aandacht voor wat je denkt en vervolgens iets doen dat uit die houding voortkomt. Op die manier krijgt het goede een concrete plek in je dag, onafhankelijk van de gebeurtenissen waarop je wacht.", "reflectionNl": "Waar hoop je vandaag op een meevaller, terwijl je zelf ook iets goeds aan de dag zou kunnen toevoegen?", "exerciseNl": "Kies één haalbare handeling die vandaag iets verbetert voor jezelf of iemand in je omgeving.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "10-25": {"dateKey": "10-25", "day": 25, "month": 10, "sourceTitle": "TWO TASKS", "thinker": "Epictetus", "thoughtNl": "Gebruik je tijd om zorgvuldig te handelen en werk te doen waar je je werkelijk voor wilt inzetten.", "explanationNl": "De auteurs noemen twee hoofdtaken: een goed mens zijn en je toeleggen op bezigheden waar je om geeft. Om daar ruimte voor te maken, stellen ze voor je tijd te beschermen tegen afleiding, ontwrichtende emoties en verwachtingen van buitenaf. Ze vragen welk werk jij zelf kunt doen en wat de beste besteding van je beperkte tijd is. Ook in kleine keuzes kun je die richting oefenen, bijvoorbeeld door anderen te behandelen zoals je zelf behandeld wilt worden.", "reflectionNl": "Wat heeft vandaag je aandacht nodig omdat juist jij er iets goeds mee kunt doen?", "exerciseNl": "Reserveer een kort blok voor die bezigheid en leg één voorspelbare afleiding alvast weg.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "10-26": {"dateKey": "10-26", "day": 26, "month": 10, "sourceTitle": "THREE PARTS, ONE AIM", "thinker": "Seneca", "thoughtNl": "Breng wat je leert over denken, de natuur en goed handelen samen in een redelijke keuze die vandaag voor je ligt.", "explanationNl": "De auteurs brengen drie onderdelen van filosofie samen: het morele, het natuurlijke en het rationele. Elk richt de aandacht op een ander terrein, van wat goed handelen vraagt tot hoe de wereld en ons denken werken. Volgens de auteurs dienen die onderdelen bij Seneca één doel. Ze helpen je een goed leven te leiden waarin je je door de rede laat sturen. Hun korte uitleg legt nadruk op de toepassing in het heden, bij beslissingen die je nu neemt.", "reflectionNl": "Bij welke beslissing kun je vandaag de feiten, je redenering en de gevolgen voor anderen tegelijk meewegen?", "exerciseNl": "Noteer voor die beslissing één feit, één aanname die je wilt toetsen en één waarde waaraan je trouw wilt blijven.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "10-27": {"dateKey": "10-27", "day": 27, "month": 10, "sourceTitle": "WE REAP WHAT WE SOW", "thinker": "Seneca", "thoughtNl": "Let op wat je anderen voordoet of leert, want hun latere gedrag kan mede uit jouw voorbeeld voortkomen.", "explanationNl": "De auteurs wijzen op de ironie dat Seneca over terugkerende gevolgen schreef en tegelijk de jonge Nero onderwees. Ze erkennen dat hij een gunstige invloed kan hebben gehad en noemen ook tijdgenoten die zijn nabijheid tot Nero vreemd vonden. Uiteindelijk kwam zijn dood voort uit een bevel van zijn vroegere leerling. Dat maakt de vraag naar je eigen medewerking concreet. Als je mensen wegwijs maakt in oneerlijk gedrag, kunnen zij dezelfde handelwijze later ook op jou toepassen.", "reflectionNl": "Welk gedrag zouden collega's, vrienden of kinderen van je kunnen overnemen terwijl je het bij hen zou afkeuren?", "exerciseNl": "Geef bij de eerstvolgende gelegenheid één klein voorbeeld van hoe je die situatie wel zorgvuldig wilt aanpakken.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "10-28": {"dateKey": "10-28", "day": 28, "month": 10, "sourceTitle": "WE WERE MADE FOR EACH OTHER", "thinker": "Marcus Aurelius", "thoughtNl": "Zorg voor anderen wanneer zij je nodig hebben en laat hen ook voor jou zorgen wanneer jij hulp nodig hebt.", "explanationNl": "De auteurs lezen bij Marcus een vergelijking tussen zwaartekracht en de sterke onderlinge afhankelijkheid van mensen. Ze begrijpen dat nadenken over menselijk gedrag ook afstand kan scheppen. Wie vooral elkaars fouten ziet of zelf een zware tijd doormaakt, kan zich gaan afzonderen. Toch blijft de mens in hun lezing een sociaal wezen. Dat vraagt zowel om voor anderen klaar te staan als om hun zorg te aanvaarden wanneer je die zelf nodig hebt.", "reflectionNl": "Bij wie houd je hulp op afstand terwijl diegene je oprecht iets zou willen bieden?", "exerciseNl": "Accepteer vandaag één concreet aanbod of vraag iemand om hulp met iets kleins.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "10-29": {"dateKey": "10-29", "day": 29, "month": 10, "sourceTitle": "CHARACTER IS FATE", "thinker": "Seneca", "thoughtNl": "Beoordeel mensen ook op hun karakter, want een indrukwekkend verleden kan veel aan geluk en kansen te danken hebben.", "explanationNl": "Werkgevers bekijken volgens de auteurs vaak eerdere banen en opleidingen om toekomstig succes in te schatten. Die aanwijzingen kunnen iets zeggen, maar ook het gevolg zijn van geluk of de mogelijkheden van iemands ouders. Een jongere kandidaat heeft bovendien minder tijd gehad om een reputatie op te bouwen. De auteurs halen Heraclitus aan om het belang van karakter te benadrukken. Dat telt volgens hen op lange termijn bij werk, vriendschap en de ontwikkeling van je eigen leven.", "reflectionNl": "Welke indruk van iemand zou veranderen als je diens gedrag zwaarder liet wegen dan opleiding, status of eerdere successen?", "exerciseNl": "Noem bij een beoordeling één concreet voorbeeld van betrouwbaarheid of eerlijkheid dat je zelf hebt gezien.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "10-30": {"dateKey": "10-30", "day": 30, "month": 10, "sourceTitle": "WHO GETS THE LION’S SHARE?", "thinker": "Seneca", "thoughtNl": "Reserveer bewust tijd om na te denken over hoe je wilt leven voordat je agenda zich met andere zaken vult.", "explanationNl": "Seneca vertelt over Alexander, die zelf wilde bepalen hoeveel grond hij de door hem bedreigde volken liet houden. De auteurs gebruiken dat om te vragen wie jouw beschikbare tijd verdeelt. Vaak krijgen werk, vergaderingen en vermaak vaste uren, terwijl nadenken en lezen moeten passen in wat aan het einde van de dag overblijft. Wie zich werkelijk wil ontwikkelen, kan die volgorde omkeren. Geef filosofie vooraf een plaats en bepaal daarna welke andere bezigheden in de resterende tijd passen.", "reflectionNl": "Welk vast moment zou je aan nadenken of lezen willen geven als je het even belangrijk behandelde als een werkafspraak?", "exerciseNl": "Zet voor de komende week één kort lees- of denkmoment in je agenda.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "10-31": {"dateKey": "10-31", "day": 31, "month": 10, "sourceTitle": "YOU WERE BORN GOOD", "thinker": "Musonius Rufus", "thoughtNl": "Samenwerken, elkaar helpen en jezelf leren sturen zijn volgens de stoïcijnen menselijke vermogens die je opnieuw kunt oefenen.", "explanationNl": "De auteurs stellen tegenover het idee van erfzonde dat mensen volgens de stoïcijnen aanleg hebben om elkaar te helpen en zich deugdzaam te gedragen. Ze wijzen op het belang van samenwerking voor ons voortbestaan en lezen bij Musonius Rufus dat iedereen die aanleg heeft. Een omgeving kan intussen andere gewoonten en ideeën belonen, soms ten bate van eigenbelang. Filosofie helpt volgens de auteurs zulke invloeden te onderzoeken en opnieuw toegang te krijgen tot wat je aan anderen kunt bijdragen.", "reflectionNl": "Welke aangeleerde gewoonte maakt het voor jou moeilijker om iemand te helpen wanneer je daar wel de ruimte voor hebt?", "exerciseNl": "Kies een kleine vorm van hulp die aansluit bij wat je zelf vanzelfsprekend goed vindt.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "11-01": {"dateKey": "11-01", "day": 1, "month": 11, "sourceTitle": "ACCEPTING WHAT IS", "thinker": "Epictetus", "thoughtNl": "Je kunt gisteren niet herschrijven, maar je kunt vandaag anders kijken naar wat er is gebeurd.", "explanationNl": "Als een gebeurtenis voorbij is, kun je alleen nog veranderen hoe je ertegen aankijkt. Holiday en Hanselman beschrijven aanvaarding als een vaardigheid: ophouden met je tegen elke tegenvaller te verzetten. De meest geoefende stoïcijnen gaan verder en proberen blij te zijn met wat hun overkomt. De auteurs verbinden dat met Nietzsches amor fati, liefde voor het lot. Aanvaarding vermindert teleurstelling. Wie ook dankbaarheid kan voelen voor het onverwachte, maakt volgens hen ruimte voor vreugde.", "reflectionNl": "Welke gebeurtenis blijf je in gedachten herschrijven, en hoe zou je haar anders kunnen bekijken?", "exerciseNl": "Schrijf bij één tegenvaller één mogelijkheid op die je vóór die gebeurtenis niet had gezien.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "11-02": {"dateKey": "11-02", "day": 2, "month": 11, "sourceTitle": "BINDING OUR WISHES TO WHAT WILL BE", "thinker": "Epictetus", "thoughtNl": "Bereid je zo goed mogelijk voor en houd er rekening mee dat de uitkomst nooit helemaal aan jou is.", "explanationNl": "Vlak voor de invasie in Normandië schreef Eisenhower aan zijn vrouw dat iedereen had gedaan wat mogelijk was en dat de uitkomst uit hun handen lag. Hij had ook een verklaring klaar voor het geval de operatie zou mislukken. Holiday en Hanselman halen dat voorbeeld aan omdat zelfs iemand met zoveel manschappen en zo'n grondige voorbereiding afhankelijk bleef van omstandigheden buiten zijn macht. Je kunt je inzet bepalen en rekening houden met verschillende uitkomsten. Welke uitkomst zich voordoet, blijft onzeker.", "reflectionNl": "Bij welk plan doe je alsof een goede voorbereiding de uitkomst garandeert?", "exerciseNl": "Schrijf voor een naderende afspraak één stap op die je kunt zetten als het anders loopt.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "11-03": {"dateKey": "11-03", "day": 3, "month": 11, "sourceTitle": "FOLLOWING THE DOCTOR’S ORDERS", "thinker": "Marcus Aurelius", "thoughtNl": "Behandel een onverwacht ongemak eens als iets wat je kan helpen oefenen in een vaardigheid die je nodig hebt.", "explanationNl": "Een nare smaak accepteer je gemakkelijk als je arts zegt dat een medicijn helpt. Holiday en Hanselman gebruiken zelfs het absurde beeld van ondersteboven slapen om te laten zien hoe ver we daarin kunnen gaan. Loopt een plan onverwacht anders, dan verzetten we ons vaak meteen. Marcus nodigt je uit dezelfde gebeurtenis tijdelijk door de ogen van een arts te bekijken: stel dat dit ongemak onderdeel was van een behandeling, wat zou het je dan kunnen leren?", "reflectionNl": "Welke recente ergernis kun je gebruiken om iets te oefenen waar je beter in wilt worden?", "exerciseNl": "Benoem tijdens een wachttijd één eigenschap die je op dat moment kunt oefenen.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "11-04": {"dateKey": "11-04", "day": 4, "month": 11, "sourceTitle": "NOT GOOD, NOR BAD", "thinker": "Marcus Aurelius", "thoughtNl": "Geef verandering even de tijd voordat je haar beoordeelt, zodat je kunt zien wat je ermee kunt doen.", "explanationNl": "Wie zegt dat verandering goed is, probeert volgens de auteurs vaak iemand gerust te stellen, inclusief zichzelf. Onze eerste reactie op iets nieuws is immers vaak argwaan. Holiday en Hanselman lezen Marcus als een uitnodiging om zowel verandering als stilstand eerst zonder waardeoordeel te bekijken. Een gebeurtenis en het oordeel dat jij erover velt zijn twee verschillende dingen. Als je je verzet even laat zakken, kun je beter onderzoeken hoe je met de nieuwe situatie om wilt gaan.", "reflectionNl": "Welke recente verandering heb je beoordeeld voordat je wist wat zij concreet voor je betekende?", "exerciseNl": "Beschrijf één verandering in feitelijke woorden en noteer wat je er vandaag mee kunt.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "11-05": {"dateKey": "11-05", "day": 5, "month": 11, "sourceTitle": "A HIGHER POWER", "thinker": "Chrysippus", "thoughtNl": "Hulp toelaten wordt makkelijker zodra je erkent dat jij maar een deel van de situatie kunt sturen.", "explanationNl": "Holiday en Hanselman bespreken de tweede stap van een twaalfstappenprogramma, waarin deelnemers erkennen dat iets groters dan zijzelf kan helpen. Die formulering kan aanvankelijk op religieuze bezwaren stuiten. De auteurs lezen de stap vooral als oefenen in loslaten, zoals ook in latere stappen terugkomt. Zelfs zonder een godsdienstige overtuiging kun je erkennen dat jij de wereld niet bestuurt. Volgens hen wordt het leven lichter wanneer je de behoefte aan volledige controle opgeeft.", "reflectionNl": "In welke situatie probeer je de uitkomst alleen te bepalen terwijl anderen of omstandigheden ook invloed hebben?", "exerciseNl": "Vraag iemand om hulp bij één concrete stap die je steeds alleen probeert op te lossen.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "11-06": {"dateKey": "11-06", "day": 6, "month": 11, "sourceTitle": "SOMEONE ELSE IS SPINNING THE THREAD", "thinker": "Seneca", "thoughtNl": "Voorspoed en tegenslag kunnen allebei onverwacht omslaan, dus beschouw je huidige situatie als tijdelijk.", "explanationNl": "Schrijver Cormac McCarthy verbleef in een motel toen hem onverwacht een grote beurs werd toegekend. Holiday en Hanselman verbinden dat geluk met Clotho, de Griekse schikgodin die de levensdraad spint. In dat oude wereldbeeld lagen zowel grote kansen als rampspoed gedeeltelijk buiten menselijke macht. De auteurs gebruiken het beeld om te laten zien hoe snel omstandigheden kunnen keren. Moeilijkheden zijn geen betrouwbare voorspelling van de rest van je leven, en hetzelfde geldt voor succes.", "reflectionNl": "Welke huidige situatie behandel je alsof die nooit meer kan veranderen?", "exerciseNl": "Noteer één eerder moment waarop je situatie onverwacht ten goede of ten kwade keerde.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "11-07": {"dateKey": "11-07", "day": 7, "month": 11, "sourceTitle": "HOW TO BE POWERFUL", "thinker": "Epictetus", "thoughtNl": "Wie minder nodig heeft om tevreden te zijn, geeft omstandigheden en andere mensen minder macht over zichzelf.", "explanationNl": "In Steven Pressfields roman antwoordt een filosoof op Alexanders veroveringen dat hij zijn eigen behoefte om te veroveren heeft overwonnen. Holiday en Hanselman vergelijken die fictieve scène met de ontmoeting tussen Alexander en Diogenes. De filosoof kon volgens hen onafhankelijker optreden doordat hij weinig verlangde naar wat Alexander bezat of vertegenwoordigde. De auteurs plaatsen die zelfbeheersing boven macht over anderen. Je kunt volgens hen meer bereiken door je eigen verlangens te onderzoeken dan door je gezag naar buiten uit te breiden.", "reflectionNl": "Welk verlangen geeft iemand anders op dit moment veel invloed op jouw stemming?", "exerciseNl": "Stel één onnodig verzoek om bevestiging een dag uit en kijk hoe dat voelt.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "11-08": {"dateKey": "11-08", "day": 8, "month": 11, "sourceTitle": "ACTORS IN A PLAY", "thinker": "Epictetus", "thoughtNl": "Je kiest je uitgangspositie maar deels. Hoe je de rol vervult die je krijgt, kun je wel oefenen.", "explanationNl": "Marcus Aurelius werd voorbereid op een keizerschap dat hij niet had nagestreefd. Epictetus leefde een tijd als slaaf. Holiday en Hanselman benadrukken dat beiden veel deden met de heel verschillende omstandigheden die hun toevielen. Een kans kan als last voelen en een kleine rol kan later groter worden. De auteurs zien aanvaarding daarom als beginpunt: begrijp wat je positie op dit moment vraagt en geef daar zo goed mogelijk invulling aan, met ruimte voor ambitie.", "reflectionNl": "Welke rol die je niet zelf hebt gekozen kun je vandaag beter vervullen?", "exerciseNl": "Kies één concrete verantwoordelijkheid binnen die rol en geef die vandaag tien minuten aandacht.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "11-09": {"dateKey": "11-09", "day": 9, "month": 11, "sourceTitle": "ALL IS FLUID", "thinker": "Marcus Aurelius", "thoughtNl": "Zelfs wat je al jaren kent, verandert stukje bij beetje, terwijl jij het bij dezelfde naam blijft noemen.", "explanationNl": "Holiday en Hanselman beginnen bij het schip van Theseus. Door onderhoud werd elke plank vervangen, terwijl men het als hetzelfde schip bleef zien. Een herbouwd heiligdom en de geleidelijk wisselende Amerikaanse Senaat roepen een soortgelijke vraag op. Volgens de auteurs zegt onze naam voor iets vooral hoe we er op één moment naar kijken. Ons lichaam en onze herinneringen veranderen eveneens geleidelijk. Dat geldt ook voor de mensen en instellingen die wij als blijvend beschouwen.", "reflectionNl": "Over wie denk je nog zoals vijf jaar geleden, terwijl die persoon intussen veranderd kan zijn?", "exerciseNl": "Noteer één concrete verandering bij iemand die je goed kent en herzie zo nodig je beeld.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "11-10": {"dateKey": "11-10", "day": 10, "month": 11, "sourceTitle": "ALWAYS THE SAME", "thinker": "Marcus Aurelius", "thoughtNl": "Generaties wisselen elkaar af, maar liefde, ruzie, verlies en plezier blijven herkenbaar door de eeuwen heen.", "explanationNl": "Hemingway opent een roman met een Bijbelpassage over de aarde die voortbestaat terwijl generaties komen en gaan. Holiday en Hanselman zien daarin een correctie op het idee dat onze tijd volledig uniek is. Gewoonten en opvattingen veranderen, maar mensen blijven liefhebben, vechten, rouwen en lachen. Volgens de auteurs meenden eerdere generaties ook al dat juist zij een uitzonderlijke tijd beleefden. Wie dat beseft, ziet zijn eigen generatie meer als een korte schakel in een lang verhaal.", "reflectionNl": "Welke ervaring uit jouw leven zou iemand van honderd jaar geleden meteen herkennen?", "exerciseNl": "Vraag iemand van een andere generatie hoe diegene met een vergelijkbare ervaring omging.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "11-11": {"dateKey": "11-11", "day": 11, "month": 11, "sourceTitle": "IT’S NOT THE THING, IT’S WHAT WE MAKE OF IT", "thinker": "Marcus Aurelius", "thoughtNl": "Een tegenslag kan je mogelijkheden veranderen zonder te bepalen wie je bent of wat je nog kunt doen.", "explanationNl": "Holiday en Hanselman beschrijven hoe Franklin Roosevelt na jaren voorbereiding op een politieke loopbaan op zijn negenendertigste de diagnose polio kreeg. Zijn lichamelijke beperking was een feit en bleef belangrijk voor zijn levensverhaal. Toch zag Roosevelt die beperking volgens de auteurs niet als het einde van zijn politieke ambities of als zijn hele identiteit. Ze gebruiken zijn voorbeeld om aanvaarding en passiviteit uit elkaar te houden. Je kunt erkennen wat er veranderd is en vervolgens blijven handelen met de mogelijkheden die je hebt.", "reflectionNl": "Welke beperking laat je in gedachten ook bepalen wat er buiten die beperking nog mogelijk is?", "exerciseNl": "Noteer bij één beperking welke haalbare vervolgstap er vandaag nog openligt.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "11-12": {"dateKey": "11-12", "day": 12, "month": 11, "sourceTitle": "THE STRONG ACCEPT RESPONSIBILITY", "thinker": "Marcus Aurelius", "thoughtNl": "Neem verantwoordelijkheid voor je houding en je reactie, ook als de gebeurtenis zelf buiten jouw macht ligt.", "explanationNl": "Op het bureau van president Truman stond een bordje dat uitdrukte dat de verantwoordelijkheid bij hem eindigde. Voor de auteurs is dat een voorbeeld van de houding die je tegenover je eigen keuzes kunt aannemen. De stoïcijnse grens blijft belangrijk: je beslist niet over alles wat je overkomt. Je kunt wel bepalen welk oordeel je eraan verbindt en hoe je antwoordt. Voor dat deel kun je de verantwoordelijkheid zelf dragen, ook wanneer iemand anders de situatie heeft veroorzaakt.", "reflectionNl": "Voor welke reactie geef je iemand anders nog de schuld, terwijl je zelf kunt kiezen wat je ermee doet?", "exerciseNl": "Herschrijf één verwijt als een zin die begint met wat jij nu kunt doen.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "11-13": {"dateKey": "11-13", "day": 13, "month": 11, "sourceTitle": "NEVER COMPLAIN, NEVER EXPLAIN", "thinker": "Marcus Aurelius", "thoughtNl": "Klagen maakt je verantwoordelijkheid niet lichter. Besteed je aandacht aan wat je eraan kunt doen.", "explanationNl": "Ook wie het goed heeft, kan veel tijd kwijt zijn aan klagen. Marcus Aurelius droeg als keizer verantwoordelijkheden waar hij niet om had gevraagd. Je kunt iets vergelijkbaars ervaren als je werk je bevalt, maar bepaalde taken erbij je tegenstaan. Holiday en Hanselman halen het motto van Benjamin Disraeli aan. Hij kende de druk van een zware functie. De auteurs wijzen erop dat geklaag je in een negatieve stemming brengt en dat excuses voor je eigen handelen de last niet verminderen.", "reflectionNl": "Over welke taak klaag je vaker dan je nadenkt over hoe je die kunt aanpakken?", "exerciseNl": "Kies één taak waar je tegen opziet en zet vandaag de kleinste stap die haar vooruithelpt.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "11-14": {"dateKey": "11-14", "day": 14, "month": 11, "sourceTitle": "YOU CHOOSE THE OUTCOME", "thinker": "Epictetus", "thoughtNl": "Je kiest de gebeurtenis vaak niet, maar je kunt wel kiezen wat je er vervolgens mee doet.", "explanationNl": "Malcolm X ging de gevangenis in als Malcolm Little. Toen hij vrijkwam, had hij zich ontwikkeld, een geloof gevonden en de motivatie om zich later in te zetten voor burgerrechten. De auteurs gebruiken die ontwikkeling om het verschil te laten zien tussen wat er gebeurt en de betekenis die iemand daaraan geeft. Hun punt is dat aanvaarden actie kan inleiden: vanuit de situatie zoals die is, kun je besluiten iets te leren of anders te handelen.", "reflectionNl": "Welke ervaring beoordeel je vooral op wat zij je kostte, terwijl je er ook nog iets mee kunt doen?", "exerciseNl": "Schrijf eerst op wat er feitelijk is gebeurd en noteer daarna één manier om verder te gaan.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "11-15": {"dateKey": "11-15", "day": 15, "month": 11, "sourceTitle": "EVERYTHING IS CHANGE", "thinker": "Marcus Aurelius", "thoughtNl": "Terwijl een situatie verandert, verander jij mee. Laat je reactie passen bij hoe de situatie er nu uitziet.", "explanationNl": "De auteurs verbinden Marcus' beeld van verandering met de rivier van Heraclitus. Wie een tweede keer het water instapt, treft een andere stroom aan en is zelf ook veranderd. Volgens Holiday en Hanselman raken we onnodig van streek als we aannemen dat een toestand blijft zoals hij nu is. Jezelf of anderen blijven verwijten dat iets veranderd is, zet die beweging niet stil. Zij moedigen aan om die veranderlijkheid te verwachten en je daarop in te stellen.", "reflectionNl": "Waar reageer je nog op een oude versie van een situatie?", "exerciseNl": "Kies één plan dat je kunt bijstellen met wat je vandaag weet.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "11-16": {"dateKey": "11-16", "day": 16, "month": 11, "sourceTitle": "HOPE AND FEAR ARE THE SAME", "thinker": "Seneca", "thoughtNl": "Hoop en angst kunnen je allebei vastzetten in een toekomst waarvan je de uitkomst niet bepaalt.", "explanationNl": "Hoop klinkt doorgaans wenselijk en angst ongewenst. De auteurs lichten toe waarom de stoïcijn Hecato ze toch bij elkaar plaatst: beide richten zich op een onzekere toekomst en trekken je aandacht weg van het moment waarin je iets kunt doen. Beide botsen zo met liefde voor het lot. Volgens Holiday en Hanselman ontstaat de zorg doordat je wilt dat de toekomst een bepaalde vorm krijgt. Het helpt om die gehechtheid te zien, ook wanneer zij aanvoelt als optimisme.", "reflectionNl": "Welke uitkomst houdt je bezig doordat je haar tegelijk sterk hoopt en vreest?", "exerciseNl": "Zet één toekomstige uitkomst op papier en schrijf ernaast welke handeling vandaag wél aan jou is.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "11-17": {"dateKey": "11-17", "day": 17, "month": 11, "sourceTitle": "JUDGE NOT, LEST . . .", "thinker": "Seneca", "thoughtNl": "Gebruik je aandacht voor je eigen verbeterpunten, want die liggen dichter bij je invloed dan de fouten van anderen.", "explanationNl": "De auteurs richten de beoefening van stoïcijnse filosofie op je eigen ontwikkeling. Zij vergelijken het bijwerken van je tekortkomingen met het verwijderen van aangroei van een scheepsromp. Dat is werk waaraan je zelf iets kunt doen. Anderen hebben hun eigen werk en hun eigen weg te gaan. Volgens Holiday en Hanselman geeft filosofie je daarom geen speciale bevoegdheid om over hen te oordelen. Juist omdat je zelf genoeg te leren hebt, kun je andermans tekortkomingen leren verdragen.", "reflectionNl": "Welke fout bij een ander trekt je aandacht terwijl je zelf iets soortgelijks kunt verbeteren?", "exerciseNl": "Kies één gewoonte van jezelf die je kunt aanpassen zodra je merkt dat je een ander beoordeelt.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "11-18": {"dateKey": "11-18", "day": 18, "month": 11, "sourceTitle": "FOUR HABITS OF THE STOIC MIND", "thinker": "Marcus Aurelius", "thoughtNl": "Toets je indrukken, draag bij aan anderen, richt je wensen op je invloed en aanvaard wat zich aandient.", "explanationNl": "Marcus Aurelius herhaalde zijn uitgangspunten in aantekeningen voor zichzelf. Holiday en Hanselman wijzen erop dat hij misschien egoïstisch had gehandeld, een verkeerde indruk had geloofd of iets had gewenst waarover hij niet beschikte. Mogelijk wilde hij de uitgangspunten gewoon opfrissen. De auteurs halen vier gewoonten uit zijn aantekening: toets of een indruk waar is, handel voor het gemeenschappelijke belang, beperk je wensen tot je eigen invloed en aanvaard wat de natuur voor je in petto heeft.", "reflectionNl": "Welke van de vier gewoonten zou vandaag het grootste verschil maken bij een concrete keuze?", "exerciseNl": "Schrijf die gewoonte in één korte zin en lees haar vóór die keuze terug.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "11-19": {"dateKey": "11-19", "day": 19, "month": 11, "sourceTitle": "MAXIMS FROM THREE WISE MEN", "thinker": "Cleanthes, Euripides en Plato", "thoughtNl": "Bekijk een onverwachte gebeurtenis eens in een groter verband en merk op of je verzet daardoor verandert.", "explanationNl": "Epictetus verzamelt uitspraken uit verschillende tijden. Holiday en Hanselman lezen daarin een gemeenschappelijke lijn van verdraagzaamheid, soepelheid en aanvaarding. Bij Cleanthes en Euripides kan een idee van het lot daarbij helpen. De auteurs noemen ook een ruimere blik op natuur en levensloop voor wie geen goddelijke leiding veronderstelt. Van dichtbij kan iets willekeurig of wreed lijken. Als denkoefening stellen ze voor om je voor te stellen dat ook het onverwachte een plaats heeft in een groter geheel.", "reflectionNl": "Wat verandert er aan je eerste reactie als je één onverwachte gebeurtenis vanuit een ruimer perspectief bekijkt?", "exerciseNl": "Schrijf bij één tegenvaller twee omstandigheden op die buiten jouw eigen verhaal over die gebeurtenis vallen.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "11-20": {"dateKey": "11-20", "day": 20, "month": 11, "sourceTitle": "BEHOLD, NOW AS EVER", "thinker": "Marcus Aurelius", "thoughtNl": "Wat jou vandaag voor het eerst overkomt, kan een ervaring zijn die anderen al lang vóór jou hadden.", "explanationNl": "Holiday en Hanselman wijzen op gebeurtenissen die zich al heel lang herhalen: geboorte en dood, bewegende wolken en de adem die in en uit gaat. Ze herkennen datzelfde besef bij Emerson en in de christelijke lofzang Gloria Patri. Volgens hen is die herhaling op zichzelf neutraal, al kan het besef ervan rust geven. Wanneer iets jou overvalt, kan het opluchten te bedenken dat iemand eerder al iets vergelijkbaars heeft gezien en dat jouw moment deel uitmaakt van die langere reeks.", "reflectionNl": "Welke nieuwe ervaring wordt minder overweldigend als je bedenkt dat anderen haar al hebben doorgemaakt?", "exerciseNl": "Zoek één persoon die ervaring heeft met wat jou te wachten staat en bedenk wat je diegene wilt vragen.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "11-21": {"dateKey": "11-21", "day": 21, "month": 11, "sourceTitle": "ONCE IS ENOUGH, ONCE IS FOREVER", "thinker": "Chrysippus", "thoughtNl": "Een kort moment van geluk of inzicht telt ook als het voorbijgaat. Je kunt het later nog herkennen.", "explanationNl": "Wie eenmaal een olympische medaille wint, blijft een medaillewinnaar, ook als later iemand sneller blijkt. Met dat beeld leggen Holiday en Hanselman uit hoe een kort moment van wijsheid of geluk betekenis kan houden. Ze noemen daarnaast de persoonlijke ervaring van acteur Evan Handler, die wilde weten hoe gewoon geluk voelde. De auteurs stellen voor om zo'n moment op te merken, ervan te genieten en het te onthouden. Hoe lang het duurt, heb je niet in de hand.", "reflectionNl": "Welk kort moment van geluk herinner je je nog juist omdat je het toen bewust opmerkte?", "exerciseNl": "Schrijf vanavond één prettig moment op en noem één concreet detail ervan.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "11-22": {"dateKey": "11-22", "day": 22, "month": 11, "sourceTitle": "THE GLASS IS ALREADY BROKEN", "thinker": "Seneca", "thoughtNl": "Als je beseft dat iets breekbaar is, kun je ervan genieten en tegelijk rekening houden met verlies.", "explanationNl": "Een zenmeester genoot van zijn kostbare beker en hield ondertussen rekening met de mogelijkheid dat die ooit zou breken. De auteurs noemen ook het verhaal waarin Epictetus een gestolen lamp door een goedkopere verving om zich er minder aan te hechten. Zij verbinden de schok van een verlies met hoe ondenkbaar je het vooraf vond. Zoals sneeuw in de winter weinig verbazing wekt, kan het je helpen om een plausibele tegenslag af en toe vooraf te overwegen.", "reflectionNl": "Van welk dierbaar voorwerp ga je vanzelfsprekend uit dat het er morgen nog zal zijn?", "exerciseNl": "Gebruik vandaag een geliefd voorwerp aandachtig en sta kort stil bij wat je eraan waardeert.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "11-23": {"dateKey": "11-23", "day": 23, "month": 11, "sourceTitle": "ATTACHMENTS ARE THE ENEMY", "thinker": "Epictetus", "thoughtNl": "Je kunt iets waarderen zonder je geluk afhankelijk te maken van de vraag of het altijd hetzelfde blijft.", "explanationNl": "Met Anthony de Mello en Epictetus bespreken de auteurs gehechtheid aan status, bezit, gewoonten en het beeld dat je van iemand hebt. Je bepaalt niet hoelang zulke dingen blijven. Wie ze toch koste wat kost wil behouden, moet steeds harder werken om op dezelfde plek te blijven, zoals de Rode Koningin in het verhaal van Alice. Holiday en Hanselman stellen daar het vermogen tot weloverwogen kiezen tegenover. Dat kun je blijven inzetten en aanpassen als je omstandigheden veranderen.", "reflectionNl": "Welke gewoonte probeer je koste wat kost vast te houden, terwijl je omstandigheden al zijn veranderd?", "exerciseNl": "Verander vandaag één klein onderdeel van die gewoonte en kijk wat er werkelijk gebeurt.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "11-24": {"dateKey": "11-24", "day": 24, "month": 11, "sourceTitle": "TRAIN TO LET GO OF WHAT’S NOT YOURS", "thinker": "Epictetus", "thoughtNl": "Herinner jezelf op een goed moment dat wat je liefhebt kwetsbaar is en niet voorgoed bij je blijft.", "explanationNl": "Holiday en Hanselman schetsen een Romeinse triomftocht waarin een helper de gevierde bevelhebber juist op het hoogtepunt aan zijn sterfelijkheid herinnert. Ze maken daarvan een oefening voor momenten waarop iets dierbaars vanzelfsprekend of onaantastbaar lijkt. Je kunt jezelf dan zacht herinneren aan de kwetsbaarheid van wat je bezit of wie je liefhebt. Volgens de auteurs vergroot wegkijken de schok wanneer verlies zich werkelijk voordoet. De gedachte aan vergankelijkheid kan ook naast waardering voor het huidige moment bestaan.", "reflectionNl": "Wie of wat waardeer je vandaag extra als je even beseft dat de aanwezigheid ervan tijdelijk is?", "exerciseNl": "Besteed vandaag vijf minuten onverdeelde aandacht aan iets of iemand die je vaak vanzelfsprekend vindt.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "11-25": {"dateKey": "11-25", "day": 25, "month": 11, "sourceTitle": "FUNNY HOW THAT WORKS OUT", "thinker": "Musonius Rufus", "thoughtNl": "Je eerste oordeel over geluk of pech zegt weinig over hoe een gebeurtenis uiteindelijk in je leven uitwerkt.", "explanationNl": "De auteurs zetten twee uiteenlopende reacties naast elkaar. Ze noemen verhalen van loterijwinnaars bij wie plotselinge rijkdom samengaat met financiële of relationele problemen. Daartegenover plaatsen ze mensen die na kanker beschrijven dat die gevreesde periode uiteindelijk ook een betekenisvolle verandering bracht. Dat contrast laat zien hoe beperkt het eerste oordeel over geluk of ongeluk kan zijn. Een meevaller kan later een last blijken. Een zware ervaring kan ook gevolgen krijgen die je vooraf niet had kunnen voorzien.", "reflectionNl": "Welke gebeurtenis kreeg voor jou een andere betekenis toen je er later op terugkeek?", "exerciseNl": "Schrijf je eerste oordeel over een recente meevaller op en bedenk één onverwacht gevolg dat mogelijk is.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "11-26": {"dateKey": "11-26", "day": 26, "month": 11, "sourceTitle": "THE ALTAR OF NO DIFFERENCE", "thinker": "Marcus Aurelius", "thoughtNl": "Ranglijsten zeggen weinig over hoe je vandaag wilt leven. Je deelt met ieder ander dat je tijd begrensd is.", "explanationNl": "De auteurs relativeren de afstand tussen jou en wie het rijkst, oudst of snelst is. Er is verschil, maar voortdurend meten voedt het verlangen naar andermans omstandigheden of naar een leven dat anders had kunnen lopen. Dat maakt het moeilijk te aanvaarden wat je wel hebt. Holiday en Hanselman lezen Marcus' herinnering aan sterfelijkheid als een nuchtere vaststelling die voor iedereen geldt. Die gedeelde grens maakt het volgens hen de moeite waard je tijd aan belangrijkere zaken te besteden dan aan rangverschillen.", "reflectionNl": "Met wie vergelijk je jezelf vaak, en welke eigen taak verdient die tijd eigenlijk?", "exerciseNl": "Sla vandaag één vergelijkingsmoment over en besteed de vrijgekomen minuten aan die taak.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "11-27": {"dateKey": "11-27", "day": 27, "month": 11, "sourceTitle": "THE PLEASURE OF TUNING OUT THE NEGATIVE", "thinker": "Marcus Aurelius", "thoughtNl": "Je kunt rust bewaren door een terugkerende bron van irritatie bewust minder aandacht en ruimte te geven.", "explanationNl": "De auteurs wijzen op hedendaagse informatiestromen die je voortdurend iets geven om je over op te winden. Ook in de oudheid waren er genoeg afleidingen. Holiday en Hanselman noemen terugkerende politieke ruzies aan tafel en het bemoeien met keuzes van een familielid. Wie zijn gebruikelijke reactie herkent, kan besluiten er deze keer niet in mee te gaan en de aanleiding voortaan minder vaak op te zoeken. De auteurs zien die doelbewuste begrenzing als een vorm van wilskracht.", "reflectionNl": "Welke terugkerende prikkel zoek je zelf op terwijl je de irritatie die volgt al kunt voorspellen?", "exerciseNl": "Zet één terugkerende bron van ergernis vandaag stil of laat één gespreksonderwerp bewust rusten.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "11-28": {"dateKey": "11-28", "day": 28, "month": 11, "sourceTitle": "IT’S NOT ON THEM, IT’S ON YOU", "thinker": "Marcus Aurelius", "thoughtNl": "Onderzoek eerst wat jij kunt verduidelijken, aanbieden of loslaten als iemands gedrag je dwarszit.", "explanationNl": "Holiday en Hanselman nemen een leraar als voorbeeld. Als een leerling vastloopt, kan de leraar eerst onderzoeken wat er aan de uitleg of begeleiding ontbreekt. Dezelfde houding kan volgens hen helpen bij een onbetrouwbare vriend of een medewerker die moeite heeft met het werk. Bespreek wat je ziet en vraag welke steun ontbreekt. Onderzoek bij irritatie ook je eigen gevoeligheid. Als praten of helpen niets oplevert, kun je een incident soms laten rusten, zeker wanneer het eenmalig blijkt.", "reflectionNl": "Welk gedrag zou je beter begrijpen als je eerst vraagt wat de ander nodig heeft?", "exerciseNl": "Vervang vandaag één stil verwijt door een concrete, open vraag.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "11-29": {"dateKey": "11-29", "day": 29, "month": 11, "sourceTitle": "YOU’RE GOING TO BE OK", "thinker": "Marcus Aurelius", "thoughtNl": "Een tegenvaller vertelt je wat er gebeurd is. Wat er daarna gebeurt, weet je nog niet.", "explanationNl": "Direct na een tegenvaller kunnen we het gevoel krijgen dat alles verloren is. De auteurs beschrijven hoe klagen en zelfmedelijden dan uitlopen op vechten tegen iets wat al voorbij is. Over het vervolg weten we op dat moment weinig. Er kan meer moeilijkheid volgen, of juist een kentering. Holiday en Hanselman leggen de stoïcijnse zekerheid bij vertrouwen in je vermogen om met het vervolg om te gaan, ook als je de inhoud van dat vervolg niet kunt voorspellen.", "reflectionNl": "Welke voorspelling maak je over de toekomst op basis van één slechte uitkomst?", "exerciseNl": "Schrijf op wat vaststaat en welke voorspelling je daar zelf aan hebt toegevoegd.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "11-30": {"dateKey": "11-30", "day": 30, "month": 11, "sourceTitle": "FOLLOW THE LOGOS", "thinker": "Marcus Aurelius", "thoughtNl": "Ook wanneer de grote richting vastligt, kun je vaak nog kiezen hoe je de weg aflegt.", "explanationNl": "De stoïcijnen geloofden volgens Holiday en Hanselman in een ordenende rede, de logos, die zowel gewenste als ongewenste gebeurtenissen omvat. Om dit uit te leggen gebruiken de auteurs een hond die met een bewegende kar is verbonden. De kar bepaalt de richting, terwijl de lijn ruimte laat om het tempo en de stappen enigszins te kiezen. Zo maakt de vergelijking zichtbaar hoeveel keuze er binnen een gegeven situatie kan overblijven. Je kunt meebewegen of je onderweg tegen de richting blijven verzetten.", "reflectionNl": "Waar besteed je energie aan verzet terwijl je binnen dezelfde omstandigheden nog iets kunt kiezen?", "exerciseNl": "Benoem bij één vaststaande afspraak welk deel van de voorbereiding of uitvoering nog van jou afhangt.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "12-01": {"dateKey": "12-01", "day": 1, "month": 12, "sourceTitle": "PRETEND TODAY IS THE END", "thinker": "Seneca", "thoughtNl": "Leef vandaag als iemand die zijn zaken op orde wil hebben en de mensen om hem heen wil spreken.", "explanationNl": "Holiday en Hanselman zoeken een praktische invulling voor leven alsof het je laatste dag is. Ze vergelijken het met iemand die wordt uitgezonden en niet zeker weet of die terugkomt. Zo iemand brengt zijn zaken op orde, spreekt uit wat naasten voor hem betekenen en houdt weinig tijd over voor kleine ruzies. De hoop om terug te komen blijft bestaan, samen met voorbereiding op een andere afloop. De auteurs vragen welke zaken jij vandaag met diezelfde aandacht zou regelen.", "reflectionNl": "Welke boodschap of praktische afspraak zou je vandaag willen afhandelen als morgen onzeker was?", "exerciseNl": "Doe vandaag één klein ding dat je anders onnodig zou uitstellen.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "12-02": {"dateKey": "12-02", "day": 2, "month": 12, "sourceTitle": "DON’T MIND ME, I’M ONLY DYING SLOW", "thinker": "Marcus Aurelius", "thoughtNl": "Je hebt geen ernstige diagnose nodig om te beseffen dat de tijd die vandaag voorbijgaat nooit terugkomt.", "explanationNl": "De vraag wat je bij een terminale diagnose zou veranderen, haalt je plotseling uit je gewone routine. Holiday en Hanselman keren die vraag om: ook zonder diagnose staat vast dat ieders leven eindigt. Ze halen schrijver Edmund Wilson aan om te onderstrepen dat de dood de voorspelling is die altijd uitkomt. Elke verstreken seconde is voorgoed voorbij. De auteurs verwachten dat dit besef doorwerkt in wat je doet, zegt en denkt, zodra je het een plaats geeft in je dag.", "reflectionNl": "Wat zou je vandaag anders zeggen of doen als je de tijd die je eraan besteedt bewust als eindig zag?", "exerciseNl": "Kies iets wat je belangrijk vindt en maak er vandaag een kwartier voor vrij.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "12-03": {"dateKey": "12-03", "day": 3, "month": 12, "sourceTitle": "THE PHILOSOPHER AS AN ARTISAN OF LIFE AND DEATH", "thinker": "Epictetus", "thoughtNl": "Filosofie krijgt vorm wanneer je een inzicht gebruikt om een alledaags probleem of een moeilijke keuze beter aan te pakken.", "explanationNl": "Holiday en Hanselman verbinden Epictetus met Thoreau, die filosofie opvatte als praktisch werk aan levensproblemen, en met Cicero, die haar verbond met leren sterven. Hun vergelijking is die van een beeldhouwer die met elke beitelslag vorm geeft aan het materiaal. Elke ervaring kan zo een gelegenheid zijn om aan je leven te werken. Oefeningen en uitspraken krijgen hun betekenis doordat je ze onthoudt en toepast op de moeilijke opgave om je ene leven zo goed mogelijk te leven.", "reflectionNl": "Welk inzicht vind je al langer goed klinken, en waar kun je het vandaag daadwerkelijk toepassen?", "exerciseNl": "Kies één zin die je wilt onthouden en gebruik haar als geheugensteun vóór een concrete beslissing.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "12-04": {"dateKey": "12-04", "day": 4, "month": 12, "sourceTitle": "YOU DON’T OWN THAT", "thinker": "Epictetus", "thoughtNl": "Veel wat je het jouwe noemt, is tijdelijk aan je toevertrouwd. Ga er zorgvuldig mee om zolang het er is.", "explanationNl": "Natuurbeschermer Daniel O'Brien grapt dat hij op zijn ranch mag wonen zolang de bank zijn hypotheekbetalingen aanneemt. Holiday en Hanselman gebruiken dat beeld om een ruimere vorm van tijdelijk bezit uit te leggen. Het land kan generaties overleven, terwijl status, kracht, gezondheid en relaties plotseling kunnen veranderen. Marcus Aurelius zag zelfs ons leven als iets dat ons is toevertrouwd. De auteurs vragen hoe volledig ons bezit eigenlijk kan zijn wanneer omstandigheden het zonder waarschuwing van ons kunnen afnemen.", "reflectionNl": "Wat beschouw je als gegarandeerd van jou terwijl je niet bepaalt hoelang het bij je blijft?", "exerciseNl": "Doe één concrete onderhouds- of zorgtaak voor iets wat je tijdelijk is toevertrouwd.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "12-05": {"dateKey": "12-05", "day": 5, "month": 12, "sourceTitle": "THE BENEFITS OF SOBERING THOUGHTS", "thinker": "Epictetus", "thoughtNl": "Je plannen kunnen plotseling veranderen. Een ogenblik stilstaan bij die mogelijkheid kan je blik op vandaag scherpen.", "explanationNl": "De auteurs herinneren eraan dat omstandigheden die veilig of stabiel lijken opeens kunnen kantelen. Ze noemen veranderende politieke vrijheden en geweld als voorbeelden, en verwijzen naar het Gilgamesj-epos, dat ook jonge mensen als kwetsbaar beschrijft. De dood is in deze meditatie het meest ingrijpende voorbeeld. Ook veel kleinere gebeurtenissen kunnen een zorgvuldig plan onderbreken. Holiday en Hanselman vragen welke prijs je betaalt voor de tijdelijke geruststelling die ontstaat als je zulke mogelijkheden consequent buiten beeld houdt.", "reflectionNl": "Welk belangrijk plan steunt op een aanname waar je zelden bewust bij stilstaat?", "exerciseNl": "Noteer bij dat plan één plausibele onderbreking en één haalbare manier om daarop te reageren.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "12-06": {"dateKey": "12-06", "day": 6, "month": 12, "sourceTitle": "THE SWORD DANGLES OVER YOU", "thinker": "Marcus Aurelius", "thoughtNl": "Als je beseft hoe plotseling je tijd kan eindigen, krijgt goed handelen vandaag voorrang boven goede voornemens voor later.", "explanationNl": "In het verhaal van Damocles mag een hoveling ervaren hoe het is om koning te zijn. Boven zijn troon hangt een zwaard aan een haar, als beeld voor het gevaar dat met de positie samengaat. Holiday en Hanselman trekken de vergelijking door naar de onzekerheid van ieder leven. Dat besef kan angst oproepen en het kan je aansporen om goed te handelen. De auteurs vragen wat je nu doet, wanneer je niet zeker bent dat je later tijd hebt om het beter te doen.", "reflectionNl": "Welke goede daad schuif je naar een moment dat je nog niet in handen hebt?", "exerciseNl": "Voer vandaag één kleine versie van die daad uit.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "12-07": {"dateKey": "12-07", "day": 7, "month": 12, "sourceTitle": "THE CARDS WE’RE DEALT", "thinker": "Marcus Aurelius", "thoughtNl": "Stilstaan bij het einde van je leven kan duidelijk maken welke kleine ergernis vandaag weinig aandacht verdient.", "explanationNl": "We ontwijken gedachten aan onze sterfelijkheid vaak uit vrees dat ze ons somber maken. Holiday en Hanselman merken op dat het besef ook energie kan geven doordat het je prioriteiten helder maakt. Ze laten je voorstellen wat je zou veranderen met nog een week te leven of na een bijna-doodervaring. Met een verwijzing naar Shakespeare maken ze duidelijk hoe kleine afleidingen daardoor gewicht verliezen. Die helderheid kun je gebruiken om vandaag meer te handelen zoals je eigenlijk wilt.", "reflectionNl": "Welke ergernis zou je onmiddellijk losser laten als je tijd opeens veel schaarser voelde?", "exerciseNl": "Verplaats vandaag tien minuten van die ergernis naar iets wat je belangrijk vindt.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "12-08": {"dateKey": "12-08", "day": 8, "month": 12, "sourceTitle": "DON’T HIDE FROM YOUR FEELINGS", "thinker": "Seneca", "thoughtNl": "Verdriet verdient aandacht. Geef jezelf ruimte om te voelen wat er speelt en te begrijpen waar de pijn zit.", "explanationNl": "Na verlies proberen anderen je soms vriendelijk af te leiden. Holiday en Hanselman zien daarin kortstondige verlichting. Voor verwerking leggen ze de nadruk op voelen en begrijpen wat er gebeurt. De stoïcijnse oefening die zij beschrijven vraagt dat je je pijn erkent en onderzoekt welke verwachtingen of gevoelens van onrecht ermee verweven zijn. Je kunt tegelijk oog houden voor wat waarde heeft en ruimte geven aan het gemis. Pijn toelaten hoort volgens hen bij erkennen dat verlies deel uitmaakt van het leven.", "reflectionNl": "Welk gevoel probeer je snel te verdrijven terwijl je nog nauwelijks hebt benoemd wat erachter zit?", "exerciseNl": "Neem drie rustige minuten om één gevoel op te schrijven in woorden die voor jou kloppen.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "12-09": {"dateKey": "12-09", "day": 9, "month": 12, "sourceTitle": "SPENDTHRIFTS OF TIME", "thinker": "Seneca", "thoughtNl": "Geef aandacht en tijd net zo bewust weg als andere kostbare dingen, want verstreken tijd krijg je nooit terug.", "explanationNl": "Berichten, telefoontjes en onverwacht bezoek kunnen je dag vullen voordat je aan nadenken toekomt. Holiday en Hanselman verwijzen naar Booker T. Washington, die zag hoe gemakkelijk anderen je tijd kunnen opeisen zonder duidelijk doel. Een filosoof beschermt volgens hen de ruimte om even stil te staan bij wat er gebeurt en hoe die daarop reageert. Ze sluiten aan bij Seneca's onderscheid: bezit kun je soms terugkrijgen, terwijl een uur dat eenmaal voorbij is voorgoed verdwenen blijft.", "reflectionNl": "Welk terugkerend verzoek krijgt automatisch je tijd zonder dat het je veel oplevert?", "exerciseNl": "Reserveer tien minuten zonder meldingen om rustig over één open vraag na te denken.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "12-10": {"dateKey": "12-10", "day": 10, "month": 12, "sourceTitle": "DON’T SELL YOURSELF TOO CHEAPLY", "thinker": "Seneca", "thoughtNl": "Behandel je tijd als iets waarmee je bewust betaalt en vraag wat een nieuwe verplichting je werkelijk oplevert.", "explanationNl": "Holiday en Hanselman vergelijken tijd besteden met betalen. Bij een kaartbetaling voel je volgens hun voorbeeld de uitgave minder direct dan wanneer je geld uit je portemonnee haalt. Met je tijd gebeurt iets vergelijkbaars: hoeveel dagen je hebt blijft onbekend, waardoor het makkelijk is verzoeken en verplichtingen te accepteren zonder hun prijs te voelen. Ze lezen Seneca als een uitnodiging om bij iedere toezegging bewust te wegen wat je ervoor opgeeft en wat je ervoor terugkrijgt.", "reflectionNl": "Welk verzoek zou je anders beoordelen als je de benodigde uren vooraf letterlijk voor je zag?", "exerciseNl": "Noteer vóór één toezegging hoeveel tijd die vraagt en welke activiteit ervoor moet wijken.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "12-11": {"dateKey": "12-11", "day": 11, "month": 12, "sourceTitle": "DIGNITY AND BRAVERY", "thinker": "Seneca", "thoughtNl": "Moed kan betekenen dat je een ongemakkelijke plicht aanvaardt, zonder je veiligheid roekeloos op het spel te zetten.", "explanationNl": "Holiday en Hanselman halen verhalen over Lyndon Johnson aan zoals biograaf Robert Caro ze beschreef. Zijn intimiderende optreden hield volgens hen weinig stand wanneer iemand hem daadwerkelijk weerstond. Ze stellen zijn latere oorlogsverhaal tegenover wat ze zien als zijn pogingen om gevaar te ontwijken. Het morele onderscheid dat ze trekken is dat tussen zorgvuldig omgaan met veiligheid en je aan een plicht onttrekken voor eigen gemak. Die tweede vorm van zelfbescherming kan je waardigheid kosten en je iets geven waarvoor je je later schaamt.", "reflectionNl": "Welke verantwoordelijkheid vermijd je vooral omdat ze ongemakkelijk is, terwijl je haar veilig kunt opnemen?", "exerciseNl": "Zet één voorbereidingsstap voor een gesprek of taak die je om die reden uitstelt.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "12-12": {"dateKey": "12-12", "day": 12, "month": 12, "sourceTitle": "THE BEAT GOES ON", "thinker": "Marcus Aurelius", "thoughtNl": "Mensen, ideeën en instellingen volgen elk hun eigen tempo, maar zelfs wat eeuwen voortduurt heeft een einde.", "explanationNl": "Holiday en Hanselman zetten de lange levensduur van Romeinse staatsvormen naast de veel kortere duur van een mensenleven. Ook ondernemingen, godsdiensten en ideeën kunnen ophouden te bestaan. De cijfers en voorbeelden verschillen in omvang, maar illustreren dezelfde eindigheid. De auteurs verbinden die met het ritme van gebeurtenissen bij Marcus Aurelius: op een gegeven moment volgt de laatste slag. Je hoeft je daar volgens hen niet voortdurend mee bezig te houden. Af en toe erkennen dat ook lange tijden eindig zijn, volstaat.", "reflectionNl": "Welke instelling of gewoonte voelt voor jou zo vertrouwd dat je haar moeilijk als tijdelijk kunt zien?", "exerciseNl": "Kijk vandaag naar één vertrouwde plek en merk op wat er sinds je eerste bezoek veranderd is.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "12-13": {"dateKey": "12-13", "day": 13, "month": 12, "sourceTitle": "IT’S JUST A NUMBER", "thinker": "Marcus Aurelius", "thoughtNl": "De waarde van je jaren groeit door wat je ermee doet, en die keuze begint bij de dag die je hebt.", "explanationNl": "Leeftijd lijkt soms een getal waaraan mensen status, zekerheid of hoop ontlenen. De auteurs zien hoe gemakkelijk het aantal jaren daardoor belangrijker lijkt dan wat iemand in die jaren doet. Ze halen Seneca aan om de aandacht naar het gebruik van tijd te verschuiven. Wie veel dagen gedachteloos laat voorbijgaan, kan later proberen dat verlies te compenseren door meer tijd te willen. Holiday en Hanselman vragen je daarom een dag zo te besteden dat je zelf tevreden bent met wat je ermee hebt gedaan.", "reflectionNl": "Waar zou je meer tevreden over zijn als je vandaag keek naar de invulling van je tijd in plaats van de hoeveelheid?", "exerciseNl": "Benoem vanavond één handeling waaraan je je tijd morgen weer graag zou besteden.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "12-14": {"dateKey": "12-14", "day": 14, "month": 12, "sourceTitle": "WHAT WE SHOULD KNOW BY THE END", "thinker": "Marcus Aurelius", "thoughtNl": "Hoe eerder je aan je karakter werkt, hoe langer je kunt profiteren van de keuzes die je leert maken.", "explanationNl": "Marcus schreef volgens de auteurs vermoedelijk veel van zijn aantekeningen toen hij ouder en ernstig ziek was. Zij lezen zijn woorden over de nabije dood als iets wat hij in de eerste plaats tegen zichzelf zei. Zelfs na grote prestaties kon hij nog last hebben van frustratie en andere pijnlijke emoties. Hij zag dat betere keuzes verlichting konden geven. Voor Holiday en Hanselman maakt dat de tijd die je wél hebt belangrijk: ook een onvolmaakt mens kan al profiteren van werk aan zijn karakter.", "reflectionNl": "Aan welke eigenschap wil je eerder beginnen te werken zodat je er tijdens je leven meer aan hebt?", "exerciseNl": "Kies één terugkerende situatie waarin je die eigenschap vandaag bewust kunt inzetten.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "12-15": {"dateKey": "12-15", "day": 15, "month": 12, "sourceTitle": "A SIMPLE WAY TO MEASURE OUR DAYS", "thinker": "Marcus Aurelius", "thoughtNl": "Je hoeft geen hele dag volmaakt te leven om vandaag met één kleine keuze iets dichterbij te komen.", "explanationNl": "De auteurs beschrijven de volmaakte wijze als het ideaal waarnaar de stoïcijnen streefden, al zagen zij volmaaktheid als onbereikbaar. De poging om elke dag iets dichterbij te komen had op zichzelf waarde. Holiday en Hanselman vragen of iemand werkelijk een hele dag kan leven alsof het de laatste is, en consequent vanzelf het juiste kan doen. Zelfs een minuut kan moeilijk blijken. Hun maatstaf is daarom de oprechte poging om je karakter in concrete momenten te oefenen.", "reflectionNl": "Op welk alledaags moment zou je vandaag één keuze willen maken die beter bij je waarden past?", "exerciseNl": "Kies dat moment vooraf en noteer achteraf kort wat je daadwerkelijk deed.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "12-16": {"dateKey": "12-16", "day": 16, "month": 12, "sourceTitle": "EVERLASTING GOOD HEALTH", "thinker": "Epictetus", "thoughtNl": "Je vermogen om weloverwogen te kiezen verdient vertrouwen, ook wanneer je omstandigheden of je lichaam minder betrouwbaar voelen.", "explanationNl": "Volgens Holiday en Hanselman is het riskant zekerheid te zoeken in zaken waarover je niet beschikt. Epictetus plaatst het vermogen om weloverwogen te kiezen in een andere categorie. De auteurs vergelijken dat vermogen met een vorm van gezondheid die je kunt blijven beoefenen, terwijl lichamelijke gezondheid plotseling kan veranderen. Ze wijzen op mensen met heel verschillende posities en verplichtingen, waaronder Socrates, Diogenes en Cleanthes. Voor deze oefening hoef je volgens hen geen bijzonder beroep of een onbezorgd leven te hebben.", "reflectionNl": "Welke weloverwogen keuze ligt vandaag nog binnen je bereik ondanks de onzekerheid om je heen?", "exerciseNl": "Neem vóór één automatische reactie een korte pauze en benoem je beschikbare keuzes.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "12-17": {"dateKey": "12-17", "day": 17, "month": 12, "sourceTitle": "KNOW THYSELF—BEFORE IT’S TOO LATE", "thinker": "Seneca", "thoughtNl": "Maak tijd om te onderzoeken wat je belangrijk vindt en nodig hebt voordat de jaren die vraag voor je uitstellen.", "explanationNl": "Beroemde mensen kunnen volgens Holiday en Hanselman het merkwaardige lot hebben dat onbekenden veel details over hen weten, terwijl zij zelf weinig tijd nemen om zichzelf te leren kennen. Drukte en ongemak kunnen dat onderzoek in de weg staan. De auteurs verbinden dit met Socrates' oproep tot zelfkennis en betrekken die op iedereen. Wie nooit vraagt wat belangrijk is, wat plezier geeft en wat nodig is, kan pas jaren later merken hoe lang die vragen zijn blijven liggen.", "reflectionNl": "Welke vraag over wat jij nodig hebt heb je al lange tijd niet eerlijk voor jezelf beantwoord?", "exerciseNl": "Schrijf drie minuten over die ene vraag en laat je eerste antwoord voorlopig open.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "12-18": {"dateKey": "12-18", "day": 18, "month": 12, "sourceTitle": "WHAT COMES TO US ALL", "thinker": "Marcus Aurelius", "thoughtNl": "Macht en aanzien geven niemand een ander einde. Dat besef kan hoogmoed en een gevoel van minderwaardigheid temperen.", "explanationNl": "Benjamin Franklins bekende koppeling van dood en belasting gebruiken de auteurs om één zekerheid te benadrukken die niemand kan ontwijken. Ze wijzen ook op Hamlet, waar Shakespeare de resten van machtige heersers voorstelt als gewone aarde die zelfs een gat in een muur kan vullen. Holiday en Hanselman lezen die gelijkheid als een oefening in nederigheid. Of je je verheven voelt boven anderen of juist minderwaardig, iedereen komt uiteindelijk op dezelfde bestemming uit, ongeacht de plaats die iemand tijdens het leven inneemt.", "reflectionNl": "In welke ontmoeting zou je anders handelen als je rang of status even minder gewicht gaf?", "exerciseNl": "Geef vandaag iemand met wie je gewoonlijk vluchtig omgaat een moment van volle aandacht.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "12-19": {"dateKey": "12-19", "day": 19, "month": 12, "sourceTitle": "HUMAN SCALE", "thinker": "Marcus Aurelius", "thoughtNl": "Je bent één mens tussen velen. Doe wat je kunt, ook wanneer het voelt alsof alles van jou afhangt.", "explanationNl": "De auteurs plaatsen een mensenlichaam naast de enorme hoeveelheid materie in het heelal en een mensenleven naast de ouderdom van de aarde. Die schaal maakt het makkelijker te zien hoe beperkt ieders plaats in het grotere geheel is. Holiday en Hanselman gebruiken dat inzicht zowel bij zelfingenomenheid als bij het gevoel dat alles afhangt van je volgende beslissing. Je handelt binnen een veel grotere wereld, samen met talloze anderen. Jouw aandeel zorgvuldig leveren is volgens hen voldoende.", "reflectionNl": "Bij welke beslissing voelt je aandeel groter dan het werkelijk is?", "exerciseNl": "Schrijf op wie of wat naast jou invloed heeft op de uitkomst en kies daarna je eigen eerstvolgende stap.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "12-20": {"dateKey": "12-20", "day": 20, "month": 12, "sourceTitle": "FEAR THE FEAR OF DEATH", "thinker": "Epictetus", "thoughtNl": "Het onbekende kan de dood angstig maken. Onderzoek wat je vreest en wat die angst vandaag met je doet.", "explanationNl": "Holiday en Hanselman bespreken hoe onbekendheid met de dood ruimte geeft aan angst. Ze verwijzen naar Plato, Seneca en het dagboek van Florida Scott-Maxwell om te laten zien hoe anderen over die vrees nadachten. Voor de auteurs kunnen zulke voorbeelden helpen om je eigen angst onder ogen te zien. Ze geven daarnaast een stoïcijnse gedachte mee: als de dood werkelijk het einde is, eindigen volgens die redenering ook de angst, pijn en zorgen die je er nu bij voorstelt.", "reflectionNl": "Welke zorg over het einde komt voort uit iets wat je je voorstelt maar niet kunt weten?", "exerciseNl": null, "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "12-21": {"dateKey": "12-21", "day": 21, "month": 12, "sourceTitle": "WHAT DO YOU HAVE TO SHOW FOR YOUR YEARS?", "thinker": "Seneca", "thoughtNl": "Bekijk je geleefde uren aan de hand van wat je leerde en wie je werd terwijl die uren verstreken.", "explanationNl": "Holiday en Hanselman stellen voor om je leeftijd om te rekenen naar uren. Het grote getal maakt zichtbaar hoeveel tijd je vanzelfsprekend hebt gevonden. De auteurs denken aan vergaderingen, matig amusement en bezittingen die weinig sporen nalaten, en halen een personage van Raymond Chandler aan dat vooral tijd doodt. Hun vraag naar opbrengst draait om wijsheid, inzicht en vooruitgang in menselijke moeilijkheden. Aan het einde wil je volgens hen kunnen terugkijken op tijd die je daadwerkelijk en bewust hebt geleefd.", "reflectionNl": "Welk inzicht of welke verandering laat zien dat je een deel van je tijd werkelijk hebt benut?", "exerciseNl": "Noteer vanavond één moment waarop je vandaag iets leerde wat je volgende keer kunt toepassen.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "12-22": {"dateKey": "12-22", "day": 22, "month": 12, "sourceTitle": "STAKE YOUR OWN CLAIM", "thinker": "Seneca", "thoughtNl": "Geef een inzicht uit je eigen ervaring woorden en laat in je handelen zien wat je ermee bedoelt.", "explanationNl": "Emerson vond dat schrijvers soms anderen citeren om om een moeilijke vraag heen te draaien. De auteurs herkennen bij Seneca een vergelijkbare uitnodiging om zelf te denken. Het voelt veiliger om woorden van een gezaghebbend iemand te herhalen dan om je eigen inzicht te formuleren. Toch zijn de uitspraken die je bewondert ooit ook ontstaan uit iemands eigen waarneming en ervaring. Holiday en Hanselman vragen je om te erkennen wat je zelf hebt geleerd en dat zowel in woorden als in gedrag te laten zien.", "reflectionNl": "Welke les uit je eigen ervaring zou je ook zonder een bekend citaat overtuigend kunnen verwoorden?", "exerciseNl": "Schrijf die les in je eigen woorden en kies één klein gebaar waarin je haar vandaag toepast.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "12-23": {"dateKey": "12-23", "day": 23, "month": 12, "sourceTitle": "WHAT ARE YOU SO AFRAID OF LOSING?", "thinker": "Seneca", "thoughtNl": "Vraag wat je eigenlijk probeert te behouden wanneer je zo bang bent om de tijd die je hebt te verliezen.", "explanationNl": "Seneca vertelt over een rijke Romein die na een bad zelfs moest vragen of hij al zat. Holiday en Hanselman lezen het verhaal als een extreem voorbeeld van iemand die zo veel uit handen heeft gegeven dat hij nauwelijks nog merkt hoe hij leeft. Zij trekken de vraag door naar de angst om te sterven. Wat willen we precies beschermen als onze dagen vooral bestaan uit verstrooiing, geroddel of ongebruikte mogelijkheden? Het voorbeeld nodigt uit om bewuster deel te nemen aan het leven dat je wilt behouden.", "reflectionNl": "Welk deel van je dag zou je missen om wat het je werkelijk geeft, los van de gewoonte?", "exerciseNl": "Vervang één halfuur op de automatische piloot door iets waarbij je bewust aanwezig kunt zijn.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "12-24": {"dateKey": "12-24", "day": 24, "month": 12, "sourceTitle": "MEANINGLESS . . . LIKE A FINE WINE", "thinker": "Seneca", "thoughtNl": "Geniet van iets bijzonders terwijl het er is, zonder je eigen waarde aan bezit of verfijnde smaak te verbinden.", "explanationNl": "De auteurs vermoeden dat Seneca zelf best van een goed glas hield. Zijn boodschap lezen ze als een kwestie van verhouding: een fijne wijn, mooie techniek of een verfijnde hobby kan plezier geven, terwijl verzamelen, besteden en vergelijken weinig zeggen over de waarde van je leven. Je omgang met zulke spullen is bovendien tijdelijk. Holiday en Hanselman gebruiken die gedachte om de aantrekkingskracht te matigen wanneer plezier omslaat in een sterk verlangen om steeds meer te bezitten of te weten.", "reflectionNl": "Welke hobby geeft je minder plezier zodra bezit of vergelijking er belangrijker wordt?", "exerciseNl": "Geniet vandaag van iets wat je al hebt zonder ondertussen naar een nieuwere of betere versie te zoeken.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "12-25": {"dateKey": "12-25", "day": 25, "month": 12, "sourceTitle": "DON’T BURN THE CANDLE AT BOTH ENDS", "thinker": "Seneca", "thoughtNl": "Rust helpt je om helder te denken wanneer het leven iets moeilijks vraagt. Bewaar vandaag ruimte voor herstel.", "explanationNl": "Holiday en Hanselman vergelijken hoe Marcus Aurelius en Seneca in hun teksten overkomen. Marcus klinkt hun soms uitgeput in de oren, terwijl Seneca studie en inspanning volgens hen met rust wist af te wisselen. Ze vergelijken de geest met een spier die je kunt overbelasten. De uitputting van John Henry in het volksverhaal versterkt dat beeld. Je zult vaker aandacht, geduld en creativiteit nodig hebben dan alleen vandaag. Daarvoor is het belangrijk dat je lichaam en geest tussendoor herstellen.", "reflectionNl": "Welk teken van vermoeidheid negeer je terwijl je binnenkort helder en geduldig moet kunnen handelen?", "exerciseNl": "Plan vandaag één korte onderbreking waarin je geen extra taak probeert af te ronden.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "12-26": {"dateKey": "12-26", "day": 26, "month": 12, "sourceTitle": "LIFE IS LONG—IF YOU KNOW HOW TO USE IT", "thinker": "Seneca", "thoughtNl": "Als je tijd tekortkomt, kijk dan ook naar wat je hebt toegezegd en waar je uren ongemerkt naartoe gaan.", "explanationNl": "De auteurs stellen de ervaring van tijdgebrek naast de vraag hoe we onze tijd besteden. Ze verwijzen naar Petrarca, die mensen bekritiseerde die hun energie aan uiterlijke zaken verloren zonder het zelf te merken. Wachten in het verkeer is hun voorbeeld van kleine hoeveelheden tijd die zich jarenlang opstapelen. Hetzelfde kan gelden voor ruzies of verstrooiing. Holiday en Hanselman nodigen je uit om vóór je concludeert dat je tijd tekortkomt, te onderzoeken welke bezigheden werkelijk belangrijk zijn en welke onnodig beslag leggen.", "reflectionNl": "Welke terugkerende bezigheid zou je heroverwegen als je wist hoeveel tijd ze je op jaarbasis kost?", "exerciseNl": "Schat de wekelijkse duur van één gewoonte en beslis of je daar vandaag iets aan wilt veranderen.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "12-27": {"dateKey": "12-27", "day": 27, "month": 12, "sourceTitle": "DON’T LET YOUR SOUL GO FIRST", "thinker": "Marcus Aurelius", "thoughtNl": "Ook met minder lichamelijke kracht kun je trouw blijven aan een waarde die voor jou belangrijk is.", "explanationNl": "Holiday en Hanselman halen historicus Cassius Dio aan over de lichamelijke zwakte en problemen tijdens het bewind van Marcus Aurelius. Toen Marcus ernstig ziek was, ging zelfs het gerucht dat hij dood was en riep een generaal zichzelf uit tot keizer. De auteurs noemen ook oorlog en zorgen over zijn zoon. Ze bewonderen dat Marcus zijn principes bleef volgen ondanks die belasting. Ze maken onderscheid tussen een lichaam dat kracht verliest en de bereidheid om onder moeilijke omstandigheden naar je waarden te handelen.", "reflectionNl": "Welke waarde kun je ook op een dag met weinig energie nog op een bescheiden manier naleven?", "exerciseNl": "Kies voor die waarde één concrete handeling die past bij hoeveel je vandaag aankunt.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "12-28": {"dateKey": "12-28", "day": 28, "month": 12, "sourceTitle": "ON BEING REMEMBERED", "thinker": "Marcus Aurelius", "thoughtNl": "Zelfs grote bekendheid verdwijnt geleidelijk, want ook de mensen die zich jouw naam herinneren leven maar tijdelijk.", "explanationNl": "Langs de route naar de openbare bibliotheek van New York ligt een plaat met een uitspraak van Marcus over herinneren en herinnerd worden. Holiday en Hanselman beschrijven de vele ooit invloedrijke architecten, weldoeners en bestuurders die bij de bibliotheek betrokken waren. Hun namen staan soms nog op het gebouw, terwijl veel voorbijgangers hen niet meer herkennen. De auteurs zien zelfs Marcus als deel van dat verschijnsel. Roem hangt af van mensen die zich iets herinneren, en ook hun tijd eindigt.", "reflectionNl": "Welke keuze zou je vandaag maken als latere erkenning voor je werk geen rol speelde?", "exerciseNl": "Doe één kleine nuttige handeling die voor jou waarde heeft ook als niemand weet dat jij haar deed.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "12-29": {"dateKey": "12-29", "day": 29, "month": 12, "sourceTitle": "GIVE THANKS", "thinker": "Seneca", "thoughtNl": "Dankbaarheid kan beginnen bij iets kleins dat je vandaag opmerkt en je aandacht voor de rest van de dag veranderen.", "explanationNl": "Holiday en Hanselman beginnen met grote redenen voor dankbaarheid, zoals leven en de ruimte hebben om te lezen. Daarna richten ze de aandacht op kleine gebeurtenissen: een deur die iemand openhoudt, een glimlach of muziek die je graag hoort. Volgens hen kan die aandacht zich door je dag verspreiden. Ze vragen of er zelfs op je laatste dag nog dingen zouden zijn die je kon waarderen. Daarmee nodigen ze uit dankbaarheid vanaf de ochtend mee te nemen in gewone momenten.", "reflectionNl": "Welke kleine vriendelijkheid zou je vandaag gemakkelijk missen als je alleen let op wat er misging?", "exerciseNl": "Bedank vandaag iemand voor een concreet gebaar dat je gewoonlijk vanzelfsprekend vindt.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "12-30": {"dateKey": "12-30", "day": 30, "month": 12, "sourceTitle": "TAKING THE BITE OUT OF IT", "thinker": "Seneca", "thoughtNl": "Je kunt de zwaarte van een moeilijke situatie verminderen door er met een rustige, weloverwogen houding in te stappen.", "explanationNl": "Holiday en Hanselman wijzen op mensen die onder kritiek, verlies of druk blijven functioneren. Zij verklaren hun houding vanuit geoefende rust en discipline. Je kunt die rust volgens hen ontwikkelen door mogelijke tegenslag vooraf rustig te overdenken. De auteurs passen dezelfde oefening toe op sterfelijkheid, waarvan tijdstip en verloop onzeker blijven. Voor die grootste beproeving achten ze een kalme, redelijke geest belangrijker dan een beroep op religie of op woorden van filosofen. Die geest kun je in kleinere situaties al oefenen.", "reflectionNl": "Welke naderende moeilijkheid kun je vooraf rustig bekijken zodat ze je minder overvalt?", "exerciseNl": "Stel je één plausibel lastig moment voor en kies een zin waarmee je jezelf dan rustig kunt toespreken.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"},
  "12-31": {"dateKey": "12-31", "day": 31, "month": 12, "sourceTitle": "GET ACTIVE IN YOUR OWN RESCUE", "thinker": "Marcus Aurelius", "thoughtNl": "Zet één inzicht om in een keuze vandaag, zodat je studie werkelijk iets verandert aan hoe je leeft.", "explanationNl": "Lezen en studeren dienen volgens Holiday en Hanselman om goed te leven en uiteindelijk goed te sterven. Op enig moment moet je de bladzijde omslaan naar wat je daadwerkelijk doet. Ze verwijzen naar Seneca's oproep om woorden zichtbaar te maken in daden en gebruiken het beeld van de geleerde die ook soldaat moet kunnen zijn. Wat morgen brengt en hoeveel tijd je hebt, blijft onbekend. Daarom leggen zij de volgende stap bij het nemen van een concrete, weloverwogen beslissing.", "reflectionNl": "Welk inzicht uit dit jaar wacht nog op één daad die laat zien dat je het serieus neemt?", "exerciseNl": "Voer vóór het einde van de dag één kleine handeling uit die bij dat inzicht past.", "bookAttribution": "Ryan Holiday & Stephen Hanselman — The Daily Stoic"}
};
